  AvgCommunicate_134108_Option_17 = {
    Text = "Because you're important to me."
  },
  AvgCommunicate_134108_Option_4 = {
    Text = "Oh, really."
  },
  AvgCommunicate_134109_Content_1 = {
    Text = "Kiiper, I saw this black tunnel..."
  },
  AvgCommunicate_134109_Content_10 = {
    Text = "Nah. Didn't get any bad vibes from them. Actually, I felt really good. And... it feels like I can just be any one of 'em."
  },
  AvgCommunicate_134109_Content_11 = {
    Text = "You mean you're linked to their souls?"
  },
  AvgCommunicate_134109_Content_12 = {
    Text = "Yeah. I felt myself split into a hundred pieces at once, zipping through twisty pipes, under messy junk and low furniture..."
  },
  AvgCommunicate_134109_Content_13 = {
    Text = "You're just remembering the old days. It's fine. That's all in the past now."
  },
  AvgCommunicate_134109_Content_14 = {
    Text = "And then I realized—I can make 'em swipe whatever I want!"
  },
  AvgCommunicate_134109_Content_15 = {
    Text = "If I'd had this power back then, I could've cleaned out the biggest bank in the West District! Hah! Now I'm basically the greatest thief in the country... no, the whole world! Nobody's gonna stop me now!"
  },
  AvgCommunicate_134109_Content_17 = {
    Text = "Guess calling the cops won't do anything now. I'd better go ask Doll to set up some security cams."
  },
  AvgCommunicate_134109_Content_2 = {
    Text = "There's no light, no time, and I just kept walking, all alone. Felt like I'd been walking forever."
  },
  AvgCommunicate_134109_Content_3 = {
    Text = "You okay? Did you get lost in the void again?"
  },
  AvgCommunicate_134109_Content_4 = {
    Text = "I walked and walked, and then I finally saw something—like a little light or smoke. Then it slowly turned into Brown! Its eyes, tiny and round, just shining in the dark."
  },
  AvgCommunicate_134109_Content_5 = {
    Text = "Then eyes everywhere. All around me, like they were... keeping me company."
  },
  AvgCommunicate_134109_Content_6 = {
    Text = "Sounds like a swarm of rats?"
  },
  AvgCommunicate_134109_Content_7 = {
    Text = "Yeah. But they felt like more than just rats—like they had souls... like the street kids I grew up with. We'd fight, we'd team up, we're all broke and hungry... running through the alleys just like rats."
  },
  AvgCommunicate_134109_Content_8 = {
    Text = "Maybe those kids' souls were there with you."
  },
  AvgCommunicate_134109_Content_9 = {
    Text = "Hah? Hold on, I still owe Joe a drumstick, little Jones two slices of bread, and I swiped a few marbles from Johnny... They ain't here to collect, are they?!"
  },
  AvgCommunicate_134109_Option_11 = {
    Text = "You can feel what they feel?"
  },
  AvgCommunicate_134109_Option_13 = {
    Text = "That's all behind you now."
  },
  AvgCommunicate_134109_Option_17 = {Text = "..."},
  AvgCommunicate_134109_Option_3 = {
    Text = "Are you okay?"
