  AvgCommunicate_134109_Option_8 = {
    Text = "Maybe it was them."
  },
  AvgCommunicate_134110_Content_1 = {
    Text = "Ah, ah... AHHHHH! Black, it's all black!"
  },
  AvgCommunicate_134110_Content_10 = {
    Text = "It hasn't...? The black demon didn't come?"
  },
  AvgCommunicate_134110_Content_11 = {
    Text = "But... if we're living inside the demon's belly... sooner or later, the black'll swallow us whole. We can't escape, there's no escape!"
