  AvgCommunicate_134110_Content_15 = {
    Text = "I don't fully get what you're saying... but if the world really is destined to end, at least I—and everyone at Mythag—will fight until the very last breath."
  },
  AvgCommunicate_134110_Content_16 = {
    Text = "If the Dissolution is truly inevitable... I'll find you the last patch of light. And I'll stay right there with you, until the very end."
