  },
  AvgCommunicate_134112_Content_1 = {
    Text = "Wow, so that's what the world looks like through your eyes."
  },
  AvgCommunicate_134112_Content_10 = {
    Text = "Humans really have that many expressions? Guess I've got a poker face."
  },
  AvgCommunicate_134112_Content_11 = {
    Text = "And that's not all! I've also learned crying while smiling, crying while angry, smiling while angry, laughing while terrified..."
  },
  AvgCommunicate_134112_Content_12 = {
