  AvgCommunicate_134112_Content_13 = {
    Text = "Wanna see? Casiah can even act out \"love\"—the big human mystery!"
  },
  AvgCommunicate_134112_Content_15 = {
    Text = "Not even close—and you're looking even less human right now! You're freaking me out—stop it! STOP!"
  },
  AvgCommunicate_134112_Content_2 = {
    Text = "What do you mean?"
