    Text = "Liz... are you still thinking about that fire all those years ago?"
  },
  AvgCommunicate_134114_Content_5 = {
    Text = "My hatred has burned away in the flames. But... I have no right to forgive that fire on anyone else's behalf."
  },
  AvgCommunicate_134114_Content_6 = {
    Text = "I have no regrets. And I won't look away from the faces I see in the fire."
  },
  AvgCommunicate_134114_Content_7 = {
