  AvgCommunicate_134118_Content_5 = {
    Text = "I mean, it’s not like life is that scary anymore, but you can never have too much power. It’s a security thing."
  },
  AvgCommunicate_134118_Content_6 = {
    Text = "Might makes right, after all!"
  },
  AvgCommunicate_134118_Content_7 = {
    Text = "But using all this power on mere busywork for Mythag feels like such a waste... Oh, I've got it!"
  },
  AvgCommunicate_134118_Content_8 = {
    Text = "Since all these tentacles can work independently, I’ll just open my own bakery! I can do the work of eight people all by myself. I'll have unlimited cake for life!"
  },
  AvgCommunicate_134118_Content_9 = {
    Text = "You’re going to use it for <Italic:that>?"
  },
  AvgCommunicate_134118_Option_14 = {
    Text = "I have to eat too?"
  },
  AvgCommunicate_134118_Option_17 = {Text = "So..."},
  AvgCommunicate_134118_Option_4 = {Text = "Go Murphy!"},
  AvgCommunicate_134118_Option_9 = {
    Text = "You’re going to use it for <Italic:that>?"
  },
  AvgCommunicate_134119_Content_1 = {
    Text = "Hahaha... Hahahaha!"
  },
  AvgCommunicate_134119_Content_10 = {
    Text = "Before absolute might, conquest is but a long, entertaining game."
  },
  AvgCommunicate_134119_Content_11 = {
    Text = "Whatever makes you happy..."
  },
  AvgCommunicate_134119_Content_12 = {
    Text = "Time will bring you news of my triumphs. When that day comes, as the prime architect of my new kingdom, I shall grant you a fief of the most fertile land."
  },
  AvgCommunicate_134119_Content_13 = {
    Text = "Or... perhaps you'd prefer that drab, gray city of Londinium?"
  },
  AvgCommunicate_134119_Content_2 = {
    Text = "You haven't let all that power go to your head and gone crazy, have you?"
  },
  AvgCommunicate_134119_Content_3 = {
    Text = "Hmph. As the one who contributed most to my strength, I can forgive your minor impudence."
  },
  AvgCommunicate_134119_Content_4 = {
    Text = "Ah... the moment I've long awaited. This familiar sweetness, this surge of blood through my veins!"
  },
  AvgCommunicate_134119_Content_5 = {
    Text = "I can now effortlessly lift icebergs and cleave through the ocean's depths."
  },
  AvgCommunicate_134119_Content_6 = {
    Text = "No tribal chief or seafaring warrior could stand against me for a single second. Even that madwoman can no longer suppress me."
  },
  AvgCommunicate_134119_Content_7 = {
    Text = "Soon, I shall conquer the seas, and then all the lands! Hahahaha!"
  },
  AvgCommunicate_134119_Content_8 = {
    Text = "Self-confidence is one thing, but don't be so conceited! This is straight-up delusional!"
  },
  AvgCommunicate_134119_Content_9 = {
    Text = "You know nothing of a giant's power, little one."
  },
  AvgCommunicate_134119_Option_11 = {
    Text = "Whatever makes you happy..."
  },
  AvgCommunicate_134119_Option_2 = {
    Text = "Have you lost your mind?"
  },
  AvgCommunicate_134119_Option_8 = {Text = "..."},
  AvgCommunicate_134120_Content_1 = {
    Text = "My singing... it's different now."
  },
  AvgCommunicate_134120_Content_10 = {
    Text = "Yes. I will."
  },
  AvgCommunicate_134120_Content_11 = {
    Text = "Oh, Keeper, after our talk, I signed with a record label. My first album's officially out now, and... and it's selling quite well."
  },
  AvgCommunicate_134120_Content_12 = {
    Text = "That’s awesome! Congrats! How many copies sold?"
  },
  AvgCommunicate_134120_Content_13 = {
    Text = "About a hundred thousand. But I don't need this planet's currency anyway. Since that's all I have to give... I'll just transfer the album's profits to you."
  },
  AvgCommunicate_134120_Content_14 = {Text = "Hooray!!!"},
  AvgCommunicate_134120_Content_2 = {
    Text = "Keeper, after you helped me grasp the Absolute Axiom, my voice seems to resonate with the Ether in a wonderful way."
  },
  AvgCommunicate_134120_Content_3 = {
    Text = "Sounds like you've gotten stronger! Faint would be so happy!"
  },
  AvgCommunicate_134120_Content_4 = {
    Text = "How can I ever repay you, Keeper? Seeing my sister again was already more than I ever dreamed of. And now you've given me something this precious."
  },
  AvgCommunicate_134120_Content_5 = {
    Text = "I don't have much to give, and I'm not a star anymore. The only thing I can offer... please, let me sing you a song."
  },
  AvgCommunicate_134120_Content_6 = {
    Text = "Tinct, you've already found your own path. If you really wanna do something for me..."
  },
  AvgCommunicate_134120_Content_7 = {
    Text = "Please sing freely, for yourself, and for me."
  },
  AvgCommunicate_134120_Content_8 = {
    Text = "Not to please anyone. Not to perform for anyone’s demands. Just sing because it makes you happy."
  },
  AvgCommunicate_134120_Content_9 = {
    Text = "Make me... happy."
  },
  AvgCommunicate_134120_Option_12 = {
    Text = "That's great news!"
  },
  AvgCommunicate_134120_Option_14 = {
    Text = "Wait, what?!"
  },
  AvgCommunicate_134120_Option_3 = {
    Text = "That's amazing."
  },
  AvgCommunicate_134120_Option_6 = {
    Text = "Have you thought about..."
  },
  AvgCommunicate_134180_Content_1 = {
    Text = "The wind fills the sails, and the birds fly alongside us in formation..."
  },
  AvgCommunicate_134180_Content_10 = {
    Text = "I want to sail the seas forever with you, the captain, and everyone else."
  },
  AvgCommunicate_134180_Content_11 = {
    Text = "Sailing through sunny and rainy days together, docking at all sorts of ports in different countries."
  },
  AvgCommunicate_134180_Content_12 = {
    Text = "Fishing together, grilling our catch... and maybe even plucking mussels off the hull to stew in red wine."
  },
  AvgCommunicate_134180_Content_13 = {
    Text = "Let's do it on our next holiday."
  },
  AvgCommunicate_134180_Content_14 = {
    Text = "I've thought about it for a long time... sailing is when I'm at my happiest."
  },
  AvgCommunicate_134180_Content_15 = {
    Text = "I'll steer us clear of every storm so we can keep sailing together, happy and free."
  },
  AvgCommunicate_134180_Content_16 = {
    Text = "It sounds lovely, but if we never stop sailing, everyone except the Aequor Awakeners is going to get seasick!"
  },
  AvgCommunicate_134180_Content_2 = {
    Text = "I see the bow breaking the waves, I hear the sailors' shanties, and I feel the hints of the wind and rain."
  },
  AvgCommunicate_134180_Content_3 = {
    Text = "I can see the course to calm, placid waters more clearly now."
  },
  AvgCommunicate_134180_Content_4 = {
    Text = "Congratulations, Celeste!"
  },
  AvgCommunicate_134180_Content_5 = {
    Text = "Now, I might truly be able to fulfill everyone's wishes and guide the ships under my protection safely to the other shore."
  },
  AvgCommunicate_134180_Content_6 = {
    Text = "I won't let anyone down again."
  },
  AvgCommunicate_134180_Content_7 = {
    Text = "And what about your wish? Have you thought about what you want?"
  },
  AvgCommunicate_134180_Content_8 = {Text = "My wish..."},
  AvgCommunicate_134180_Content_9 = {
    Text = "I've made up my mind."
  },
  AvgCommunicate_134180_Option_13 = {
    Text = "Let's do it on our next holiday."
  },
  AvgCommunicate_134180_Option_16 = {
    Text = "That sounds wonderful."
  },
  AvgCommunicate_134180_Option_4 = {
    Text = "Congratulations!"
  },
  AvgCommunicate_134180_Option_7 = {
    Text = "And what about you?"
  },
  AvgCommunicate_134181_Content_1 = {
    Text = "Ah... the call of the ocean. So gentle, so warm."
  },
  AvgCommunicate_134181_Content_10 = {
    Text = "Did Rogers' brutish behavior leave a scar on you? Or do you really think I'm such a hack and lazy artist?"
  },
  AvgCommunicate_134181_Content_11 = {
    Text = "There are no shortcuts in the craft of creation. My sculptures are carved by my own hand, one stroke at a time."
  },
  AvgCommunicate_134181_Content_12 = {
    Text = "Don't worry, I won't touch a single hair on your head."
  },
  AvgCommunicate_134181_Content_13 = {
    Text = "Haha... Maybe your skills are just too brilliant. Every time I see your work, I get the feeling that I'm looking at someone alive."
  },
  AvgCommunicate_134181_Content_14 = {
    Text = "Hmm... Well, now that my strength has reached its peak, I might actually be able to create a sculpture that comes to life."
  },
  AvgCommunicate_134181_Content_15 = {
    Text = "In the dead of night, when you aren't looking, the sculpture's eyes will slowly turn, and the corners of its mouth will curl into a smile..."
  },
  AvgCommunicate_134181_Content_16 = {
    Text = "When I finish my latest piece, I'll put one by your bedside to watch over you for me. How does that sound?"
  },
  AvgCommunicate_134181_Content_17 = {
    Text = "I'll never be able to sleep again!!"
  },
  AvgCommunicate_134181_Content_18 = {
    Text = "Just kidding."
  },
  AvgCommunicate_134181_Content_19 = {
    Text = "Looks like you're really afraid of such a simple spooky story. How adorable."
  },
  AvgCommunicate_134181_Content_2 = {
    Text = "You hear it too, don't you?"
  },
  AvgCommunicate_134181_Content_3 = {
    Text = "It's inviting us. They are waiting for us... to go to the pure white palace at the bottom of the sea together."
  },
  AvgCommunicate_134181_Content_4 = {
    Text = "Who? I think I might be going deaf; I didn't hear a thing."
  },
  AvgCommunicate_134181_Content_5 = {
    Text = "Then this is a Muse's Kiss meant only for me. The beauty of the ocean has finally merged with my soul."
  },
  AvgCommunicate_134181_Content_6 = {
    Text = "You always bring me fresh inspiration. I find myself liking you more and more."
  },
  AvgCommunicate_134181_Content_7 = {
    Text = "Why not consider becoming my long-term assistant? You wouldn't have to do anything—just drop by my studio every day, have some tea, and chat."
  },
  AvgCommunicate_134181_Content_8 = {
    Text = "I'm honored, but... will I wake up one day to find I've become a stone statue?"
  },
  AvgCommunicate_134181_Content_9 = {
    Text = "Hehe, is that really how you see me?"
  },
  AvgCommunicate_134181_Option_13 = {
    Text = "Your craftsmanship is just too good."
  },
  AvgCommunicate_134181_Option_17 = {
    Text = "No, please!"
  },
  AvgCommunicate_134181_Option_4 = {
    Text = "I don't hear anything."
  },
  AvgCommunicate_134181_Option_8 = {
    Text = "Will I be turned into a sculpture?"
  },
  AvgCommunicate_134187_Content_1 = {
    Text = "How have you been lately, little pup?"
  },
  AvgCommunicate_134187_Content_10 = {
    Text = "Don't do anything rash. No matter what, the Black Pool will keep you firmly imprisoned."
  },
  AvgCommunicate_134187_Content_11 = {
    Text = "You have absolutely no idea what kind of power knowledge can grant me."
  },
  AvgCommunicate_134187_Content_12 = {
    Text = "I'm very pleased with this gift. So, my dearest student, I'm going to give you a gift in return."
  },
  AvgCommunicate_134187_Content_13 = {Text = "...?"},
  AvgCommunicate_134187_Content_14 = {
    Text = "Guess. Guess just how much I can achieve now."
  },
  AvgCommunicate_134187_Content_15 = {
    Text = "Guess whether your arrogant attempts to restrict me will actually work."
  },
  AvgCommunicate_134187_Content_16 = {
    Text = "Guess whether the truth I've glimpsed will be implanted into everyone's consciousness now that I have this power."
  },
  AvgCommunicate_134187_Content_17 = {
    Text = "This is your most important homework assignment. Very soon, I'll be coming to grade it myself."
  },
  AvgCommunicate_134187_Content_2 = {
    Text = "You've got quite the nerve. I never expected you to send a gift of this caliber."
  },
  AvgCommunicate_134187_Content_3 = {
    Text = "Would you believe me if I said there was a serious accident while transporting rare materials...?"
  },
  AvgCommunicate_134187_Content_5 = {
    Text = "You underestimated me, and you underestimated Mythag."
  },
  AvgCommunicate_134187_Content_6 = {
    Text = "We are willing to let every Awakener touch that limit, because we will try every method to stop destruction."
  },
  AvgCommunicate_134187_Content_7 = {
    Text = "This is where Ms. Doll and the rest of us differ from you most. Even if destruction is inevitable, we will never bow to it."
  },
  AvgCommunicate_134187_Content_8 = {
    Text = "Ugh, I never realized Mythag’s education system produced such idiots."
  },
  AvgCommunicate_134187_Content_9 = {
    Text = "Fortunately, you're such a pitifully cute idiot that it's hard not to feel a certain fondness for you."
  },
  AvgCommunicate_134187_Option_13 = {Text = "...?"},
  AvgCommunicate_134187_Option_3 = {
    Text = "It was an accident."
  },
  AvgCommunicate_134187_Option_5 = {
    Text = "It's the thought that counts."
  },
  AvgCommunicate_134188_Content_1 = {
    Text = "This power is amazing! Bang! Boom! Kaboom!"
  },
  AvgCommunicate_134188_Content_11 = {
    Text = "In that case, the school's repair costs should drop significantly this month..."
  },
  AvgCommunicate_134188_Content_12 = {
    Text = "Bad homework appears! Vortice... kill it!"
  },
  AvgCommunicate_134188_Content_13 = {
    Text = "No, you can't count homework as an enemy!"
  },
  AvgCommunicate_134188_Content_14 = {
    Text = "Vortice? Vortice?"
  },
  AvgCommunicate_134188_Content_16 = {
    Text = "Keeper, this is Nautila. Rest assured, Vortice is pinned down. Both the homework and the classroom are safe."
  },
  AvgCommunicate_134188_Content_17 = {
    Text = "Thank goodness..."
  },
  AvgCommunicate_134188_Content_18 = {
    Text = "Mythag, Vortice, and I will always need you, Nautila."
  },
  AvgCommunicate_134188_Content_2 = {
    Text = "Remember the first rule of the Mythag Code, Vortice-Specific Edition: under no circumstances are you permitted to point a lethal weapon at anyone in Mythag."
  },
  AvgCommunicate_134188_Content_5 = {
    Text = "%player%, don't worry. Vortice... can control!"
  },
  AvgCommunicate_134188_Content_6 = {
    Text = "Vortice... hold back... vortex."
  },
  AvgCommunicate_134188_Content_7 = {
    Text = "Vortice... friend... hug."
  },
  AvgCommunicate_134188_Content_8 = {
    Text = "Vortice... enemy... Bang! Boom! Kaboom!"
  },
  AvgCommunicate_134188_Option_2 = {
    Text = "Safety first."
  },
  AvgCommunicate_134189_Content_1 = {
    Text = "We are comrades-in-arms, so I won't say thank you."
  },
  AvgCommunicate_134189_Content_2 = {
    Text = "My weapon is sharpened to its finest edge—sharp enough to slit a slave-driver's throat in an instant."
  },
  AvgCommunicate_134189_Content_3 = {
    Text = "The meaning of resistance, of revenge, of battle... I am still pondering them even now."
  },
  AvgCommunicate_134189_Content_4 = {
    Text = "Perhaps I will spend the rest of my life seeking those answers, until the day I can no longer stand."
  },
  AvgCommunicate_134189_Content_5 = {
    Text = "At least I am no longer lost."
  },
  AvgCommunicate_134189_Content_6 = {
    Text = "To my comrades-in-arms."
  },
  AvgCommunicate_134189_Content_7 = {
    Text = "To my comrades-in-arms. It was you who set my soul free and gave me the resolve to keep moving forward."
  },
  AvgCommunicate_134189_Content_8 = {
    Text = "Whenever you need me, I will have your back and fight by your side."
  },
  AvgCommunicate_134189_Content_9 = {
    Text = "Let’s keep fighting together—for the sake of righteous vengeance and for the sheer thrill of battle."
  },
  AvgCommunicate_134189_Option_6 = {
    Text = "To my comrades."
  },
  AvgCommunicate_134201_Content_1 = {
    Text = "Keeper, I have submitted an application to the Academic Affairs Office. I will be absent from training for the next three days."
  },
  AvgCommunicate_134201_Content_10 = {
    Text = "But after crossing that limit, I understood."
  },
  AvgCommunicate_134201_Content_11 = {
    Text = "Understood what?"
  },
  AvgCommunicate_134201_Content_13 = {
    Text = "I am the forerunner. I am the blade. This is precisely because I have always stayed on this path. That is how I met everyone, and how I met you."
  },
  AvgCommunicate_134201_Content_14 = {
    Text = "My pursuit ensures I am never alone. We may never truly arrive, but as long as we persevere, I can bring that ideal, fair world closer—just a little bit closer."
  },
  AvgCommunicate_134201_Content_15 = {
    Text = "I shall use my body as a blade until we reach a utopia where everyone can live in the light."
  },
  AvgCommunicate_134201_Content_16 = {
    Text = "What a grand vision, Instructor. I'll support you unconditionally!"
  },
  AvgCommunicate_134201_Content_17 = {
    Text = "Wonderful. In that case, I will use these three days to develop a much more rigorous and difficult training plan."
  },
  AvgCommunicate_134201_Content_18 = {
    Text = "You'll be among the first to undergo it. Don’t worry; I will be there to spar with you and help everyone improve."
  },
  AvgCommunicate_134201_Content_19 = {
    Text = "Wait, I think we can talk this over a bit more..."
  },
  AvgCommunicate_134201_Content_2 = {
    Text = "Is there a problem with the materials? Are you okay? Do you need help?"
  },
  AvgCommunicate_134201_Content_3 = {
    Text = "No, quite the opposite. Everything is going smoothly. I have achieved a breakthrough unlike any before."
  },
  AvgCommunicate_134201_Content_4 = {
    Text = "I’m not sure I follow..."
  },
  AvgCommunicate_134201_Content_5 = {
    Text = "After leaving the military... I drifted for a long time."
  },
  AvgCommunicate_134201_Content_6 = {
    Text = "I didn’t know what I was fighting for. The only thing I could follow was a sense of justice that I wasn't even sure could be achieved."
  },
  AvgCommunicate_134201_Content_7 = {
    Text = "I wanted to stand on the side of the weak, the voiceless, and those treated unfairly."
  },
  AvgCommunicate_134201_Content_8 = {
    Text = "But I also knew in my heart that no matter how strong I became, there would always be things beyond my power—just as I couldn't prevent the fall of Aram, even if time flowed backward."
  },
  AvgCommunicate_134201_Content_9 = {Text = "Alva..."},
  AvgCommunicate_134201_Option_2 = {
    Text = "Did something happen?"
  },
  AvgCommunicate_134202_Content_1 = {
    Text = "Thank you for giving such a precious thing to me, %player%."
  },
  AvgCommunicate_134202_Content_10 = {
    Text = "I think it is telling me that instead of just leaving shadows in my memory, the world can be measured by my footsteps."
  },
  AvgCommunicate_134202_Content_11 = {
    Text = "If I can't hold onto it, I'll just keep moving forward. The world and all of you will remember for me."
  },
  AvgCommunicate_134202_Content_12 = {
    Text = "Even I'm getting fired up..."
  },
  AvgCommunicate_134202_Content_13 = {
    Text = "I’m going to be the greatest explorer and the most skilled mechanical master! %player%, I want to officially invite you."
  },
  AvgCommunicate_134202_Content_14 = {
    Text = "Once everything is resolved, please come explore with me and create more precious memories in this world."
  },
  AvgCommunicate_134202_Content_15 = {
    Text = "That day might be far off, or it might be tomorrow."
  },
  AvgCommunicate_134202_Content_16 = {
    Text = "This invitation stands forever. And this time, I will remember."
  },
  AvgCommunicate_134202_Content_2 = {
    Text = "I processed it for a long time... it makes me feel as if I've become whole again."
  },
  AvgCommunicate_134202_Content_3 = {
    Text = "Does that mean you won't forget things anymore?"
  },
  AvgCommunicate_134202_Content_4 = {
    Text = "Hmm, let me think..."
  },
  AvgCommunicate_134202_Content_5 = {
    Text = "Haha, I still can’t remember!"
  },
  AvgCommunicate_134202_Content_6 = {
    Text = "Why do you sound so proud of that?!"
  },
  AvgCommunicate_134202_Content_7 = {
    Text = "Because even if I still forget many things, %player% will always be there to remind me of both the past and the present."
  },
  AvgCommunicate_134202_Content_8 = {
    Text = "Who I am, where I am, and what I must do—the people I trust most will tell me those things."
  },
  AvgCommunicate_134202_Content_9 = {
    Text = "Perhaps that is why, after understanding the Absolute Axiom, my memory hasn't improved, but the whole world feels like a vast map unfolding before me."
  },
  AvgCommunicate_134202_Option_3 = {
    Text = "Has your memory improved?"
  },
  AvgCommunicate_134208_Content_1 = {
    Text = "I once thought that only by playing the role of an observer could I experience the joy of the unknown."
  },
  AvgCommunicate_134208_Content_10 = {
    Text = "I don't fully understand... but it sounds like a good thing?"
  },
  AvgCommunicate_134208_Content_11 = {
    Text = "Since leaving that doorway, this is the greatest blessing I have encountered."
  },
  AvgCommunicate_134208_Content_12 = {
    Text = "Keeper, this is a surprise you gave me that I could never have foreseen."
  },
  AvgCommunicate_134208_Content_13 = {
    Text = "Fate never fails to favor a generous soul."
  },
  AvgCommunicate_134208_Content_14 = {
    Text = "I cannot touch your threads, but while you fight for destiny, my spinning wheel will forever turn for you."
  },
  AvgCommunicate_134208_Content_2 = {
    Text = "It has been a long, long time since I experienced this feeling..."
  },
  AvgCommunicate_134208_Content_3 = {
    Text = "What feeling?"
  },
  AvgCommunicate_134208_Content_4 = {Text = "Novelty."},
  AvgCommunicate_134208_Content_5 = {
    Text = "The quiet growth of flower buds, the intertwining of words on paper, the gentle flow of clouds in the wind..."
  },
  AvgCommunicate_134208_Content_6 = {
    Text = "And of course, people. Open arms, falling tears, and heartbeats that sound like war drums or raindrops..."
  },
  AvgCommunicate_134208_Content_7 = {
    Text = "I see more than before, but my eyes are closer to the earth."
  },
  AvgCommunicate_134208_Content_8 = {
    Text = "It no longer lingers in the sky, Keeper. It has descended to every street, to the side of every passerby."
  },
  AvgCommunicate_134208_Content_9 = {
    Text = "Now, I do not need to play a role. I can truly exist as an individual."
  },
  AvgCommunicate_134208_Option_10 = {
    Text = "That sounds like a good thing?"
  },
  AvgCommunicate_134208_Option_3 = {
    Text = "What feeling?"
  },
  AvgCommunicate_134242_Content_1 = {
    Text = "Suggested Translation"
  },
  AvgCommunicate_134245_Content_1 = {
    Text = "It looks like something precious. Is it really okay to let me have it?"
  },
  AvgCommunicate_134245_Content_12 = {
    Text = "I see this world has its beautiful side, too. It's a little different from what I remember though."
  },
  AvgCommunicate_134245_Content_13 = {
    Text = "The way it's structured, the logic holding it together... Saya understands it all."
  },
  AvgCommunicate_134245_Content_14 = {
    Text = "So... I think I can rewrite it to be just like the world in my memories now. It shouldn't be too hard."
  },
  AvgCommunicate_134245_Content_16 = {
    Text = "I know you're joking, but please, absolutely not."
  },
  AvgCommunicate_134245_Content_17 = {Text = "..."},
  AvgCommunicate_134245_Content_18 = {
    Text = "Hello? Why are you suddenly quiet? It was a joke, right? Please, say something!"
  },
  AvgCommunicate_134245_Content_19 = {
    Text = "Oh, I just left the room for a moment. To observe everyone with fresh eyes..."
  },
  AvgCommunicate_134245_Content_2 = {
    Text = "It's okay. I trust you."
  },
  AvgCommunicate_134245_Content_20 = {
    Text = "So this is what it feels like. To have people who care for me, still breathing, still alive."
  },
  AvgCommunicate_134245_Content_21 = {
    Text = "I can't quite put my finger on it, but I have a gut feeling something's really, really off."
  },
  AvgCommunicate_134245_Content_22 = {
    Text = "I bet you're making that face right now—that look when everything goes exactly as you planned!"
  },
  AvgCommunicate_134245_Content_23 = {
    Text = "Don't worry. I'll be nice to everyone here."
  },
  AvgCommunicate_134245_Content_24 = {
    Text = "Mm... though the world in my memories still feels more interesting. Maybe we could all go see it together? I think I could actually make that happen now."
  },
  AvgCommunicate_134245_Content_25 = {
    Text = "Now that sounds even scarier!"
  },
  AvgCommunicate_134245_Content_3 = {
    Text = "This should help you better understand our world, and hopefully push our research forward on how to stop the Dissolution."
  },
  AvgCommunicate_134245_Content_4 = {
    Text = "After all, you do pick things up alarmingly fast when it comes to research..."
  },
  AvgCommunicate_134245_Content_5 = {
    Text = "It was an accident... probably slipped through the inventory process. But I guess it's too late to take it back now?"
  },
  AvgCommunicate_134245_Content_6 = {
    Text = "Huh? Should I return it, then? I'm a little torn."
  },
  AvgCommunicate_134245_Content_7 = {
    Text = "Really? We can undo something like this?"
  },
  AvgCommunicate_134245_Content_8 = {
    Text = "Hmm, let me think..."
  },
  AvgCommunicate_134245_Content_9 = {
    Text = "My answer is—nope. I'm not doing it."
  },
  AvgCommunicate_134245_Option_2 = {Text = "It's okay."},
  AvgCommunicate_134245_Option_5 = {
    Text = "It was an accident."
  },
  AvgCommunicate_134246_Content_1 = {
    Text = "My dear, most beloved, most magnificent benefactor~"
  },
  AvgCommunicate_134246_Content_10 = {
    Text = "Let me check."
  },
  AvgCommunicate_134246_Content_11 = {
    Text = "Let me check your Gnostic Index fluctuation data."
  },
  AvgCommunicate_134246_Content_12 = {
    Text = "Well, would you look at that—Our Caraboo actually wasn't lying this time."
  },
  AvgCommunicate_134246_Content_13 = {
    Text = "Heh heh, believe poor little Caraboo now, don't you?"
  },
  AvgCommunicate_134246_Content_14 = {
    Text = "Please, keep investing generously in me—So that I can earn my dear benefactor a hundred, a thousand times the returns down the road!"
  },
  AvgCommunicate_134246_Content_15 = {
    Text = "Just eight more—no, five Enlightenment Shards! And I'll dazzle you all over again, I promise!"
  },
  AvgCommunicate_134246_Content_16 = {
    Text = "That's impossible."
  },
  AvgCommunicate_134246_Content_17 = {Text = "Nice try."},
  AvgCommunicate_134246_Content_18 = {
    Text = "Professor Doll told me that research into Awakener Enlightenment has already hit its ceiling. There won't be another breakthrough for a century."
  },
  AvgCommunicate_134246_Content_19 = {
    Text = "Once an Awakener attains the Absolute Axiom, they can never undergo the Psyche Surge ritual again."
  },
  AvgCommunicate_134246_Content_2 = {
    Text = "What do you need this time, laying it on this thick all of a sudden?"
  },
  AvgCommunicate_134246_Content_21 = {
    Text = "Haha—I must have gotten something mixed up by accident!"
  },
  AvgCommunicate_134246_Content_22 = {
    Text = "Please rewind your memory of this conversation by six messages. Have a wonderful day~"
  },
  AvgCommunicate_134246_Content_3 = {
    Text = "Oh my, listen to you—what do you take me for, someone who only shows up when she wants something?"
  },
  AvgCommunicate_134246_Content_4 = {
    Text = "That's exactly what you are..."
  },
  AvgCommunicate_134246_Content_5 = {
    Text = "Boo-hoo, I'm heartbroken. My benefactor misjudges me so terribly."
  },
  AvgCommunicate_134246_Content_6 = {
    Text = "I've actually come to bring you some good news this time!"
  },
  AvgCommunicate_134246_Content_7 = {
    Text = "Your investment has paid off—with super, super amazing results~"
  },
  AvgCommunicate_134246_Content_8 = {
    Text = "See? I'm a whole new me. Reborn, transformed, a completely different person~"
  },
  AvgCommunicate_134246_Content_9 = {Text = "Really?"},
  AvgCommunicate_134246_Option_10 = {
    Text = "Let me check."
  },
  AvgCommunicate_134246_Option_16 = {
    Text = "That's impossible."
  },
  AvgCommunicate_134246_Option_17 = {Text = "Nice try."},
  AvgCommunicate_134246_Option_9 = {Text = "Really?"},
  AvgCommunicate_134247_Content_1 = {
    Text = "Suggested Translation"
  },
  AvgCommunicate_134249_Content_1 = {Text = "Keeper..."},
  AvgCommunicate_134249_Content_10 = {
    Text = "Ugh... That feeling's back. I'm suddenly so hot, so thirsty. It's in my stomach... right inside it..."
  },
  AvgCommunicate_134249_Content_11 = {
    Text = "Keeper, am I sick? My stomach is going soft, my heart is going soft, everything is soft—I can't tell them apart, as if I'm about to melt..."
  },
  AvgCommunicate_134249_Content_12 = {
    Text = "Take a deep breath, Leigh. You're not going to melt."
  },
  AvgCommunicate_134249_Content_13 = {
    Text = "This is a normal human reaction when we're happy—there is no need for medication... or a whip."
  },
  AvgCommunicate_134249_Content_14 = {
    Text = "Huh? Not even a whip? I‘m... a little disappointed."
  },
  AvgCommunicate_134249_Content_16 = {
    Text = "...Uh, if you really need it, you could try looking for Pandia..."
  },
  AvgCommunicate_134249_Content_17 = {Text = "Hehe."},
  AvgCommunicate_134249_Content_18 = {
    Text = "Keeper, I'll try not to crouch by your door anymore from now on."
  },
  AvgCommunicate_134249_Content_19 = {
    Text = "But... could you occasionally leave a door open for me at night? A window works too."
  },
  AvgCommunicate_134249_Content_2 = {
    Text = "My brother's flesh and my body fit together better than before. They breathe quietly beneath my skin, no longer constantly screaming to tear me apart."
  },
  AvgCommunicate_134249_Content_20 = {
    Text = "I won't go in, but just knowing there's always a way to reach you... It lets me sleep a little more soundly."
  },
  AvgCommunicate_134249_Content_3 = {
    Text = "The craving for blood doesn't hurt as much anymore. It used to feel like something was lodged in my throat—like I'd suffocate if I didn't drink. Now it seems like... it’s willing to wait for me for a little while."
  },
  AvgCommunicate_134249_Content_4 = {
    Text = "Sounds great. I'm happy for you."
  },
  AvgCommunicate_134249_Content_5 = {
    Text = "The school is so quiet at night. The fountain gurgles softly."
  },
  AvgCommunicate_134249_Content_6 = {
    Text = "Keeper, you've given me so many treasures. Do I deserve them?"
  },
  AvgCommunicate_134249_Content_7 = {
    Text = "Absolutely."
  },
  AvgCommunicate_134249_Content_8 = {
    Text = "...You always answer so quickly."
  },
  AvgCommunicate_134249_Content_9 = {
    Text = "Leigh, you've helped us so much; this is the least I can do."
  },
  AvgCommunicate_134250_Content_1 = {
    Text = "Don't you know the fate of those who keep a wild beast?"
  },
  AvgCommunicate_134250_Content_10 = {
    Text = "I often wonder if you are truly as you seem, or if..."
  },
  AvgCommunicate_134250_Content_11 = {
    Text = "...you’ve been acting all along, just like those slaveholders."
  },
  AvgCommunicate_134250_Content_12 = {
    Text = "What do you think? I'm not good at acting, and I'm not good at lying."
  },
  AvgCommunicate_134250_Content_13 = {
    Text = "You can trust your own feelings. I won't convince you, and I won't force you to do anything."
  },
  AvgCommunicate_134250_Content_14 = {
    Text = "Just like the other \"you\" said: we are friends, we are comrades."
  },
  AvgCommunicate_134250_Content_15 = {
    Text = "Tch. Don't compare me to that weakling."
  },
  AvgCommunicate_134250_Content_16 = {
    Text = "I’ve had more than enough of betrayal. I don't need friends."
  },
  AvgCommunicate_134250_Content_17 = {
    Text = "And I don't want any promises from you."
  },
  AvgCommunicate_134250_Content_18 = {
    Text = "All you need to do is give me more power."
  },
  AvgCommunicate_134250_Content_19 = {
    Text = "In exchange, I’ll take revenge on your enemies as well."
  },
  AvgCommunicate_134250_Content_2 = {
    Text = "Once grown, the beast will snap its chains and—crunch—tear out the feeder's throat."
  },
  AvgCommunicate_134250_Content_20 = {
    Text = "But when you actually betray me... even if you flee to the ends of the earth, I will hunt you down and tear your throat out."
  },
  AvgCommunicate_134250_Content_3 = {
    Text = "Right now, the link between us looks even flimsier than an iron chain to me."
  },
  AvgCommunicate_134250_Content_4 = {
    Text = "Aren't you afraid?"
  },
  AvgCommunicate_134250_Content_5 = {
    Text = "You are free. Our link isn't meant to restrict you."
  },
  AvgCommunicate_134250_Content_6 = {
    Text = "I have no reason to be afraid."
  },
  AvgCommunicate_134250_Content_7 = {Text = "..."},
  AvgCommunicate_134250_Content_8 = {
    Text = "Tch, silver-tongued."
  },
  AvgCommunicate_134250_Content_9 = {
    Text = "Still, I’ve been watching you for a long time, and I haven't seen you slip up once."
  },
  AvgCommunicate_134250_Option_12 = {
    Text = "So what do you think?"
  },
  AvgCommunicate_134250_Option_5 = {
    Text = "You are free."
  },
  AvgCommunicate_134263_Content_1 = {Text = "Keeper!!"},
  AvgCommunicate_134263_Content_10 = {
    Text = "Of course; I never doubted that you would get stronger."
  },
  AvgCommunicate_134263_Content_11 = {Text = "..."},
  AvgCommunicate_134263_Content_12 = {
    Text = "You're really strange."
  },
  AvgCommunicate_134263_Content_13 = {
    Text = "At a time like this, shouldn't you say something like \"See, I knew I wasn't wrong about you\" or \"Just as I expected, you didn't let me down\"?"
  },
  AvgCommunicate_134263_Content_14 = {
    Text = "Why are you so calm?"
  },
  AvgCommunicate_134263_Content_16 = {
    Text = "Uhhh... Because you push yourself so hard, it's only natural you'd get stronger. What's there to say about it?"
  },
  AvgCommunicate_134263_Content_17 = {
    Text = "That 50 bucks you paid me back the year before last, and the 54 bucks from last year—I've kept them all."
  },
  AvgCommunicate_134263_Content_18 = {
    Text = "W-what are you keeping them for... just spend them."
  },
  AvgCommunicate_134263_Content_19 = {
    Text = "Forget it, let's not get into that. There's something important to discuss."
  },
  AvgCommunicate_134263_Content_2 = {
    Text = "Those markings are burning hot—the power of the deep sea flows beneath my skin, clearer than ever before!"
  },
  AvgCommunicate_134263_Content_20 = {
    Text = "Get over to the lake quickly. I'm waiting for you here."
  },
  AvgCommunicate_134263_Content_21 = {Text = "Why?"},
  AvgCommunicate_134263_Content_22 = {
    Text = "Come over and you'll find out."
  },
  AvgCommunicate_134263_Content_23 = {
    Text = "Alright... wait for me a moment. It's raining outside right now, so I need to head back to the dorm to grab my umbrella."
  },
  AvgCommunicate_134263_Content_24 = {
    Text = "Stop dawdling. We won't need an umbrella for what we've got planned next."
  },
  AvgCommunicate_134263_Content_25 = {
    Text = "You won't get wet! My wing membranes are large enough to cover you."
  },
  AvgCommunicate_134263_Content_3 = {
    Text = "You know what this feels like?"
  },
  AvgCommunicate_134263_Content_4 = {
    Text = "In short, it's incredible. Words can't quite describe it. You humans probably wouldn't understand."
  },
  AvgCommunicate_134263_Content_5 = {
    Text = "...Caecus, are you okay?"
  },
  AvgCommunicate_134263_Content_6 = {
    Text = "I'm doing great. Never been better."
  },
  AvgCommunicate_134263_Content_7 = {
    Text = "I told you so! Your investment won't go to waste. My bloodline never lies."
  },
  AvgCommunicate_134263_Content_8 = {Text = "I know."},
  AvgCommunicate_134263_Content_9 = {
    Text = "...That's it?"
  },
  AvgCommunicate_134264_Content_1 = {
    Text = "Please forgive me, Pale Messenger. I was underprepared for this and seem to have frightened you."
  },
  AvgCommunicate_134264_Content_10 = {
    Text = "The mere thought of this fills my heart with a peace that far outweighs the travail of my flesh."
  },
  AvgCommunicate_134264_Content_11 = {
    Text = "I understand. I may not have such grand ideals. But even if it's for you, for my friends..."
  },
  AvgCommunicate_134264_Content_12 = {
    Text = "...I will do whatever it takes to reach that ideal, peaceful world."
  },
  AvgCommunicate_134264_Content_13 = {
    Text = "Thank you, Pale Messenger."
  },
  AvgCommunicate_134264_Content_14 = {
    Text = "May all suffering find its day of dissolution, and may you and I always walk side by side."
  },
  AvgCommunicate_134264_Content_15 = {
    Text = "May the All-Father's protection also descend upon all that you hold dear."
  },
  AvgCommunicate_134264_Content_2 = {
    Text = "Phew... I'm glad you're alright. I didn't expect the comprehension of the Axiom to have this effect."
  },
  AvgCommunicate_134264_Content_3 = {
    Text = "Don't worry about me. This is the very mission for which I came into this world."
  },
  AvgCommunicate_134264_Content_4 = {
    Text = "Before I crossed the threshold to the pinnacle, before the All-Father revealed these unfathomable mysteries to me, I had already devoted myself to this path."
  },
  AvgCommunicate_134264_Content_5 = {
    Text = "Gathering the suffering of all beings unto myself, guiding all things toward an immaculate land where suffering no longer exists—this is no burden. This is the grace bestowed upon me by the All-Father."
  },
  AvgCommunicate_134264_Content_6 = {
    Text = "I've always felt you bear far too much. The pain of others is dissolved, but the cost..."
  },
  AvgCommunicate_134264_Content_7 = {
    Text = "My Pale Flame, you possess a tender heart."
  },
  AvgCommunicate_134264_Content_8 = {
    Text = "But rest assured. Physical suffering is to me as thorns are to soil—the deeper they pierce, the more firmly I take root."
  },
  AvgCommunicate_134264_Content_9 = {
    Text = "If even one soul in this world still suffers, they shall never be alone. If one has yet to escape the sea of suffering, I shall never reach the other shore before them."
  },
  AvgCommunicate_134264_Option_11 = {
    Text = "I understand."
  },
  AvgCommunicate_134264_Option_6 = {Text = "But..."},
  AvgCommunicate_134265_Content_1 = {
    Text = "Haha, exhilarating! Absolutely exhilarating!"
  },
  AvgCommunicate_134265_Content_10 = {
    Text = "Ask any of my boys or girls; they've known me for years. When have they ever seen me do something like that?"
  },
  AvgCommunicate_134265_Content_11 = {
    Text = "Ah, now that my strength is even fiercer, I'll have to be careful not to burn you next time."
  },
  AvgCommunicate_134265_Content_12 = {
    Text = "What... it was you? Then... those times I woke up in different clothes... was that you, too?"
  },
  AvgCommunicate_134265_Content_13 = {
    Text = "Yeah. Your clothes were all dirty from booze and food. I couldn't just let you crawl into bed like that."
  },
  AvgCommunicate_134265_Content_14 = {
    Text = "Thank you, Kathigu-Ra."
  },
  AvgCommunicate_134265_Content_15 = {
    Text = "But next time, could you just shake me awake instead..."
  },
  AvgCommunicate_134265_Content_16 = {
    Text = "Oh, getting shy? C'mon—we're practically family."
  },
  AvgCommunicate_134265_Content_17 = {
    Text = "Never mind changing a few clothes—I'd go through hell and high water for you without a second thought!"
  },
  AvgCommunicate_134265_Content_18 = {
    Text = "Worst case, I'll just let you help me change next time. Fair's fair."
  },
  AvgCommunicate_134265_Content_19 = {
    Text = "...Nothing about that is reasonable, and it's so unreasonable I have no idea how to even respond!"
  },
  AvgCommunicate_134265_Content_2 = {
    Text = "With this incredible power coursing through me... now, I AM THE SUN!"
  },
  AvgCommunicate_134265_Content_3 = {
    Text = "Little one, I’m more and more impressed by you."
  },
  AvgCommunicate_134265_Content_4 = {
    Text = "Just figuring that out now? I've got plenty more where that came from."
  },
  AvgCommunicate_134265_Content_5 = {
    Text = "Oh? I guess treating you like a kid all this time was a bit of a misstep."
  },
  AvgCommunicate_134265_Content_6 = {
    Text = "Hmm... guess I'll have to start calling you \"big one\" from now on."
  },
  AvgCommunicate_134265_Content_7 = {
    Text = "\"Big one\"? What is that even supposed to mean! You're messing with me again with that straight face, aren't you?"
  },
  AvgCommunicate_134265_Content_8 = {
    Text = "Hahaha, what can I say? You're always the first one to pass out every time we go out drinking."
  },
  AvgCommunicate_134265_Content_9 = {
    Text = "I have to carry you back to the dorm every single time—taking off your shoes, tucking you in, and wiping your face."
  },
  AvgCommunicate_134265_Option_12 = {
    Text = "It was you?"
  },
  AvgCommunicate_134265_Option_7 = {Text = "?!"},
  AvgCommunicate_134267_Content_1 = {
    Text = "%player%, my music has reached a new level of perfection."
  },
  AvgCommunicate_134267_Content_10 = {
    Text = "My music was like a precisely calibrated machine, and it once earned me a place in an elite orchestra. I was very proud of that."
  },
  AvgCommunicate_134267_Content_11 = {
    Text = "He was different. He wasn't suited for an ensemble. His music was meant to shine alone in the sky, like the sun or the moon."
  },
  AvgCommunicate_134267_Content_12 = {
    Text = "I always watched him, chasing after him... it’s just that I have already lost the chance to speak with him forever."
  },
  AvgCommunicate_134267_Content_13 = {
    Text = "But... this performance, having reached ultimate perfection, is the best answer I can offer after a lifetime of pursuit."
  },
  AvgCommunicate_134267_Content_14 = {
    Text = "That’s so moving... I can't believe you have a past like that. It sounds like a legendary story of brilliant musicians reflecting each other's light."
  },
  AvgCommunicate_134267_Content_15 = {
    Text = "Mm, just some perfectly ordinary musings. It’s really not that dramatic."
  },
  AvgCommunicate_134267_Content_16 = {
    Text = "Regardless, what I want to say most is: thank you, %player%."
  },
  AvgCommunicate_134267_Content_17 = {
    Text = "From now on, please let me continue to play my flute for you, accompanying you into a peaceful slumber each night."
  },
  AvgCommunicate_134267_Content_2 = {
    Text = "Without your guidance, I would likely never have taken this final step—calibrating the minute errors that were once beyond human ability to correct."
  },
  AvgCommunicate_134267_Content_3 = {
    Text = "Perfect rhythm, flawless pitch... everything sounds so exquisite."
  },
  AvgCommunicate_134267_Content_4 = {
    Text = "Absolutely! I’ve never heard such a delightful performance!"
  },
  AvgCommunicate_134267_Content_5 = {
    Text = "This is the result of resonance between music and calculation, instrument and body, mind and muscle."
  },
  AvgCommunicate_134267_Content_6 = {
    Text = "I’ve finally proven that at the end of this dry and tedious path, such perfect music can also exist."
  },
  AvgCommunicate_134267_Content_7 = {
    Text = "Also? What do you mean by that?"
  },
  AvgCommunicate_134267_Content_8 = {
    Text = "In the past, I had a friend whose music was the product of the purest sensibility and creativity."
  },
  AvgCommunicate_134267_Content_9 = {
    Text = "The talent he wielded so freely allowed him to improvise unique passages with every performance."
  },
  AvgCommunicate_134267_Option_14 = {Text = "Aww..."},
  AvgCommunicate_134267_Option_4 = {Text = "True."},
  AvgCommunicate_134267_Option_7 = {Text = "Also?"},
  AvgCommunicate_134268_Content_1 = {
    Text = "My most esteemed guest, how can I ever thank you for your generosity?"
  },
  AvgCommunicate_134268_Content_10 = {
    Text = "I see. You don't want those vulgar celebrations, and I agree they don't suit you."
  },
  AvgCommunicate_134268_Content_11 = {
    Text = "I have an idea. Perhaps you'd be willing to accompany me beyond Necrovia to receive one who is approaching their end?"
  },
  AvgCommunicate_134268_Content_12 = {
    Text = "Should we be graced with such an honor, I hope you and I may receive them together, guiding them to their final destination and rebirth. What do you say?"
  },
  AvgCommunicate_134268_Content_13 = {
    Text = "Though it may be a bit untimely... I'm guessing it will still involve a meal in the end, since that's the custom of Necrovia."
  },
  AvgCommunicate_134268_Content_14 = {
    Text = "Hmm, I wouldn't define it as a meal. It is just as it was in the stories you already know."
  },
  AvgCommunicate_134268_Content_15 = {
    Text = "It is simply a solemn and serene farewell."
  },
  AvgCommunicate_134268_Content_16 = {
    Text = "I'd be happy to participate, as long as you allow me to skip certain parts..."
  },
  AvgCommunicate_134268_Content_17 = {
    Text = "Of course, of course."
  },
  AvgCommunicate_134268_Content_18 = {
    Text = "Then, I shall be waiting at your door tomorrow morning, with Necrovia's carriage."
  },
  AvgCommunicate_134268_Content_2 = {
    Text = "Your gift has granted me the strength to truly and steadfastly serve as the guardian of Necrovia."
  },
  AvgCommunicate_134268_Content_3 = {
    Text = "Ordinary cuisine is unworthy of your offering, and my finest reserves may not quite suit your palate."
  },
  AvgCommunicate_134268_Content_4 = {
    Text = "What a blissfully vexing dilemma."
  },
  AvgCommunicate_134268_Content_5 = {
    Text = "You're too kind, Doresain."
  },
  AvgCommunicate_134268_Content_6 = {
    Text = "We've been through so much together. You really don't need to fuss over tedious formalities."
  },
  AvgCommunicate_134268_Content_7 = {
    Text = "Oh no, no, this is by no means a mere formality. I am earnestly contemplating how to prepare a fitting gathering with a dear friend."
  },
  AvgCommunicate_134268_Content_8 = {
    Text = "You have already attended Necrovia's most extraordinary ball. How to bring us closer still—that is indeed a challenge."
  },
  AvgCommunicate_134268_Content_9 = {
    Text = "Um... If you want to know my preference, I simply hope for something ordinary—nothing too scary."
  },
  AvgCommunicate_134268_Option_13 = {
    Text = "I'm guessing..."
  },
  AvgCommunicate_134268_Option_9 = {Text = "Um..."},
  AvgCommunicate_134269_Content_1 = {
    Text = "My little sapling..."
  },
  AvgCommunicate_134269_Content_10 = {
    Text = "Within my body, the strength of Proliferation is blossoming, born from touching the ultimate."
  },
  AvgCommunicate_134269_Content_11 = {
    Text = "How sweet, how lush... Ah, I grow weary of speaking to you through this tiny metal block."
  },
  AvgCommunicate_134269_Content_12 = {Text = "Thais?"},
  AvgCommunicate_134269_Content_13 = {
    Text = "Come to my side, little sapling. Right now, this instant."
  },
  AvgCommunicate_134269_Content_14 = {
    Text = "I want to hold your warm palms, to touch your soft skin..."
  },
  AvgCommunicate_134269_Content_15 = {
    Text = "I want to embrace you under the moonlight, just like the night we made our promise."
  },
  AvgCommunicate_134269_Content_16 = {
    Text = "With my ever more abundant strength, merging with you bit by bit, and letting your sweet essence warm me, little by little..."
  },
  AvgCommunicate_134269_Content_2 = {
    Text = "The promise you made me back then under the moonlight and across the sea of sand—you're already fulfilling it."
  },
  AvgCommunicate_134269_Content_3 = {
    Text = "I'm so happy."
  },
  AvgCommunicate_134269_Content_4 = {
    Text = "Although a world where everyone can live in peace is still far away, I'll keep working toward it."
  },
  AvgCommunicate_134269_Content_5 = {
    Text = "I have believed in you since the moment we first met."
  },
  AvgCommunicate_134269_Content_6 = {
    Text = "You are one blessed by fate. You have the strength, and the resolve."
  },
  AvgCommunicate_134269_Content_7 = {
    Text = "My little sapling, you look so adorable when you're earnestly taking on the world."
  },
  AvgCommunicate_134269_Content_8 = {
    Text = "I will wait patiently, earnestly... Waiting, waiting... for the day our promise is fulfilled."
  },
  AvgCommunicate_134269_Content_9 = {Text = "I promise!"},
  AvgCommunicate_134269_Option_12 = {Text = "Thais?"},
  AvgCommunicate_134269_Option_4 = {
    Text = "I'll keep working hard."
  },
  AvgCommunicate_134269_Option_9 = {Text = "I promise!"},
  AvgCommunicate_134270_Content_1 = {
    Text = "I won't kill you."
  },
  AvgCommunicate_134270_Content_10 = {
    Text = "After I drain you dry, I'll go kill everyone else."
  },
  AvgCommunicate_134270_Content_11 = {
    Text = "Then I'll... try to stay alive as long as I can?"
  },
  AvgCommunicate_134270_Content_12 = {
    Text = "Ha. A funny answer."
  },
  AvgCommunicate_134270_Content_13 = {
    Text = "Since you intend to use that frail body of yours to protect the entire world..."
  },
  AvgCommunicate_134270_Content_14 = {Text = "Then..."},
  AvgCommunicate_134270_Content_15 = {Text = "...Then?"},
  AvgCommunicate_134270_Content_16 = {
    Text = "Until then, I will only kill your enemies."
  },
  AvgCommunicate_134270_Content_17 = {
    Text = "So you're still going to kill people...?!"
  },
  AvgCommunicate_134270_Content_2 = {
    Text = "...? Huh? What am I supposed to say? Thanks?"
  },
  AvgCommunicate_134270_Content_3 = {
    Text = "This world became truly boring after the fall of Rome."
  },
  AvgCommunicate_134270_Content_4 = {
    Text = "Killing, killing, killing. Pure slaughter and blood. Without Rome, nothing remains."
  },
  AvgCommunicate_134270_Content_5 = {
    Text = "Your gift freed me from those shackles. Now, I’m going to rip off an arm or two—or perhaps tear out a throat."
  },
  AvgCommunicate_134270_Content_6 = {
    Text = "I'm sorry, Uvhash, but in modern times, killing people without special authorization is against the law."
  },
  AvgCommunicate_134270_Content_7 = {
    Text = "Besides, I am still your Linker. Not only can you not kill me, you can't kill anyone else either."
  },
  AvgCommunicate_134270_Content_8 = {Text = "Tch."},
  AvgCommunicate_134270_Content_9 = {
    Text = "Fine. At least you taste better than all those slave masters."
  },
  AvgCommunicate_134271_Content_1 = {
    Text = "Keee-per~ Are you busy? I have something to tell you~"
  },
  AvgCommunicate_134271_Content_10 = {Text = "Empty?"},
  AvgCommunicate_134271_Content_11 = {
    Text = "Mm~ You know, that dark, cold feeling—the feeling of being abandoned by everyone that wells up whenever the wind blows through."
  },
  AvgCommunicate_134271_Content_12 = {
    Text = "But now, it's all warm~ and bright~"
  },
  AvgCommunicate_134271_Content_13 = {
    Text = "It's all because of %player%."
  },
  AvgCommunicate_134271_Content_14 = {
    Text = "So this really is a sincere thank you?"
  },
  AvgCommunicate_134271_Content_15 = {
    Text = "Hmph~ Of course, I can be serious once in a while, you know!"
  },
  AvgCommunicate_134271_Content_16 = {
    Text = "But in exchange—you have to spend more time with me from now on, okay?"
  },
  AvgCommunicate_134271_Content_17 = {
    Text = "Otherwise, I'll use my newly learned skills to pun~ish~ you real good~"
  },
  AvgCommunicate_134271_Content_18 = {
    Text = "...Is this really how you show your thanks?!"
  },
  AvgCommunicate_134271_Content_19 = {
    Text = "Oh my, this is Pandia's exclusive way of expressing love~ Mwah~ Remember to be grateful!"
  },
  AvgCommunicate_134271_Content_2 = {
    Text = "What kind of mischief are you up to now?"
  },
  AvgCommunicate_134271_Content_3 = {
    Text = "How could you say that! I'm here to sincerely thank you!"
  },
  AvgCommunicate_134271_Content_4 = {
    Text = "Those good things you gave me before... they made my body feel so hot, so hot~"
  },
  AvgCommunicate_134271_Content_5 = {
    Text = "It's like something scalding hot is flowing beneath my skin, sweet yet stinging~"
  },
  AvgCommunicate_134271_Content_6 = {
    Text = "Although I know there won't be any side effects, are you sure this isn't one...?"
  },
  AvgCommunicate_134271_Content_7 = {
    Text = "It's not! This feeling is amazing! A hundred times more thrilling than any whipping!"
  },
  AvgCommunicate_134271_Content_8 = {
    Text = "And you know what, the most incredible thing is..."
  },
  AvgCommunicate_134271_Content_9 = {
    Text = "That empty place inside my heart... has been filled up."
  },
  AvgCommunicate_134271_Option_14 = {Text = "So..."},
  AvgCommunicate_134271_Option_6 = {
    Text = "Although..."
  },
  AvgCommunicate_134272_Content_1 = {
    Text = "Master~ What can Karen do to repay you? Drinks, cleaning, meals—please feel free to order Karen around!"
  },
  AvgCommunicate_134272_Content_10 = {
    Text = "As long as I want, my skin can shine more brilliantly than the most expensive gemstones and gleam more radiantly than the most perfect pearls."
  },
  AvgCommunicate_134272_Content_11 = {
    Text = "If I go to a ball now, I will definitely be the center of attention—no longer the little nobody that no one cares about."
  },
  AvgCommunicate_134272_Content_12 = {
    Text = "Though I doubt this was the main point of the Axiom's power, still..."
  },
  AvgCommunicate_134272_Content_13 = {
    Text = "As long as it makes you happy, that's all that matters."
  },
  AvgCommunicate_134272_Content_2 = {
    Text = "First, let's rule out the meals!"
  },
  AvgCommunicate_134272_Content_3 = {
    Text = "Oh my, my housekeeping skills are being doubted. Karen should be sad about this, but, but..."
  },
  AvgCommunicate_134272_Content_4 = {
    Text = "So many, so many jewels and accessories! Karen feels like the most dazzling gem ever. It's really hard for Karen to feel sad!"
  },
  AvgCommunicate_134272_Content_5 = {
    Text = "Calm down a bit first. I can barely understand what you're saying anymore."
  },
  AvgCommunicate_134272_Content_6 = {
    Text = "Sorry! Karen got too carried away! After Master helped Karen grasp that thing... what was it, an accessory?"
  },
  AvgCommunicate_134272_Content_7 = {
    Text = "...It's the Absolute Axiom."
  },
  AvgCommunicate_134272_Content_8 = {
    Text = "Oh right, that really expensive, really amazing thing. And then, Karen felt like she gained an incredibly powerful ability."
  },
  AvgCommunicate_134272_Content_9 = {
    Text = "Karen's chores are done twice as fast now, but more importantly... Karen's body is literally glowing."
  },
  AvgCommunicate_134272_Option_7 = {
    Text = "It's not an accessory..."
  },
  AvgCommunicate_134273_Content_1 = {
    Text = "%player%, my link with you has grown deeper."
  },
  AvgCommunicate_134273_Content_10 = {
    Text = "Can I get things like calculus answers, general ed exam questions, and the like directly from infinite knowledge?"
  },
  AvgCommunicate_134273_Content_11 = {Text = "..."},
  AvgCommunicate_134273_Content_12 = {
    Text = "It is true that you no longer need to painstakingly memorize so many things."
  },
  AvgCommunicate_134273_Content_13 = {
    Text = "But I believe the meaning of learning lies in the process of seeking knowledge and strengthening the mind."
  },
  AvgCommunicate_134273_Content_14 = {
    Text = "You must first realize what you do not know and what you should know, before you can find the answers you need from the endless treasury."
  },
  AvgCommunicate_134273_Content_15 = {
    Text = "Alright, I understand. Though your answer differs from Ramona's, the outcome is exactly the same."
  },
  AvgCommunicate_134273_Content_16 = {
    Text = "Okay fine, I'll study!"
  },
  AvgCommunicate_134273_Content_17 = {
    Text = "I’m glad to see your eagerness to learn. Keep at it. I will be right by your side, as always."
  },
  AvgCommunicate_134273_Content_2 = {
    Text = "You've done well, and I thank you for your efforts. Now I can gather more fragments of consciousness and anchor a more complete existence within the world's crevices."
  },
  AvgCommunicate_134273_Content_3 = {
    Text = "You can manifest in the world now!?"
  },
  AvgCommunicate_134273_Content_4 = {
    Text = "Regrettably, I still cannot truly reveal my existence, nor can I leave the Black Pool."
  },
  AvgCommunicate_134273_Content_5 = {
    Text = "But my spirit, my dreams, and my gaze upon the myriad worlds can now reach you more directly, resonating within your mind more clearly."
  },
  AvgCommunicate_134273_Content_6 = {
    Text = "At the very least, you now possess the key to infinite knowledge."
  },
  AvgCommunicate_134273_Content_7 = {
    Text = "You mean no matter what I ask, I can get an answer?"
  },
  AvgCommunicate_134273_Content_8 = {
    Text = "As long as it exists, or can be proven."
  },
  AvgCommunicate_134273_Content_9 = {
    Text = "Hehe, for example—just as an example."
  },
  AvgCommunicate_134273_Option_15 = {
    Text = "I understand."
  },
  AvgCommunicate_134273_Option_7 = {
    Text = "Infinite knowledge?"
  },
  AvgCommunicate_134274_Content_1 = {
    Text = "The seed... has become more complete."
  },
  AvgCommunicate_134274_Content_10 = {
    Text = "Such lively scenes are still far too nerve-wracking for me."
  },
  AvgCommunicate_134274_Content_11 = {
    Text = "It's okay. I, as well as Tinct, will be right there with you."
  },
  AvgCommunicate_134274_Content_12 = {
    Text = "Of course, if you feel more comfortable keeping to yourself, I fully support that, too!"
  },
  AvgCommunicate_134274_Content_13 = {
    Text = "Keeper... thank you, if this is what you and Tinct hope for."
  },
  AvgCommunicate_134274_Content_14 = {
    Text = "Hmm... I'll start by adapting in the back corner of the classroom."
  },
  AvgCommunicate_134274_Content_2 = {
    Text = "I can feel a power nourishing my growth, slowly filling the emptiness within my soul."
  },
  AvgCommunicate_134274_Content_3 = {
    Text = "So... does that mean you won't drain others' life force anymore?"
  },
  AvgCommunicate_134274_Content_4 = {
    Text = "Unfortunately, this innate ability of mine hasn't disappeared."
  },
  AvgCommunicate_134274_Content_5 = {
    Text = "However, I'm beginning to gain control over this strength."
  },
  AvgCommunicate_134274_Content_6 = {
    Text = "As long as I keep practicing, investigators who come into contact with me won't need to wear those cumbersome protective suits anymore."
  },
  AvgCommunicate_134274_Content_7 = {
    Text = "Now, it's finally possible for me to stay safely by everyone's side."
  },
  AvgCommunicate_134274_Content_8 = {
    Text = "That's wonderful! From now on, you can join all kinds of school activities, galas, and parties for the Awakeners."
  },
  AvgCommunicate_134274_Content_9 = {
    Text = "P-parties... I think learning to get along with others is much harder than controlling my instincts."
  },
  AvgCommunicate_134274_Option_11 = {Text = "It's okay."},
  AvgCommunicate_134274_Option_3 = {Text = "So..."},
  AvgCommunicate_134274_Option_8 = {
    Text = "That's wonderful!"
  },
  AvgCommunicate_134275_Content_1 = {
    Text = "It is your privilege to offer such tributes to me."
  },
  AvgCommunicate_134275_Content_10 = {
    Text = "...Thank you? Aren't you just trying to butter me up with gifts to hear words of encouragement, or to have me fulfill some expectation?"
  },
  AvgCommunicate_134275_Content_11 = {
    Text = "Murphy, I give you gifts and treat you well simply for who you are."
  },
  AvgCommunicate_134275_Content_12 = {
    Text = "It has nothing to do with you being a Divine Mother, or anything else. You are my friend. Beyond that, I have no other expectations."
  },
  AvgCommunicate_134275_Content_13 = {Text = "..."},
  AvgCommunicate_134275_Content_14 = {
    Text = "Hmph! That's just the same smooth-talking, silver-tongued nonsense! Do you think saying that will move me to tears?"
  },
  AvgCommunicate_134275_Content_15 = {
    Text = "Don't even think about it! What do you mean, friend? You only need to be a loyal follower."
  },
  AvgCommunicate_134275_Content_16 = {
    Text = "That hurts. I might just cry myself to sleep tonight, you know?"
  },
  AvgCommunicate_134275_Content_17 = {
    Text = "You... you, oh, you useless fool."
  },
  AvgCommunicate_134275_Content_18 = {
    Text = "Only this once, so listen carefully."
  },
  AvgCommunicate_134275_Content_19 = {
    Text = "...Thank you."
  },
  AvgCommunicate_134275_Content_2 = {Text = "Not bad."},
  AvgCommunicate_134275_Content_20 = {
    Text = "In any case, from now on, I will have more than enough power to keep you safe. Be grateful and continue to worship me!"
  },
  AvgCommunicate_134275_Content_3 = {
    Text = "You don't have anything else to say?"
  },
  AvgCommunicate_134275_Content_4 = {
    Text = "What? Shouldn't this power rightfully be mine?"
  },
  AvgCommunicate_134275_Content_5 = {
    Text = "Oh, I see. You want a reward, a benediction, a higher position, or a more distinguished title?"
  },
  AvgCommunicate_134275_Content_6 = {Text = "..."},
  AvgCommunicate_134275_Content_7 = {
    Text = "What do those three dots mean? How annoying. I have no interest in playing guessing games with you."
  },
  AvgCommunicate_134275_Content_8 = {
    Text = "I’ll give you one last chance. Tell me what you want, quickly. Stop beating around the bush."
  },
  AvgCommunicate_134275_Content_9 = {
    Text = "Is it possible that... well, I mean, you could at least say thank you."
  },
  AvgCommunicate_134275_Option_16 = {
    Text = "That hurts."
  },
  AvgCommunicate_134275_Option_3 = {Text = "That's it?"},
  AvgCommunicate_134275_Option_6 = {Text = "..."},
  AvgCommunicate_134275_Option_9 = {
    Text = "Is it possible..."
  },
  AvgCommunicate_134276_Content_1 = {
    Text = "Thank you, Keeper, thank you! I... I don't know how to express it..."
  },
  AvgCommunicate_134276_Content_10 = {
    Text = "Something like that?"
  },
  AvgCommunicate_134276_Content_11 = {
    Text = "I've heard that colors carry different emotions and atmospheres. You could create new colors according to your own creative vision."
  },
  AvgCommunicate_134276_Content_12 = {
    Text = "Oh! Ohhh! Mix entirely new color combinations as I please!"
  },
  AvgCommunicate_134276_Content_13 = {
    Text = "What a genius idea! Different polarizations... different textures... I already have so many ideas!"
  },
  AvgCommunicate_134276_Content_14 = {
    Text = "Excuse me, Keeper!"
  },
  AvgCommunicate_134276_Content_15 = {
    Text = "I have a feeling that my next painting will possess even more wondrous brushstrokes."
  },
  AvgCommunicate_134276_Content_16 = {
    Text = "Maybe I really can create a painted realm that connects to the unknown. When that time comes, you'll definitely be the first to see it!"
  },
  AvgCommunicate_134276_Content_2 = {
    Text = "Thank you for giving me the chance to see the world as it truly is—the ultimate laws of the universe, the underpainting on the canvas of reality..."
  },
  AvgCommunicate_134276_Content_3 = {
    Text = "Ah, it’s so beautiful... How could I ever mix such a color?"
  },
  AvgCommunicate_134276_Content_4 = {
    Text = "Rainbow crystal? Mithril? Pearl? Crystal worm powder? Luminous butterfly wings?"
  },
  AvgCommunicate_134276_Content_5 = {
    Text = "No, no, no... That can't be replicated with such mundane, ordinary materials. I need to think... think harder..."
  },
  AvgCommunicate_134276_Content_6 = {
    Text = "Pickman? Looks like you're already lost in your own art..."
  },
  AvgCommunicate_134276_Content_7 = {
    Text = "Shh—what do you think the true color of the universe looks like? Someone as special as you must be able to grant me a unique insight!"
  },
  AvgCommunicate_134276_Content_8 = {
    Text = "I think the world might look different through everyone's eyes."
  },
  AvgCommunicate_134276_Content_9 = {
    Text = "Oh! You mean... follow my own heart... follow my feelings, and paint the different colors of the universe..."
  },
  AvgCommunicate_134276_Option_10 = {Text = "Perhaps."},
  AvgCommunicate_134276_Option_8 = {Text = "I think..."},
  AvgCommunicate_134277_Content_1 = {Text = "Keeper~"},
  AvgCommunicate_134277_Content_10 = {
    Text = "I won't pity you, and I won't condescendingly assume your logic. I only hope you enjoy yourself in this world."
  },
  AvgCommunicate_134277_Content_11 = {Text = "..."},
  AvgCommunicate_134277_Content_12 = {
    Text = "Wow. Which one of us is crazier here? To hand this level of strength over to a lunatic like me for a reason like that?"
  },
  AvgCommunicate_134277_Content_13 = {
    Text = "Don't tell me my ending up in this world was actually fate's doing?"
  },
  AvgCommunicate_134277_Content_15 = {
    Text = "Anyway, thanks to you, I've touched my \"ceiling\" in this world."
  },
  AvgCommunicate_134277_Content_16 = {
    Text = "Now then, hurry up and assign me a mission! I can't wait to go chop off a few heads and show you what I can do~"
  },
  AvgCommunicate_134277_Content_2 = {
    Text = "A girl stranded in a foreign world receives an expensive gift that makes her stronger. Do you know what that sounds like?"
  },
  AvgCommunicate_134277_Content_3 = {
    Text = "Before you say something typically weird, let me get this straight—you're a member of Mythag, and in Mythag, we help each other. That's why I gave you those materials."
  },
  AvgCommunicate_134277_Content_4 = {
    Text = "Really? It’s not some boring, roundabout, socialized performance?"
  },
  AvgCommunicate_134277_Content_5 = {
    Text = "Like... \"She can't go home—poor thing—let's show her a little more care.\""
  },
  AvgCommunicate_134277_Content_6 = {
    Text = "\"It must be so hard figuring things out alone, let's give her a hand.\" And you're telling me you didn't do this for any of these typical, \"ordinary society\" reasons?"
  },
  AvgCommunicate_134277_Content_7 = {
    Text = "First of all, no matter how you look at it, Mouchette, you have nothing to do with the word \"ordinary\"!"
  },
  AvgCommunicate_134277_Content_8 = {
    Text = "Heh☆, well, I actually love that compliment."
  },
  AvgCommunicate_134277_Content_9 = {
    Text = "Second, no matter how you see yourself or how you appear on the surface, to me—as you said—\"Mouchette\" is \"Mouchette.\""
  },
  AvgCommunicate_134277_Option_7 = {
    Text = "First of all..."
  },
  AvgCommunicate_134278_Content_1 = {
    Text = "Thank you, my dear. You have brought me so much happiness and allowed my ambition to burn forever."
  },
  AvgCommunicate_134278_Content_10 = {
    Text = "Whatever form of gratitude you desire, I can make it happen."
  },
  AvgCommunicate_134278_Content_11 = {
    Text = "Even what I do not yet possess—even the stars and the moon—I would find a way to bring them to you."
  },
  AvgCommunicate_134278_Content_12 = {
    Text = "Anything I choose? Anything at all?"
  },
  AvgCommunicate_134278_Content_13 = {
    Text = "Keeping one's word is an indispensable pass in the world of fame and fortune."
  },
  AvgCommunicate_134278_Content_14 = {
    Text = "Well then, I'd like a promise from you. As for the specifics, I'll need some time to think it over."
  },
  AvgCommunicate_134278_Content_15 = {Text = "..."},
  AvgCommunicate_134278_Content_16 = {
    Text = "Hahahaha, what a cunning choice. You're making me like you more and more."
  },
  AvgCommunicate_134278_Content_17 = {
    Text = "Of course, my dear. You have plenty of time to think it over."
  },
  AvgCommunicate_134278_Content_18 = {
    Text = "If you have the time, why not come to my estate tonight? Perhaps, when it's just the two of us... you'll find it easier to come up with a refreshingly \"good idea.\""
  },
  AvgCommunicate_134278_Content_2 = {
    Text = "To serve you, my lady, is my pleasure."
  },
  AvgCommunicate_134278_Content_3 = {
    Text = "Hehe, sensible, clever, brave, loyal, plus just the right touch of... beauty."
  },
  AvgCommunicate_134278_Content_4 = {
    Text = "Who could say you're not a perfect..."
  },
  AvgCommunicate_134278_Content_5 = {
    Text = "A perfect... what?"
  },
  AvgCommunicate_134278_Content_6 = {
    Text = "You seem a little nervous?"
  },
  AvgCommunicate_134278_Content_7 = {
    Text = "My lady... You always leave me speechless."
  },
  AvgCommunicate_134278_Content_8 = {
    Text = "Some things need not be expressed in words. I have felt your heart in every bit of strength I've gained."
  },
  AvgCommunicate_134278_Content_9 = {
    Text = "Land, property, rare treasures, art, and the chance to meet so many celebrities... with my current power, all are within reach."
  },
  AvgCommunicate_134278_Option_12 = {
    Text = "Really, anything at all?"
  },
  AvgCommunicate_134278_Option_14 = {
    Text = "I'd like a promise from you."
  },
  AvgCommunicate_134278_Option_2 = {
    Text = "My pleasure."
  },
  AvgCommunicate_134278_Option_5 = {Text = "Perfect?"},
  AvgCommunicate_134278_Option_7 = {Text = "..."},
  AvgCommunicate_134279_Content_1 = {
    Text = "Keeper, are you still awake?"
  },
  AvgCommunicate_134279_Content_10 = {
    Text = "But everything you've poured into me... has converged into a new lake within me. One even vaster than that sea."
  },
  AvgCommunicate_134279_Content_11 = {
    Text = "It tells me: there is no need to be afraid anymore."
  },
  AvgCommunicate_134279_Content_12 = {
    Text = "I understand that pain may never fully dissolve, but no matter how many times it takes, I am willing to pull you back to the shore."
  },
  AvgCommunicate_134279_Content_13 = {
    Text = "...If Mom and Dad could hear you say that, I'm sure they would feel at ease."
  },
  AvgCommunicate_134279_Content_14 = {
    Text = "I think... perhaps they're somewhere out in that sea, watching over as I am now."
  },
  AvgCommunicate_134279_Content_15 = {
    Text = "From now on, I shall wield the strength I've been given and become the tide that serves as your guardian."
  },
  AvgCommunicate_134279_Content_16 = {
    Text = "Perhaps... would you be willing to grant one more bold request?"
  },
  AvgCommunicate_134279_Content_17 = {
    Text = "What is it? As long as it's something I can do, I'd be happy to."
  },
  AvgCommunicate_134279_Content_18 = {
    Text = "When the weather clears, please take a walk by the sea with me."
  },
  AvgCommunicate_134279_Content_19 = {
    Text = "I have so much I want to tell you. Just one afternoon is all I ask."
  },
  AvgCommunicate_134279_Content_2 = {
    Text = "I'm sorry if I'm disturbing your rest..."
  },
  AvgCommunicate_134279_Content_20 = {
    Text = "Of course. You have my word."
  },
  AvgCommunicate_134279_Content_3 = {
    Text = "No, I'm still up. What's wrong?"
  },
  AvgCommunicate_134279_Content_4 = {
    Text = "After receiving your gift, I fell into a deep slumber and drifted into a dream. I dreamed of the ocean from back then, and the sunset outside the sanatorium."
  },
  AvgCommunicate_134279_Content_5 = {
    Text = "But this time... I didn't walk into the sea."
  },
  AvgCommunicate_134279_Content_6 = {
    Text = "I stood on the shore, gazing at that sea. It still filled me with a sense of peace, yet I had no desire to move forward."
  },
  AvgCommunicate_134279_Content_7 = {
    Text = "If it isn't presumptuous to guess—is it because this time, you have a reason to stay?"
  },
  AvgCommunicate_134279_Content_8 = {Text = "Yes."},
  AvgCommunicate_134279_Content_9 = {
    Text = "I was once crushed by pain. Nothing could wash away the heaviness lodged in my throat—nothing except the deep sea, which sweeps away and embraces everything."
  },
  AvgCommunicate_134279_Option_12 = {
    Text = "Nymphaea..."
  },
  AvgCommunicate_134279_Option_17 = {
    Text = "What is it?"
  },
  AvgCommunicate_134279_Option_7 = {Text = "Because..."},
  AvgCommunicate_134280_Content_1 = {
    Text = "%player%, last night, I had that dream again."
  },
  AvgCommunicate_134280_Content_10 = {
    Text = "Perhaps it's the effect of the Absolute Axiom."
  },
  AvgCommunicate_134280_Content_11 = {
    Text = "Yes, so I want to say—on behalf of every \"24\", thank you, %player%."
  },
  AvgCommunicate_134280_Content_12 = {
    Text = "Thank you for letting us hear each other, see each other, understand each other, and accept each other."
  },
  AvgCommunicate_134280_Content_13 = {
    Text = "I can't take the credit for that."
  },
  AvgCommunicate_134280_Content_14 = {
    Text = "No, the guidance and comfort you gave quelled all the restless spirits."
  },
  AvgCommunicate_134280_Content_15 = {
    Text = "It is your presence that makes all the rivers converge into one."
  },
  AvgCommunicate_134280_Content_16 = {
    Text = "\"We\"—all of us—will never forget your kindness."
  },
  AvgCommunicate_134280_Content_2 = {
    Text = "I seemed to have returned to a pitch-black cavern at the foot of the snowy mountains in the far north."
  },
  AvgCommunicate_134280_Content_3 = {
    Text = "Countless masses of slime, reflecting countless shadows of \"24\"..."
  },
  AvgCommunicate_134280_Content_4 = {
    Text = "Those... were all you—all a part of you."
  },
  AvgCommunicate_134280_Content_5 = {Text = "I know."},
  AvgCommunicate_134280_Content_6 = {
    Text = "Amidst the chaos, I seemed to hear someone say something to me."
  },
  AvgCommunicate_134280_Content_7 = {
    Text = "The voice was hazy. I couldn't make it out clearly..."
  },
  AvgCommunicate_134280_Content_8 = {
    Text = "But after that person left, I felt all the clamor around me settle into stillness."
  },
  AvgCommunicate_134280_Content_9 = {
    Text = "The noisy whispers in my ears became harmonious and natural, as if they were a concordant melody..."
  },
  AvgCommunicate_134280_Option_4 = {
    Text = "They were all you."
  },
  AvgCommunicate_134281_Content_1 = {
    Text = "Keeper, do you believe in fate?"
  },
  AvgCommunicate_134281_Content_10 = {
    Text = "...As an ordinary person, I can barely imagine how great that feels. Allow me to ask through gritted teeth—what does it actually feel like?"
  },
  AvgCommunicate_134281_Content_11 = {
    Text = "How should I describe it? For example, I'm feeling a bit hungry right now..."
  },
  AvgCommunicate_134281_Content_12 = {
    Text = "? And then?"
  },
  AvgCommunicate_134281_Content_13 = {
    Text = "Oh, sorry for the wait. Someone just knocked on the door—it was Miss Mason sharing some freshly baked pound cake."
  },
  AvgCommunicate_134281_Content_14 = {Text = "What???"},
  AvgCommunicate_134281_Content_15 = {
    Text = "Just like that. And then... I'm feeling a bit thirsty."
  },
  AvgCommunicate_134281_Content_16 = {
    Text = "Hm? Mr. Doresain's butler just delivered an invitation, saying he'd like to invite me to savor his red wine collection stored at a nearby restaurant."
  },
  AvgCommunicate_134281_Content_17 = {
    Text = "...Enough. Next time, could you genuinely desire to help me with my homework?"
  },
  AvgCommunicate_134281_Content_18 = {
    Text = "Hahaha, as you wish, %player%. You are now my greatest backer, partner, and indispensable Dr. Watson."
  },
  AvgCommunicate_134281_Content_19 = {
    Text = "The Lucky Detective is most happy to be of service."
  },
  AvgCommunicate_134281_Content_2 = {
    Text = "I believe in fate, and I believe I have the best luck of all."
  },
  AvgCommunicate_134281_Content_3 = {
    Text = "Unexpected delights, windfalls, blessings falling from the sky—when these things suddenly happen to me, I don't even bat an eye anymore."
  },
  AvgCommunicate_134281_Content_4 = {
    Text = "Once you're accustomed to fate's favor, all the pleasant surprises become unremarkable."
  },
  AvgCommunicate_134281_Content_5 = {
    Text = "What you just said is truly both enviable and infuriating."
  },
  AvgCommunicate_134281_Content_6 = {
    Text = "Hold on, I'm not done yet. Meeting you is the greatest stroke of luck of all."
  },
  AvgCommunicate_134281_Content_7 = {
    Text = "What you give me always brings new surprises."
  },
  AvgCommunicate_134281_Content_8 = {
    Text = "Just like now—the strength I gained from the Absolute Axiom already allows me to clearly sense every stroke of good fortune before it arrives."
  },
  AvgCommunicate_134281_Content_9 = {
    Text = "Lucky events fall like raindrops—from a gentle drizzle to—splash!—a torrential downpour."
  },
  AvgCommunicate_134281_Option_10 = {
    Text = "What does that feel like?"
  },
  AvgCommunicate_134281_Option_14 = {Text = "???"},
  AvgCommunicate_134281_Option_5 = {
    Text = "That's both enviable and infuriating."
  },
  AvgCommunicate_137645_Content_1 = {Text = "Keeper."},
  AvgCommunicate_137645_Content_10 = {
    Text = "Though with that many legs, entering a running race seems a little unfair on your part..."
  },
  AvgCommunicate_137645_Content_11 = {
    Text = "Castor has wings, and Nautila has brought her vehicle."
  },
  AvgCommunicate_137645_Content_12 = {
    Text = "I spend most of my days weaving at the theater and am not well-suited to sport. Still, I've already signed my maid up on my behalf."
  },
  AvgCommunicate_137645_Content_13 = {
    Text = "Honestly, I can't picture you caring about something like this."
  },
  AvgCommunicate_137645_Content_14 = {
    Text = "Watching people lay bare their will and vitality in pursuit of a shared goal—there is a quiet pleasure in that."
  },
  AvgCommunicate_137645_Content_15 = {
    Text = "And... I'll admit I'm curious about what magic that cake holds, as a prize. Even Tawil seems taken with it."
  },
  AvgCommunicate_137645_Content_16 = {
    Text = "As long as it's not another one of those situations where someone has to choose which world gets destroyed, I'll take it..."
  },
  AvgCommunicate_137645_Content_17 = {
    Text = "...You're not using threads of fate to rig the results, are you?"
  },
  AvgCommunicate_137645_Content_18 = {
    Text = "...Arachne?"
  },
  AvgCommunicate_137645_Content_2 = {
    Text = "What's the matter?"
  },
  AvgCommunicate_137645_Content_20 = {
    Text = "See you in the stands, Keeper."
  },
  AvgCommunicate_137645_Content_3 = {
    Text = "What kind of fate do you think... could truly be called just and right?"
  },
  AvgCommunicate_137645_Content_4 = {
    Text = "Just and right? ...I suppose it would be one that protects the interests of as many people as possible."
  },
  AvgCommunicate_137645_Content_5 = {
    Text = "And if—inevitably—the interests of a few must be sacrificed? You'd accept that as the right course of fate, would you?"
  },
  AvgCommunicate_137645_Content_6 = {
    Text = "Why... Why are you suddenly asking that? Don't read too much into what I said!"
  },
  AvgCommunicate_137645_Content_7 = {
    Text = "If you're thinking about destroying another world, please think it through this time, Arachne!"
  },
  AvgCommunicate_137645_Content_8 = {
    Text = "There's nothing to worry about, Keeper. It's only a running race."
  },
  AvgCommunicate_137645_Content_9 = {
    Text = "Oh thank god... you scared me..."
  },
  AvgCommunicate_137645_Option_2 = {
    Text = "What's the matter?"
  },
  AvgCommunicate_137646_Content_1 = {
    Text = "Keeper, I heard you're setting off on an investigation. I've written something for you."
  },
  AvgCommunicate_137646_Content_10 = {
    Text = "Your titling instincts are something else, Arachne..."
  },
  AvgCommunicate_137646_Content_11 = {
    Text = "Every thread spun has its destined owner. Every story written has its destined reader."
  },
  AvgCommunicate_137646_Content_12 = {
    Text = "A name that travels easily can carry a worthy story to those it was always meant to reach."
  },
  AvgCommunicate_137646_Content_13 = {
    Text = "Take, for instance, the best-selling title..."
  },
  AvgCommunicate_137646_Content_14 = {
    Text = "<Italic:The Joy of Cooking: Seafarer Edition>? That's the best-seller?"
  },
  AvgCommunicate_137646_Content_15 = {
    Text = "Please tell me Doresain didn't bulk-order copies for all of Necrovia..."
  },
  AvgCommunicate_137646_Content_16 = {
    Text = "Does Tulu know about this?"
  },
  AvgCommunicate_137646_Content_18 = {
    Text = "It is precisely this instinct for the human heart—and for fate—that I find so admirable in you."
  },
  AvgCommunicate_137646_Content_19 = {
    Text = "<Italic:Keeper: You've Got a Friend in Me.>"
  },
  AvgCommunicate_137646_Content_2 = {
    Text = "I considered staging a play, but given that you'll be traveling, a novel seemed more practical."
  },
  AvgCommunicate_137646_Content_20 = {
    Text = "Take it with you when you go."
  },
  AvgCommunicate_137646_Content_3 = {
    Text = "These are..."
  },
  AvgCommunicate_137646_Content_4 = {
    Text = "<Italic:The Great Keeper>? <Italic:Keeper Crusoe>? <Italic:Project Hail Mythag>?"
  },
  AvgCommunicate_137646_Content_5 = {
    Text = "What do you even write? Do people actually read this stuff??"
  },
  AvgCommunicate_137646_Content_6 = {
    Text = "Don't underestimate your popularity in Mythag. These are all extremely well-received works."
  },
  AvgCommunicate_137646_Content_7 = {
    Text = "A fate this dramatic deserves to be seen by the world."
  },
  AvgCommunicate_137646_Content_8 = {
    Text = "And it isn't only you. I've woven stories around others' fates as well."
  },
  AvgCommunicate_137646_Content_9 = {
    Text = "<Italic:AP Combat: 5 Years of Practice Tests>... <Italic:Postpartum Care of Mice>... <Italic:Fifty Shades of Wax>..."
  },
  AvgCommunicate_137646_Option_3 = {
    Text = "These are..."
  },
  AvgCommunicate_137647_Content_1 = {
    Text = "With invisible threads, I connect those separated by time and space..."
  },
  AvgCommunicate_137647_Content_10 = {
    Text = "I look forward to it, Keeper."
  },
  AvgCommunicate_137647_Content_2 = {
    Text = "Human civilization never ceases to amaze me."
  },
  AvgCommunicate_137647_Content_3 = {Text = "Amaze you?"},
  AvgCommunicate_137647_Content_4 = {
    Text = "But aren't these the fates you chose yourself?"
  },
  AvgCommunicate_137647_Content_5 = {
    Text = "What I chose was only the direction. All civilization, all history—you built that yourselves."
  },
  AvgCommunicate_137647_Content_6 = {
    Text = "The threads of fate, left to extend on their own, will always give rise to something new—some origin no one could have foreseen."
  },
  AvgCommunicate_137647_Content_7 = {
    Text = "It is because I have witnessed this, because of the joy found in the weaving, that I am able to carry on."
  },
  AvgCommunicate_137647_Content_8 = {Text = "I see..."},
  AvgCommunicate_137647_Content_9 = {
    Text = "If you create something new, I hope you'll let me see it too."
  },
  AvgCommunicate_137647_Option_3 = {Text = "Amaze you?"},
  AvgCommunicate_140194_Content_1 = {
    Text = "Something feels off. The fact that no one is afraid of me at all..."
  },
  AvgCommunicate_140194_Content_10 = {
    Text = "Don't worry, everyone's been so kind to me! They're safe!"
  },
  AvgCommunicate_140194_Content_11 = {
    Text = "...Probably. For now."
  },
  AvgCommunicate_140194_Content_12 = {
    Text = "For now? ...Please make it a definite!"
  },
  AvgCommunicate_140194_Content_13 = {Text = "For now~!"},
  AvgCommunicate_140194_Content_2 = {
    Text = "Doll developed a special pheromone. Right now, you look like nothing more than an ordinary human girl to everyone."
  },
  AvgCommunicate_140194_Content_4 = {
    Text = "Convenient, I suppose, but..."
  },
  AvgCommunicate_140194_Content_5 = {
    Text = "It's almost a little disappointing that I don't get to scare people anymore?"
  },
  AvgCommunicate_140194_Content_6 = {Text = "...?"},
  AvgCommunicate_140194_Content_7 = {
    Text = "How do I put it... hmm... for example, it's going to make my \"hunting\" harder..."
  },
  AvgCommunicate_140194_Content_8 = {
    Text = "I haven't had trouble finding meals lately, so hunting's not an urgent need, but... sometimes... yeah..."
  },
  AvgCommunicate_140194_Content_9 = {
    Text = "I'm almost used to all the Awakeners saying various deranged stuff at this point, but I still gotta tell you... That's a very dangerous thing to say!"
  },
  AvgCommunicate_140195_Content_1 = {
    Text = "Here's my purchase request..."
  },
  AvgCommunicate_140195_Content_10 = {
    Text = "...And I'll just pretend to be entirely not aware of any of this. Alright?"
  },
  AvgCommunicate_140195_Content_2 = {
    Text = "Four large household refrigerators... The university budget isn't exactly strained, but what do you need these fridges for?"
  },
  AvgCommunicate_140195_Content_3 = {
    Text = "If I remember correctly, Saya, you already requested one to be put in your dorm on the first day of moving here."
  },
  AvgCommunicate_140195_Content_4 = {
    Text = "Well, um... You never know when the fridge space is going to come in handy..."
  },
  AvgCommunicate_140195_Content_5 = {
    Text = "Plus, you know, freshness of the meat is important..."
  },
  AvgCommunicate_140195_Content_6 = {Text = "..."},
  AvgCommunicate_140195_Content_7 = {
    Text = "Sorry, but I can't approve any more refrigerators. I will, however, pass along the contacts of Xu and Doresain."
  },
  AvgCommunicate_140195_Content_9 = {
    Text = "I think you'd have a fun time talking with them about food and recipes."
  },
  AvgCommunicate_140196_Content_1 = {Text = "¥%&#...%"},
  AvgCommunicate_140196_Content_10 = {Text = "..."},
  AvgCommunicate_140196_Content_11 = {
    Text = "Wrong! You're supposed to say Splish Splash!"
  },
  AvgCommunicate_140196_Content_12 = {
    Text = "Apparently, the pheromone Professor Doll developed doesn't work on Miss Vortice."
  },
  AvgCommunicate_140196_Content_13 = {
    Text = "But she still treats me all the same. Her attitude hasn't changed at all."
  },
  AvgCommunicate_140196_Content_14 = {
    Text = "I think that's because, um, how do I put this..."
  },
  AvgCommunicate_140196_Content_15 = {
    Text = "...Perhaps Vortice is just gifted with... extraordinary social skills?"
  },
  AvgCommunicate_140196_Content_2 = {
    Text = "A... Abandon. Ah, another word learned. Hmm."
  },
  AvgCommunicate_140196_Content_3 = {Text = "?"},
  AvgCommunicate_140196_Content_4 = {
    Text = "I've been studying all kinds of languages lately. ...It's fascinating."
  },
  AvgCommunicate_140196_Content_6 = {
    Text = "Besides standard Leonian, I've also picked up a lot of new vocabulary. For example..."
  },
  AvgCommunicate_140196_Content_7 = {
    Text = "Gurgle Gurgle?"
  },
  AvgCommunicate_140196_Content_8 = {
    Text = "Splish Splash!"
  },
  AvgCommunicate_140196_Content_9 = {Text = "Correct!"},
  AvgCommunicate_140196_Option_10 = {Text = "..."},
  AvgCommunicate_140196_Option_8 = {
    Text = "Splish Splash!"
  },
  AvgCommunicate_141374_Content_1 = {
    Text = "A solemn, formal thank-you might come off a little stiff—but from the bottom of my heart, thank you. For my own sake, and for all of Ebwynnos."
  },
  AvgCommunicate_141374_Content_10 = {
    Text = "I act that way because it's simply who I am."
  },
  AvgCommunicate_141374_Content_12 = {
    Text = "Do you really have to sound so proud of that?"
  },
  AvgCommunicate_141374_Content_13 = {
    Text = "So helping me reach that limit, and shake off His control—you really did me an enormous favor."
  },
  AvgCommunicate_141374_Content_14 = {
    Text = "A great many things that were beyond me before are no longer any trouble at all."
  },
  AvgCommunicate_141374_Content_15 = {
    Text = "Is it too late for me to take it all back?"
  },
  AvgCommunicate_141374_Content_16 = {
    Text = "Calm down, Pontos—Londinium has a complete and functioning legal system!"
  },
  AvgCommunicate_141374_Content_2 = {
    Text = "You getting all serious out of nowhere... it's honestly a little unsettling."
  },
  AvgCommunicate_141374_Content_3 = {
    Text = "You probably don't realize what this means. Until I grew strong enough, Ebwynnos could never truly break free of that ancient being's control."
  },
  AvgCommunicate_141374_Content_4 = {
    Text = "It was the deal I struck with Him. Luckily, He bore no real ill will—you could even call Him magnanimous."
  },
  AvgCommunicate_141374_Content_5 = {
    Text = "But in the end He isn't human. Under His hold, Ebwynnos grew harder to grasp, and the people within it turned more extreme in temperament."
  },
  AvgCommunicate_141374_Content_6 = {
    Text = "By that logic... were you the way you were before because of His influence too? You know, all that, uh—"
  },
  AvgCommunicate_141374_Content_7 = {
    Text = "Let me guess. You want to say obsessive, vindictive—or control freak?"
  },
  AvgCommunicate_141374_Content_9 = {Text = "No."},
  AvgCommunicate_141374_Option_2 = {
    Text = "It's unsettling..."
  },
  AvgCommunicate_141374_Option_6 = {
    Text = "Was it His influence..."
  },
  AvgCommunicate_143429_Content_1 = {
    Text = "As farcical as these cultists and their false gods are, I have to admit—a few of them actually have rather decent taste."
  },
  AvgCommunicate_143429_Content_10 = {
    Text = "And they don't even fit the era!"
  },
  AvgCommunicate_143429_Content_11 = {
    Text = "Personally, I believe a little cultural enrichment like this might spark some ambition in you. It could do wonders to curb the sheer number of distress calls you send during field ops."
  },
  AvgCommunicate_143429_Content_12 = {
    Text = "Of course, as long as the sweet \"Uncle\" calls keep coming, I'm always happy to bail out my unambitious little {Male=nephew,Female=niece}."
  },
  AvgCommunicate_143429_Content_13 = {
    Text = "...That's it, I'm going to have a word with Goliath right now."
  },
  AvgCommunicate_143429_Content_14 = {
    Text = "I'm adding those to Mythag's banned film list. No more reckless recommendations!"
  },
  AvgCommunicate_143429_Content_2 = {
    Text = "I was already shocked a few days ago when he kept sneaking out of Mythag behind Miryam's back..."
  },
  AvgCommunicate_143429_Content_3 = {
    Text = "You don’t mean Goliath, do you?"
  },
  AvgCommunicate_143429_Content_4 = {
    Text = "Hmm, first of all, I quite admire his resolve—willing to play second fiddle to Miryam just to get what he wants."
  },
  AvgCommunicate_143429_Content_5 = {
    Text = "And secondly, the plays he recommended are genuinely fascinating."
  },
  AvgCommunicate_143429_Content_6 = {
    Text = "I can't even picture Goliath sitting in a theater."
  },
  AvgCommunicate_143429_Content_7 = {
    Text = "He recommended <Italic:Once Upon a Time in Leonia> and <Italic:The Go▼father> to me—everyone loved them."
  },
  AvgCommunicate_143429_Content_8 = {
    Text = "Tonight, Ebwynnos should be staging <Italic:The Wolf of Londinium>."
  },
  AvgCommunicate_143429_Content_9 = {
    Text = "No—wait, hold on. Mythag doesn't allow mob bosses, and we certainly don't allow this whole \"wolf culture\" thing either!"
  },
  AvgCommunicate_143429_Option_2 = {
    Text = "Wait, you don't mean..."
  },
  AvgCommunicate_143430_Content_1 = {
    Text = "The sixth immigration application this month. It seems the Administration Office's regulations don't always do the trick."
  },
  AvgCommunicate_143430_Content_10 = {
    Text = "Ah. What a shame."
  },
  AvgCommunicate_143430_Content_11 = {
    Text = "Huh??? Wait—what?! Why is there a Gaunt pulling out the exam answers and sitting down to write my essay?!"
  },
  AvgCommunicate_143430_Content_12 = {
    Text = "You're carrying way too much on your shoulders. Even if you're just joking, it's a clear sign you need to take a break, kiddo."
  },
  AvgCommunicate_143430_Content_13 = {
    Text = "Just this once. As much as I'd love to, I'd better not spoil you rotten."
  },
  AvgCommunicate_143430_Content_14 = {
    Text = "Now, open your window. Let's go have some fun tonight. I'll make you forget reality without heading to Ebwynnos."
  },
  AvgCommunicate_143430_Content_15 = {Text = "...Yay!"},
  AvgCommunicate_143430_Content_3 = {
    Text = "GPA, attendance, practice-to-credit conversion rates—ugh, and the employment anxiety that most ordinary students face but Keepers don't."
  },
  AvgCommunicate_143430_Content_4 = {
    Text = "Even with Dissolution looming over our heads, real-world problems are still scary as hell."
  },
  AvgCommunicate_143430_Content_5 = {
    Text = "It's normal to want to escape reality sometimes. Honestly, why don't you just bring me along to Ebwynnos too..."
  },
  AvgCommunicate_143430_Content_6 = {
    Text = "Are you serious?"
  },
  AvgCommunicate_143430_Content_7 = {
    Text = "Is that really the sound of flapping wings outside my window, or am I just hallucinating after three straight nights of cramming?"
  },
  AvgCommunicate_143430_Content_8 = {
    Text = "Now or never. Since you're finally giving me the chance, I'm absolutely taking it—even if all of Mythag comes after me for it."
  },
  AvgCommunicate_143430_Content_9 = {
    Text = "Nonono I was joking please don't do that."
  },
  AvgCommunicate_143431_Content_1 = {
    Text = "Looking for me?"
  },
  AvgCommunicate_143431_Content_10 = {
    Text = "Hahahahaha—alright, alright, drop that face."
  },
  AvgCommunicate_143431_Content_11 = {
    Text = "Procuring his personal seal is child's play. As for the charity gala, how about we host it in Ebwynnos?"
  },
  AvgCommunicate_143431_Content_12 = {
    Text = "Next thing you know, the police will have us all locked up for breaking and entering."
  },
  AvgCommunicate_143431_Content_14 = {
    Text = "Fine. A pity, but I'll lie low for a few days."
  },
  AvgCommunicate_143431_Content_15 = {
    Text = "Killing him while his guard is down might be far more entertaining, anyway."
  },
  AvgCommunicate_143431_Content_16 = {Text = "???!"},
  AvgCommunicate_143431_Content_2 = {
    Text = "Uh, Pontos, would you consider heading back to Ebwynnos for a while?"
  },
  AvgCommunicate_143431_Content_3 = {
    Text = "Professor Dexter hasn't shown up at Mythag for two whole months."
  },
  AvgCommunicate_143431_Content_4 = {
    Text = "Hah. That spineless little filth—right about now, he's probably throwing a tantrum at some poor wretch under his command."
  },
  AvgCommunicate_143431_Content_5 = {
    Text = "Don't worry. Until he returns to his Genesis, he isn't even qualified to be my opponent."
  },
  AvgCommunicate_143431_Content_6 = {
    Text = "The problem is, a mountain of paperwork is waiting for his personal seal! What are we supposed to do about this year's charity banquet?! Dean Czort and Professor Doll would sooner blow up Mythag than attend an event like this."
  },
  AvgCommunicate_143431_Content_7 = {
    Text = "And if Professor Sylvia hosts it instead... well, we'd have entirely different things to worry about..."
  },
  AvgCommunicate_143431_Content_8 = {
    Text = "How heartbreaking, little one. I see—you're sheltered by so many people at Mythag now, you don't need me anymore. And after all I've done for you, you'd even..."
  },
  AvgCommunicate_145234_Content_1 = {
    Text = "It has gone quiet."
  },
  AvgCommunicate_145234_Content_10 = {
    Text = "So... you don't want to fight anymore?"
  },
  AvgCommunicate_145234_Content_11 = {Text = "Hah..."},
  AvgCommunicate_145234_Content_12 = {
    Text = "Of course not."
  },
  AvgCommunicate_145234_Content_13 = {
    Text = "I no longer need combat to quiet my body, but..."
  },
  AvgCommunicate_145234_Content_14 = {
    Text = "Now, I can use my strength more freely, and challenge whoever I want!"
  },
  AvgCommunicate_145234_Content_15 = {
    Text = "I think... I owe you my thanks."
  },
  AvgCommunicate_145234_Content_16 = {
    Text = "You brought me to a peak I've long yearned for. But..."
  },
  AvgCommunicate_145234_Content_17 = {
    Text = "The path of strength has no end. Right, Keeper?"
  },
  AvgCommunicate_145234_Content_2 = {
    Text = "Quiet? What do you mean?"
  },
  AvgCommunicate_145234_Content_3 = {
    Text = "My blood's stopped boiling. My bones, stopped aching. My blade no longer roars..."
  },
  AvgCommunicate_145234_Content_4 = {
    Text = "Ever since the moment I was born, they never once stopped."
  },
  AvgCommunicate_145234_Content_5 = {
    Text = "Now, they're all silent."
  },
  AvgCommunicate_145234_Content_6 = {
    Text = "Is that a bad thing?"
  },
  AvgCommunicate_145234_Content_7 = {
    Text = "Are you okay?"
  },
  AvgCommunicate_145234_Content_8 = {
    Text = "The noise before—it was just hunger. A desperate itch from not being strong enough, fast enough."
  },
  AvgCommunicate_145234_Content_9 = {
    Text = "Now it's gone. My body feels... sated for the first time."
  },
  AvgCommunicate_145234_Option_6 = {
    Text = "Is that a bad thing?"
  },
  AvgCommunicate_145234_Option_7 = {
    Text = "Are you okay?"
  },
  AvgCommunicate_146392_Content_1 = {Text = "You there?"},
  AvgCommunicate_146392_Content_10 = {
    Text = "I paid her to let me take the job instead."
  },
  AvgCommunicate_146392_Content_11 = {
    Text = "Did you find it?"
  },
  AvgCommunicate_146392_Content_12 = {
    Text = "It's right in front of me. Sleeping soundly."
  },
  AvgCommunicate_146392_Content_13 = {
    Text = "I'm waiting for it to wake up."
  },
  AvgCommunicate_146392_Content_14 = {
    Text = "...Fair enough."
  },
  AvgCommunicate_146392_Content_15 = {
    Text = "Let me think of some way for you to kill time..."
  },
  AvgCommunicate_146392_Content_16 = {
    Text = "Oh, I know! You could..."
  },
  AvgCommunicate_146392_Content_17 = {
    Text = "Its eyes are twitching... It's waking up."
  },
  AvgCommunicate_146392_Content_18 = {Text = "Gotta go."},
  AvgCommunicate_146392_Content_19 = {
    Text = "Hey? Lotan?"
  },
  AvgCommunicate_146392_Content_2 = {Text = "?"},
  AvgCommunicate_146392_Content_3 = {
    Text = "Lotan? I thought you had no interest in these things."
  },
  AvgCommunicate_146392_Content_4 = {
    Text = "Just bored. Testing out this gadget Doll gave me."
  },
  AvgCommunicate_146392_Content_5 = {
    Text = "Might come in handy someday."
  },
  AvgCommunicate_146392_Content_6 = {
    Text = "You? Bored?"
  },
  AvgCommunicate_146392_Content_7 = {
    Text = "I thought you were either fighting or looking for a fight."
  },
  AvgCommunicate_146392_Content_8 = {
    Text = "Speaking of which, where are you? Haven't seen you in days..."
  },
  AvgCommunicate_146392_Content_9 = {
    Text = "Heard Daffodil's been hunting some powerful ancient thing."
  },
  AvgCommunicate_146392_Option_14 = {
    Text = "...Fair enough."
  },
  AvgCommunicate_146392_Option_6 = {
    Text = "You? Bored?"
  },
  AvgCommunicate_146393_Content_1 = {
    Text = "Horns. Teeth. Claws. Flesh. Eyeballs. Tentacles."
  },
  AvgCommunicate_146393_Content_10 = {
    Text = "Hope you can be just as tough."
  },
  AvgCommunicate_146393_Content_11 = {Text = "..."},
  AvgCommunicate_146393_Content_12 = {
    Text = "Gee, thanks."
  },
  AvgCommunicate_146393_Content_2 = {Text = "Pick one."},
  AvgCommunicate_146393_Content_3 = {
    Text = "Is this some kind of \"guess what you'd like\" game...?"
  },
  AvgCommunicate_146393_Content_4 = {
    Text = "I brought back the monster I killed last time."
  },
  AvgCommunicate_146393_Content_5 = {
    Text = "Nowhere to put it anyway, figured you'd want a souvenir."
  },
  AvgCommunicate_146393_Content_6 = {
    Text = "None of those sound appealing..."
  },
  AvgCommunicate_146393_Content_7 = {
    Text = "Is it weird if I want them all..."
  },
  AvgCommunicate_146393_Content_8 = {
    Text = "Tough call... how about you just pick for me..."
  },
  AvgCommunicate_146393_Content_9 = {
    Text = "The horn's good. Took three strikes before it broke. It suits you."
  },
  AvgCommunicate_146393_Option_6 = {
    Text = "None of those sound appealing..."
  },
  AvgCommunicate_146393_Option_7 = {
    Text = "Is it weird if I want them all..."
  },
  AvgCommunicate_146394_Content_1 = {
    Text = "I've got a problem."
  },
  AvgCommunicate_146394_Content_10 = {
    Text = "I left three times. Every time I did, they started sacrificing themselves. Apparently, they thought it was some divine trial."
  },
  AvgCommunicate_146394_Content_11 = {
    Text = "They're all nuts."
  },
  AvgCommunicate_146394_Content_12 = {
    Text = "And why did you even go back??"
  },
  AvgCommunicate_146394_Content_13 = {
    Text = "I didn't pull my blade out of its corpse."
  },
  AvgCommunicate_146394_Content_14 = {
    Text = "Now they've enshrined it too."
  },
  AvgCommunicate_146394_Content_15 = {Text = "..."},
  AvgCommunicate_146394_Content_16 = {
    Text = "I need to get my blade back without them committing mass suicide in front of me."
  },
  AvgCommunicate_146394_Content_17 = {
    Text = "You understand these weak little creatures better than I do. Help me out."
  },
  AvgCommunicate_146394_Content_18 = {
    Text = "...Hey, what's that supposed to mean?!"
  },
  AvgCommunicate_146394_Content_2 = {
    Text = "Wow, so even you run into trouble sometimes!"
  },
  AvgCommunicate_146394_Content_3 = {
    Text = "Heard there was a strong worm, so I killed it."
  },
  AvgCommunicate_146394_Content_4 = {
    Text = "After it died, the people long trapped inside the planet beneath its bulk came crawling out."
  },
  AvgCommunicate_146394_Content_5 = {
    Text = "They called me a god, bowed to me, and even built me a golden statue—ugly as hell."
  },
  AvgCommunicate_146394_Content_6 = {Text = "HAHAHAHAHA"},
  AvgCommunicate_146394_Content_7 = {
    Text = "Stop laughing."
  },
  AvgCommunicate_146394_Content_8 = {
    Text = "Why didn't you just walk away?"
  },
  AvgCommunicate_146394_Content_9 = {
    Text = "Don't you like being worshipped?"
  },
  AvgCommunicate_146394_Option_6 = {Text = "HAHAHAHA"},
  AvgCommunicate_146394_Option_8 = {
    Text = "Why not just walk away?"
  },
  AvgCommunicate_146394_Option_9 = {
    Text = "Don't you like being worshipped?"
  },
  AvgCommunicate_148438_Content_1 = {
    Text = "I guess you already know, hmm?"
  },
  AvgCommunicate_148438_Content_10 = {
    Text = "Hee hee, don't overthink it~ People who overthink turn into boring, no-fun grown-ups~"
  },
  AvgCommunicate_148438_Content_11 = {
    Text = "Though of course, if the Keeper simply can't help being drawn to the Fairy—if you find yourself chasing after my every step, day and night, just to earn my true affection—well, that would be perfectly understandable~"
  },
  AvgCommunicate_148438_Content_12 = {Text = "Ugh..."},
  AvgCommunicate_148438_Content_13 = {
    Text = "I've already left the sweetest candy apple of the bunch on the desk in your dorm."
  },
  AvgCommunicate_148438_Content_14 = {
    Text = "Now you must, absolutely must, savor it slowly, examine every bite, and enjoy it all by yourself~"
  },
  AvgCommunicate_148438_Content_2 = {
    Text = "So you went through all that trouble to get an outing permit... just to buy Aigis, Ogier, and Murphy some limited-edition candy apples they said they'd never tried?"
  },
  AvgCommunicate_148438_Content_3 = {
    Text = "Those little bra—ahem—those devout children may not have paid their membership dues in full, but they play an absolutely vital role in spreading the Fairy's blessings far and wide."
  },
  AvgCommunicate_148438_Content_4 = {
    Text = "Nurturing my flock, so they'll spread the good word all the more eagerly—why, that's just one more heavy burden the Fairy carries on her shoulders~"
  },
  AvgCommunicate_148438_Content_5 = {
    Text = "Even if you had a good reason this time, why is it MY account you keep charging it to..."
  },
  AvgCommunicate_148438_Content_7 = {
    Text = "Oh, don't sweat the little details~ Look, the children are true believers now. So when are you finally going to come join them, hmm?"
  },
  AvgCommunicate_148438_Content_9 = {
    Text = "I honestly can't tell if you let a sliver of your real self slip out now and then, or if you're just an onion, forever hiding your real goal under one more layer..."
  },
  AvgCommunicate_148439_Content_1 = {Text = "[Image]"},
  AvgCommunicate_148439_Content_10 = {
    Text = "[Image loaded successfully]"
  },
  AvgCommunicate_148439_Content_11 = {Text = "[Image]"},
  AvgCommunicate_148439_Content_12 = {
    Text = "What... it really is an apology letter..."
  },
  AvgCommunicate_148439_Content_13 = {
    Text = "I'm sorry... Caraboo. I shouldn't have reacted like that when you were finally being sincere for once."
  },
  AvgCommunicate_148439_Content_14 = {
    Text = "I'll go withdraw the complaint I just filed right now. The one recommending grounding you... denying all outing requests... There! I've withdrawn every complaint I ever filed against you."
  },
  AvgCommunicate_148439_Content_15 = {
    Text = "Wonderful~ Hee hee, Keeper—I do believe that once a complaint is withdrawn, you can't file any new one against the same Awakener for a whole month, can you?"
  },
  AvgCommunicate_148439_Content_17 = {
    Text = "I have a very bad feeling about this..."
  },
  AvgCommunicate_148439_Content_18 = {
    Text = "Oh my, the Fairy would never be so ungracious as to toy with %player%'s sincere heart~ Every word in that apology letter was the honest truth. When I get back from my outing, I'll be sure to bring you the sweetest red apple~"
  },
  AvgCommunicate_148439_Content_19 = {
    Text = "Wait! Why did Aigis just come to me in tears, saying that even though she has no idea what she did wrong, she hopes I'll forgive her once I see the apology letter?"
  },
  AvgCommunicate_148439_Content_2 = {Text = "Loading..."},
  AvgCommunicate_148439_Content_20 = {
    Text = "And that you promised to pass it along for her—but she decided to apologize to my face as well just to make sure I wouldn't be angry with her again?!"
  },
  AvgCommunicate_148439_Content_21 = {
    Text = "Hey, Caraboo. CARABOO!!"
  },
  AvgCommunicate_148439_Content_3 = {Text = "?"},
  AvgCommunicate_148439_Content_4 = {
    Text = "Caraboo, you've already pulled this trick once. Whatever you say, I am NOT opening this image."
  },
  AvgCommunicate_148439_Content_5 = {
    Text = "No, %player%... I've truly reflected on it. You, and everyone in Mythag, have been so kind to me. I really shouldn't have brought my old ways into this beautiful place."
  },
  AvgCommunicate_148439_Content_6 = {
    Text = "After all, I never chose to become who I am, not at the very start."
  },
  AvgCommunicate_148439_Content_7 = {
    Text = "So I sat down and wrote you a proper apology letter—handwritten, every single word, by my own hand~ But wouldn't you know it, the Communicator just happened to glitch at this exact moment..."
  },
  AvgCommunicate_148439_Content_8 = {
    Text = "I get it if you don't believe me. I'll just... wait. However long it takes for you to trust me again..."
  },
  AvgCommunicate_148439_Content_9 = {
    Text = "...Ugh, why is my conscience acting up? Anyway, there is no way I'm..."
  },
  AvgCommunicate_148440_Content_1 = {Text = "[Image]"},
  AvgCommunicate_148440_Content_10 = {
    Text = "What are you talking about? As if I'd ever pay you back!"
  },
  AvgCommunicate_148440_Content_11 = {Text = "Huh?"},
  AvgCommunicate_148440_Content_12 = {
    Text = "You're not even pretending anymore?"
  },
  AvgCommunicate_148440_Content_13 = {
    Text = "Hehee. Serving the Fairy is itself your greatest honor. It will lead you to a paradise beyond compare. Next to that, worldly repayment is hardly worth mentioning, of course."
  },
  AvgCommunicate_148440_Content_14 = {
    Text = "Enough of all that! If you don't wire the money soon, the map will be lost for good..."
  },
  AvgCommunicate_148440_Content_16 = {
    Text = "I already looked at that thing you sent me. It was clearly faked with some crappy Silver tech..."
  },
  AvgCommunicate_148440_Content_17 = {
    Text = "Oh? You opened it? That was entirely your own choice, you know~ Wonderful! *The Fairy will remember %player%'s offering forever.*"
  },
  AvgCommunicate_148440_Content_18 = {
    Text = "Wait, why am I getting a notice that 1,000 Florins just got deducted—that's my fieldwork stipend!"
  },
  AvgCommunicate_148440_Content_2 = {Text = "Loading..."},
  AvgCommunicate_148440_Content_20 = {
    Text = "There, there. You're pretty loaded, aren't you? I'll only take 200 Florins this time—as payment for the kind lesson that you shouldn't go opening unknown links on your comms. Do be grateful for the Fairy's mercy, hmm?"
  },
  AvgCommunicate_148440_Content_21 = {
    Text = "[Transfer: 800 Leonian Florins]"
  },
  AvgCommunicate_148440_Content_3 = {
    Text = "[Image Corrupted]"
  },
  AvgCommunicate_148440_Content_4 = {
    Text = "...What did you send?"
  },
  AvgCommunicate_148440_Content_5 = {Text = "Oh no!"},
  AvgCommunicate_148440_Content_6 = {
    Text = "We're screwed! That image held a map to the East, seized through the blood, sweat, and tears of my devoted followers—and now the original's corrupted along with it! It must be some evil @2 trying to stop us from reaching the East!"
  },
  AvgCommunicate_148440_Content_7 = {
    Text = "%player%, how many Florins do you have on you? Quick, give me all of them! There's still a chance to recover it..."
  },
  AvgCommunicate_148440_Content_8 = {
    Text = "Let me guess, you'll pay me back tenfold once you reach the East. I'm not born yesterday, you know."
  },
  AvgCommunicate_148440_Content_9 = {
    Text = "A scam that doesn't keep up with the times has no future."
  },
  AvgCommunicate_149803_Content_1 = {
    Text = "The escort mission the Academy previously entrusted to me has been completed. Is there anything you need me to do, my lord?"
  },
  AvgCommunicate_149803_Content_10 = {
    Text = "In any case, if you're unwilling to idle about, there are many activities at the academy in a few days — why not go and enjoy yourself?"
  },
  AvgCommunicate_149803_Content_11 = {
    Text = "...Since it is my lord's command, I will comply."
  },
  AvgCommunicate_149803_Content_12 = {
    Text = "I will go on patrol now."
  },
  AvgCommunicate_149803_Content_13 = {
    Text = "I hope you'll actually follow through later!"
  },
  AvgCommunicate_149803_Content_2 = {
    Text = "Won't you take a rest?"
  },
  AvgCommunicate_149803_Content_3 = {
    Text = "There is no need."
  },
  AvgCommunicate_149803_Content_4 = {
    Text = "Besides... I have no right to enjoy such peace."
  },
  AvgCommunicate_149803_Content_5 = {
    Text = "That dark shadow still disturbs me from time to time, whispering in my ear."
  },
  AvgCommunicate_149803_Content_6 = {
    Text = "Perhaps when I have tasks at hand, I am actually more at ease."
  },
  AvgCommunicate_149803_Content_7 = {
    Text = "That is all. Please do not worry about it, my lord."
  },
  AvgCommunicate_149803_Content_8 = {
    Text = "Perhaps I need to teach you the necessity of slacking off."
  },
  AvgCommunicate_149803_Content_9 = {
    Text = "You'll fight better if you relax more."
  },
  AvgCommunicate_149803_Option_8 = {
    Text = "Perhaps I need to teach you the necessity of slacking off."
  },
  AvgCommunicate_149803_Option_9 = {
    Text = "You'll fight better if you relax more."
  },
  AvgCommunicate_149950_Content_10 = {
    Text = "Hmph... are you mocking me? This is already the limit of how much I can control this body right now!"
  },
  AvgCommunicate_149950_Content_11 = {
    Text = "What are you trying to do? Keep goading him and manipulating him?"
  },
  AvgCommunicate_149950_Content_12 = {
    Text = "If I could, I would have long since..."
  },
  AvgCommunicate_149950_Content_13 = {
    Text = "Never mind. Rather than becoming a blade, being a shield or a bulwark doesn't seem so bad either..."
  },
  AvgCommunicate_149950_Content_14 = {
    Text = "As for the master he trusts and serves — you — getting to know you has actually been quite interesting."
  },
  AvgCommunicate_149950_Content_15 = {
    Text = "I see it now. You've been influenced by Ogier in return, haven't you."
  },
  AvgCommunicate_149950_Content_16 = {Text = "..."},
  AvgCommunicate_149950_Content_17 = {Text = "???"},
  AvgCommunicate_149950_Content_18 = {
    Text = "My lord, I sincerely apologize. I suddenly blanked out for a few minutes just now."
  },
  AvgCommunicate_149950_Content_19 = {
    Text = "When I came to, I found the communicator lit up."
  },
  AvgCommunicate_149950_Content_2 = {
    Text = "I've finally found you..."
  },
  AvgCommunicate_149950_Content_20 = {
    Text = "I have a feeling... I just heard that irritating voice again after such a long time..."
  },
  AvgCommunicate_149950_Content_21 = {
    Text = "How to put it... it seems you and the power within you have already learned to coexist quite harmoniously."
  },
  AvgCommunicate_149950_Content_22 = {
    Text = "...I've read through the log."
  },
  AvgCommunicate_149950_Content_23 = {
    Text = "I was worried it would speak wicked, aggressive words like it used to."
  },
  AvgCommunicate_149950_Content_24 = {
    Text = "It's truly surprising. It was always I who was eroded by it before — and now it seems the roles have reversed."
  },
  AvgCommunicate_149950_Content_25 = {
    Text = "This should be a good thing. At least... it means I have completely overcome It."
  },
  AvgCommunicate_149950_Content_26 = {
    Text = "Of course, could it be that the enhancement of Ogier's power is what allowed control over this intangible thing to reach such a level?"
  },
  AvgCommunicate_149950_Content_27 = {
    Text = "Mm, that must be it. These changes have certainly all come about because of you."
  },
  AvgCommunicate_149950_Content_28 = {
    Text = "And for me, the \"Ultimate Law\" I have come to understand is not merely power..."
  },
  AvgCommunicate_149950_Content_29 = {
    Text = "There is also this conviction to protect others, burning in my chest with greater fervor than ever before. I believe that is where the true source lies."
  },
  AvgCommunicate_149950_Content_3 = {
    Text = "You're not Ogier. Who are you?"
  },
  AvgCommunicate_149950_Content_4 = {
    Text = "Give the communicator back to its owner!"
  },
  AvgCommunicate_149950_Content_5 = {
    Text = "How laughable. Without my existence, how could this child have survived, and how could he have remained here as an Awakener?"
  },
  AvgCommunicate_149950_Content_6 = {
    Text = "You are... the invisible presence attached to him?"
  },
  AvgCommunicate_149950_Content_7 = {
    Text = "Precisely. And yet you don't recognize me, Mythag's Keeper."
  },
  AvgCommunicate_149950_Content_8 = {
    Text = "Well... you've always been so thoroughly suppressed by Ogier that I've simply never seen you before."
  },
  AvgCommunicate_149950_Option_3 = {
    Text = "You're not Ogier. Who are you?"
  },
  AvgCommunicate_149950_Option_4 = {
    Text = "Give the communicator back to its owner!"
  },
  AvgCommunicate_149986_Content_1 = {
    Text = "My lord, I have come to extend an invitation to you."
  },
  AvgCommunicate_149986_Content_10 = {Text = "...A tree."},
  AvgCommunicate_149986_Content_11 = {Text = "Huh?"},
  AvgCommunicate_149986_Content_12 = {
    Text = "Perhaps it's because of my professional training — no matter how chaotic things get, I can stand perfectly still on stage."
  },
  AvgCommunicate_149986_Content_13 = {
    Text = "Just what is going to happen in your play?!"
  },
  AvgCommunicate_149986_Content_14 = {
    Text = "I wouldn't know. I'm just a tree."
  },
  AvgCommunicate_149986_Content_15 = {
    Text = "...Well, during the performance, Jenkin, who plays the princess, will descend from above, and Lily, who plays the prince, has to catch her."
  },
  AvgCommunicate_149986_Content_16 = {
    Text = "Aigis, who plays the demon king, also has to come off the stage and interact with the audience."
  },
  AvgCommunicate_149986_Content_17 = {
    Text = "I've given up trying to comment on the casting..."
  },
  AvgCommunicate_149986_Content_18 = {
    Text = "But doesn't this count as spoiling it for me?"
  },
  AvgCommunicate_149986_Content_19 = {
    Text = "Because I don't want to keep anything from you."
  },
  AvgCommunicate_149986_Content_2 = {
    Text = "The drama club is staging a fairy tale play and has invited the underage Awakeners in Mythag to perform together."
  },
  AvgCommunicate_149986_Content_20 = {
    Text = "Besides, judging by how rehearsals have gone, something different goes wrong every time. I can't guarantee what you'll actually end up seeing."
  },
  AvgCommunicate_149986_Content_21 = {
    Text = "...That does make it rather intriguing."
  },
  AvgCommunicate_149986_Content_22 = {
    Text = "The things that happen during the performance carry a certain degree of danger, after all."
  },
  AvgCommunicate_149986_Content_23 = {
    Text = "So while playing the role of a tree, I also need to keep an eye on the situation both on and off the stage to ensure the safety of the actors and the audience."
  },
  AvgCommunicate_149986_Content_24 = {
    Text = "So you were actually moonlighting as a bodyguard... that sounds really tough."
  },
  AvgCommunicate_149986_Content_25 = {
    Text = "Indeed. In any case, please rest assured. As long as I am still on stage, I will not let anyone get hurt again."
  },
  AvgCommunicate_149986_Content_3 = {
    Text = "It's a little embarrassing to say... I'll be on stage too. I hope you'll come watch."
  },
  AvgCommunicate_149986_Content_4 = {
    Text = "! I'm looking forward to it."
  },
  AvgCommunicate_149986_Content_5 = {
    Text = "Still, I didn't expect you to agree to take part in something like this."
  },
  AvgCommunicate_149986_Content_6 = {
    Text = "Well, I'm no longer a child, so it doesn't really suit me to be involved."
  },
  AvgCommunicate_149986_Content_7 = {
    Text = "But they insisted..."
  },
  AvgCommunicate_149986_Content_8 = {
    Text = "I didn't want to dampen their spirits, and besides, I realized this particular role truly could only be played by me."
  },
  AvgCommunicate_149986_Content_9 = {
    Text = "So, what role will Ogier be playing? A knight?"
  },
  AvgCommunicate_149987_Content_1 = {
    Text = "My lord, are there any courses related to the Dissolution Phenomenon recently?"
  },
  AvgCommunicate_149987_Content_10 = {
    Text = "How studious... If I were as hardworking as you, I definitely wouldn't have to worry about exams."
  },
  AvgCommunicate_149987_Content_11 = {
    Text = "Please don't flatter me like that. The responsibilities you bear are far more demanding than mine."
  },
  AvgCommunicate_149987_Content_12 = {
    Text = "Besides, this is merely the necessary work I do as penance."
  },
  AvgCommunicate_149987_Content_13 = {
    Text = "But you learn so quickly — who knows, Ogier might just have the makings of a scholar."
  },
  AvgCommunicate_149987_Content_14 = {
    Text = "Like the topic everyone thinks about when they're young — what the future holds."
  },
  AvgCommunicate_149987_Content_15 = {
    Text = "Has Ogier ever thought about what you want to do when you grow up?"
  },
  AvgCommunicate_149987_Content_16 = {
    Text = "You know I have become an Awakener. There is no longer any possibility of growing up."
  },
  AvgCommunicate_149987_Content_17 = {
    Text = "You can still dream about your plans for the future! No need to be so pessimistic."
  },
  AvgCommunicate_149987_Content_18 = {
    Text = "Is there nothing Ogier wants to do beyond \"protecting others\"?"
  },
  AvgCommunicate_149987_Content_19 = {
    Text = "Thank you for the encouragement."
  },
  AvgCommunicate_149987_Content_2 = {
    Text = "I would like to study it more in depth."
  },
  AvgCommunicate_149987_Content_20 = {
    Text = "As for other things I want to do... I'm sorry, I really can't think of any."
  },
  AvgCommunicate_149987_Content_21 = {
    Text = "When this body is no longer stained with sin, I'll think about it then."
  },
  AvgCommunicate_149987_Content_3 = {
    Text = "Of course, I'll take you along next time."
  },
  AvgCommunicate_149987_Content_4 = {
    Text = "But why has Ogier suddenly taken an interest in learning about this?"
  },
  AvgCommunicate_149987_Content_5 = {
    Text = "Because someone asked me today whether the power wrapped around my body is related to D-Slime."
  },
  AvgCommunicate_149987_Content_6 = {
    Text = "I see. Just looking at the form, they do resemble each other a little."
  },
  AvgCommunicate_149987_Content_7 = {
    Text = "Yes, I have always been curious about the true nature of this invisible force. Perhaps understanding it well enough will allow me to control it better."
  },
  AvgCommunicate_149987_Content_8 = {
    Text = "Though since coming to Mythag, I've found that there are far more incomprehensible things than I ever imagined..."
  },
  AvgCommunicate_149987_Content_9 = {
    Text = "So I've decided to first learn more about D-Slime and all things related to it. After all, it is also the enemy my lord has long been fighting against."
  },
  AvgCommunicate_149988_Content_1 = {
    Text = "Ah, my disobedient little puppy, always running wild across the globe."
  },
  AvgCommunicate_149988_Content_10 = {
    Text = "Nobody cares about your William."
  },
  AvgCommunicate_149988_Content_11 = {
    Text = "Just don't forget: you are my personal pet puppy. Any threat to your pathetic life is simply a loss of my assets."
  },
  AvgCommunicate_149988_Content_12 = {
    Text = "Besides, I handpicked this specific world—a little rift, safe from the Dissolution."
  },
  AvgCommunicate_149988_Content_13 = {
    Text = "So watch your step. Try not to break it."
  },
  AvgCommunicate_149988_Content_2 = {
    Text = "Your signal is cutting out again. What godforsaken wasteland have you crawled into this time?"
  },
  AvgCommunicate_149988_Content_3 = {
    Text = "I'm in Hyperborea."
  },
  AvgCommunicate_149988_Content_4 = {
    Text = "I'm way up in the highlands."
  },
  AvgCommunicate_149988_Content_5 = {
    Text = "We're preparing to climb a mountain next. Honestly, I'm a bit worried about my stamina."
  },
  AvgCommunicate_149988_Content_6 = {
    Text = "The air is incredibly thin up here. Feels like I'll pass out if I run more than a few steps."
  },
  AvgCommunicate_149988_Content_7 = {
    Text = "And you actually think you can climb a mountain like that? What a reckless, brainless little puppy, utterly clueless about your own limits."
  },
  AvgCommunicate_149988_Content_8 = {
    Text = "I know you're just worried, but I have things I need to finish."
  },
  AvgCommunicate_149988_Content_9 = {
    Text = "Don't worry, Senior William is here with me. We'll be fine."
  },
  AvgCommunicate_149988_Option_3 = {
    Text = "Hyperborea."
