  AvgCommunicate_150103_Content_1 = {
    Text = "A faint tremor ripples through the far reaches of fate's tapestry."
  },
  AvgCommunicate_150103_Content_10 = {
    Text = "Is this another thread in your tapestry of fate?"
  },
  AvgCommunicate_150103_Content_11 = {
    Text = "On this, the loom must remain silent."
  },
  AvgCommunicate_150103_Content_12 = {
    Text = "What about the people who live in this world? What happens to them now?"
  },
  AvgCommunicate_150103_Content_13 = {
    Text = "They shall return to their purest essence—the Silver Cores."
  },
  AvgCommunicate_150103_Content_14 = {
    Text = "And the God-King will salvage those fragments from the endless rain, reshaping the world after a long, quiet slumber."
