  AvgCommunicate_57903_Content_2 = {
    Text = "Hello, Bishop Salvador."
  },
  AvgCommunicate_57903_Content_3 = {
    Text = "Looks like you've received the latest communicator. How is it?"
  },
  AvgCommunicate_57903_Content_4 = {
    Text = "It's very interesting and convenient. Even though we are hundreds of miles away, we can still communicate as if we were face-to-face."
  },
  AvgCommunicate_57903_Content_5 = {
    Text = "If the whole world had such devices, the distance between people would not be as vast as it is now."
  },
  AvgCommunicate_57903_Content_6 = {
    Text = "But I understand the uniqueness of this technology—you know it transmits information by connecting our spirits, right?"
  },
  AvgCommunicate_57903_Content_7 = {
    Text = "I only know there's a Silver Core inside."
  },
  AvgCommunicate_57903_Content_8 = {
    Text = "Did you find out how it works?"
  },
  AvgCommunicate_57903_Content_9 = {
    Text = "Indeed. Our spirits connect to a Silver Core, which is then linked to the Cores in other similar devices."
  },
  AvgCommunicate_57903_Option_2 = {
