  AvgCommunicate_57905_Content_2 = {
    Text = "Hey! Did you take my clothes!?"
  },
  AvgCommunicate_57905_Content_3 = {
    Text = "Oh dear, Master. Why are you already awake? Your clothes haven't dried yet!"
  },
  AvgCommunicate_57905_Content_4 = {
    Text = "\"Haven't dried yet\"? Are you washing my clothes?"
  },
  AvgCommunicate_57905_Content_5 = {
    Text = "Of course! As a qualified maid, I couldn't possibly let my Master go out wearing dirty, wrinkled clothing!"
  },
  AvgCommunicate_57905_Content_6 = {
    Text = "So I stayed up all~ night and washed all of your clothes tho~rough~ly~!"
  },
  AvgCommunicate_57905_Content_7 = {
    Text = "You can't just wash everything and leave nothing for me to wear!"
  },
  AvgCommunicate_57905_Content_8 = {
    Text = "Well, Master DOES still have some clothes. Honestly, I really wanted to wash that too, but... Master was wrapped up so snugly in bed that I couldn't take it off without waking you up~."
  },
  AvgCommunicate_57905_Content_9 = {
    Text = "...I'm changing the lock."
  },
  AvgCommunicate_57905_Option_11 = {
    Text = "No! Do NOT come in my room!"
  },
  AvgCommunicate_57905_Option_2 = {
    Text = "Did you take my clothes!?"
  },
  AvgCommunicate_57905_Option_4 = {
    Text = "\"Haven't dried yet\"? Are you washing my clothes?"
  },
  AvgCommunicate_57905_Option_7 = {
    Text = "Leave some clothes for me to wear at least!"
  },
  AvgCommunicate_57905_Option_9 = {
    Text = "...I'm changing the lock."
  },
  AvgCommunicate_57906_Content_1 = {
    Text = "Mmm... let me see if this thing works..."
  },
  AvgCommunicate_57906_Content_2 = {
    Text = "Is there someone out there who's unfulfilled and needs a little bit of my whip?"
  },
  AvgCommunicate_57906_Content_3 = {
    Text = "Not really..."
  },
  AvgCommunicate_57906_Content_4 = {
    Text = "Don't be shy! Don't hide your desires!"
  },
  AvgCommunicate_57906_Content_5 = {
    Text = "Yield to them! Free them! Let them run wild!"
  },
  AvgCommunicate_57906_Content_6 = {
    Text = "LET LOOSE YOUR DESIRES!"
  },
  AvgCommunicate_57906_Content_7 = {
    Text = "...I'm turning my communicator off."
  },
  AvgCommunicate_57906_Content_8 = {
    Text = "It's quite rare to find such a convenient and private way to talk with you. Don't be afraid; it's our little secret."
  },
  AvgCommunicate_57906_Content_9 = {
    Text = "If you ever need some private service, you can call me over anytime!"
  },
  AvgCommunicate_57906_Option_3 = {
    Text = "Not really..."
  },
  AvgCommunicate_57906_Option_7 = {
    Text = "...I'm turning my communicator off."
  },
  AvgCommunicate_57907_Content_1 = {
    Text = "Miss Doll asked if there was anything I wanted to do."
  },
  AvgCommunicate_57907_Content_10 = {
    Text = "...Haven't heard that before."
  },
  AvgCommunicate_57907_Content_11 = {
    Text = "Well, if you're still unsure, how about starting with what you're good at?"
  },
  AvgCommunicate_57907_Content_12 = {
    Text = "Considering your background, I'd say you're quite skilled at training soldiers. Why not start there?"
  },
  AvgCommunicate_57907_Content_13 = {
    Text = "Training, you say. That... could work."
  },
  AvgCommunicate_57907_Content_14 = {
    Text = "Thank you, Keeper."
  },
  AvgCommunicate_57907_Content_2 = {
    Text = "I'm... a bit confused."
  },
  AvgCommunicate_57907_Content_3 = {
    Text = "Did she immediately assign you work?"
  },
  AvgCommunicate_57907_Content_4 = {
    Text = "Exploiting you already, huh?"
  },
  AvgCommunicate_57907_Content_5 = {
    Text = "Hahaha... it's not like that. I'm the one that offered to help, but... I'm not sure what I can do to help..."
  },
  AvgCommunicate_57907_Content_6 = {
    Text = "I've been a soldier my entire life; just following other people's orders. Even when I was in Remouahe, I was never really sure about what I should do."
  },
  AvgCommunicate_57907_Content_7 = {
    Text = "Suddenly being told to decide what to do myself... It's a new experience for me."
  },
  AvgCommunicate_57907_Content_8 = {
    Text = "Miss Doll probably asked because she was worried that I wouldn't be able to adapt to civilian life."
  },
  AvgCommunicate_57907_Content_9 = {
    Text = "She may appear cold, but she's actually quite considerate of others."
  },
  AvgCommunicate_57907_Option_10 = {
    Text = "Haven't heard that before."
  },
  AvgCommunicate_57907_Option_3 = {
    Text = "Did she immediately assign you work?"
  },
  AvgCommunicate_57907_Option_4 = {
    Text = "Exploiting you already, huh?"
  },
  AvgCommunicate_57908_Content_1 = {
    Text = "Tonight at 10 o'clock, in the underground classroom: a secret party, a new game; an exciting experience awaits you!"
  },
  AvgCommunicate_57908_Content_10 = {
    Text = "Be grateful I didn't decide to report you."
  },
  AvgCommunicate_57908_Content_11 = {
