  AvgCommunicate_57999_Content_10 = {
    Text = "Keeper, don't listen to her. Aigis will protect your candy..."
  },
  AvgCommunicate_57999_Content_11 = {
    Text = "Absolutely!"
  },
  AvgCommunicate_57999_Content_2 = {
    Text = "There's training in the afternoon. What's up, little Aigis?"
  },
  AvgCommunicate_57999_Content_3 = {
    Text = "Aigis made candies she wanted to share at the afternoon tea party..."
  },
  AvgCommunicate_57999_Content_4 = {
    Text = "If the Keeper is busy, I can secretly set some aside for you..."
  },
  AvgCommunicate_57999_Content_5 = {
    Text = "Thank you, little Aigis. I'd love that."
  },
  AvgCommunicate_57999_Content_6 = {
    Text = "Hey, you! How dare you brush aside Aigis's invitation like that!"
  },
  AvgCommunicate_57999_Content_7 = {Text = "?"},
  AvgCommunicate_57999_Content_8 = {
    Text = "Listen up! If I don't see you at the tea party this afternoon, I'll have Brown steal all your candy!"
  },
  AvgCommunicate_57999_Content_9 = {Text = "..."},
  AvgCommunicate_57999_Option_2 = {
    Text = "What's up, little Aigis?"
  },
  AvgCommunicate_57999_Option_5 = {
    Text = "I'd love that."
  },
  AvgCommunicate_57999_Option_7 = {Text = "?"},
  AvgCommunicate_57999_Option_9 = {Text = "..."},
  AvgCommunicate_58020_Content_1 = {
    Text = "I'm so glad we'll have more opportunities to work together in the future."
  },
  AvgCommunicate_58020_Content_10 = {
    Text = "...Would it bother you if I send you too many messages?"
  },
  AvgCommunicate_58020_Content_11 = {
    Text = "Of course not."
  },
  AvgCommunicate_58020_Content_2 = {Text = "That's..."},
  AvgCommunicate_58020_Content_3 = {
    Text = "Tell Doll I said thanks..."
  },
  AvgCommunicate_58020_Content_5 = {
    Text = "Even if there aren't any pressing matters..."
  },
  AvgCommunicate_58020_Content_6 = {
    Text = "Is it alright if I send you a message?"
  },
  AvgCommunicate_58020_Content_7 = {Text = "Of course!"},
  AvgCommunicate_58020_Content_8 = {
    Text = "We will always be good partners."
  },
  AvgCommunicate_58020_Content_9 = {Text = "Thank you."},
  AvgCommunicate_58020_Option_7 = {Text = "Of course!"},
  AvgCommunicate_58021_Content_2 = {
    Text = "Another round?"
  },
  AvgCommunicate_58021_Content_4 = {
    Text = "Spare me..."
  },
  AvgCommunicate_58021_Content_5 = {
    Text = "Giving up so soon?"
