  AvgCommunicate_58498_Content_1 = {
    Text = "Good evening, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgCommunicate_58498_Content_11 = {
    Text = "How cute. Were you playing hard to get~?"
  },
  AvgCommunicate_58498_Content_12 = {
    Text = "I'll be at the chapel. Don't make me wait long~."
  },
  AvgCommunicate_58498_Content_2 = {
