  },
  AvgCommunicate_58498_Content_6 = {
    Text = "How unfortunate. Oh well, I suppose I'll wander around the campus and see if I can find someone else who is interested..."
  },
  AvgCommunicate_58498_Content_7 = {Text = "!!"},
  AvgCommunicate_58498_Content_8 = {
    Text = "Wait, Ms. Wanda! Don't go anywhere."
  },
  AvgCommunicate_58498_Content_9 = {
    Text = "I'm coming over."
