  AvgCommunicate_58498_Option_7 = {Text = "!!"},
  AvgCommunicate_60943_Content_1 = {
    Text = "Partner, we're short-handed for this mission. I need to head to the forward position early to prepare, so I'm afraid I won't be able to operate with you."
  },
  AvgCommunicate_60943_Content_10 = {
    Text = "I know. You always think of everything for everyone."
  },
  AvgCommunicate_60943_Content_11 = {
    Text = "But maybe it's time you learned to trust me with watching your back? Partner."
  },
  AvgCommunicate_60943_Content_12 = {Text = "..."},
  AvgCommunicate_60943_Content_13 = {
    Text = "You're right."
  },
  AvgCommunicate_60943_Content_14 = {
    Text = "Then I'll leave it in your hands this time, partner."
  },
  AvgCommunicate_60943_Content_2 = {
    Text = "I've written several contingency plans for you. If any emergencies arise, you can check the corresponding entry."
  },
  AvgCommunicate_60943_Content_3 = {
    Text = "I've also requested additional Emergency Gnosis for you. Even though we're short on people, I'll do my best to arrange for someone else to accompany you."
  },
  AvgCommunicate_60943_Content_4 = {Text = "Ramona."},
  AvgCommunicate_60943_Content_5 = {
    Text = "I know you're worried about me. Thank you for everything you've done."
  },
  AvgCommunicate_60943_Content_6 = {
    Text = "But I'm no longer the weak and clueless person I was when I first enrolled. I can handle it."
  },
  AvgCommunicate_60943_Content_7 = {
    Text = "Of course I trust your abilities, it's just..."
  },
  AvgCommunicate_60943_Content_8 = {
    Text = "I'm sorry, I'm used to running through every possible scenario. If I'm not there, I can't help but think of the worst possibilities."
  },
  AvgCommunicate_60943_Content_9 = {
    Text = "I can't bear the thought of failing to prevent the worst..."
  },
  AvgCommunicate_60943_Option_10 = {
    Text = "I know. You always think of everything for everyone."
  },
  AvgCommunicate_60943_Option_4 = {Text = "Ramona."},
  AvgCommunicate_66973_Content_1 = {
    Text = "Keeper, thank you so much for suggesting that my sister and I go to the gathering together."
  },
  AvgCommunicate_66973_Content_10 = {
    Text = "She's so cute when she blushes."
  },
  AvgCommunicate_66973_Content_11 = {
    Text = "Wow, the bond between you sisters is really deep..."
  },
  AvgCommunicate_66973_Content_12 = {
    Text = "Of course. My sister will always be the most important person to me, and I'll keep taking care of her."
  },
  AvgCommunicate_66973_Content_13 = {
    Text = "I guess it’s my turn to help her navigate social events from now on."
  },
  AvgCommunicate_66973_Content_14 = {
    Text = "If you get the chance, Keeper, come join us!"
  },
  AvgCommunicate_66973_Content_15 = {
    Text = "Sounds good!"
  },
  AvgCommunicate_66973_Content_2 = {
    Text = "You're welcome! Happy to help!"
  },
  AvgCommunicate_66973_Content_3 = {
    Text = "I used to always depend on my sister, and she always acted so strong in front of me—even a bit tough."
  },
  AvgCommunicate_66973_Content_4 = {
    Text = "I never expected that she'd be so flustered in that kind of situation. I've never seen her look so shy before."
  },
  AvgCommunicate_66973_Content_5 = {
    Text = "Hm? I always thought Faint was just the reserved type."
  },
  AvgCommunicate_66973_Content_6 = {
    Text = "No, actually my sister has a very strong-willed personality, and she's quite decisive!"
  },
  AvgCommunicate_66973_Content_7 = {
    Text = "Whenever I felt lost and fragile, it was always my sister who came up with ideas for me. She would stroke my head and gently comfort me."
  },
  AvgCommunicate_66973_Content_8 = {
    Text = "I see. That's something I wouldn't have expected."
  },
  AvgCommunicate_66973_Content_9 = {
    Text = "But now that we no longer have to fight to survive, my sister can finally start making friends."
  },
  AvgCommunicate_66973_Option_11 = {
    Text = "Wow, the bond between you sisters is really strong..."
  },
  AvgCommunicate_66973_Option_15 = {
    Text = "Sounds good!"
  },
  AvgCommunicate_66973_Option_2 = {
    Text = "You're welcome! Happy to help!"
  },
  AvgCommunicate_66973_Option_5 = {
    Text = "Hm? I always thought Faint was just the reserved type."
  },
  AvgCommunicate_66973_Option_8 = {
    Text = "I see. That's something I wouldn't have expected."
  },
  AvgCommunicate_66974_Content_1 = {Text = "Hungry."},
  AvgCommunicate_66974_Content_10 = {
    Text = "Well, obviously..."
  },
  AvgCommunicate_66974_Content_11 = {
    Text = "I'm hungry!"
  },
  AvgCommunicate_66974_Content_12 = {
    Text = "Okay, okay, let me think... How about you drink my blood? I'll let you have a taste to satisfy your craving."
