  AvgCommunicate_66975_Content_1 = {
    Text = "Master!! My whole world, my whole life... it's all over! Waaaaah—"
  },
  AvgCommunicate_66975_Content_10 = {
    Text = "That sounds pretty nice."
  },
  AvgCommunicate_66975_Content_11 = {
    Text = "Hmph. I immediately emptied all my savings to buy those pretty little trinkets and wore them all."
  },
  AvgCommunicate_66975_Content_12 = {
    Text = "Hmm... Don't you find them heavy?"
  },
  AvgCommunicate_66975_Content_13 = {
    Text = "But then, when Karen went to attend to Lady Sorel, the Lady took just one look and said all those gems were fakes! They were just cheap fakes!!"
  },
  AvgCommunicate_66975_Content_14 = {
    Text = "How could this happen? How much money did she scam you out of?"
  },
  AvgCommunicate_66975_Content_15 = {
    Text = "A full 500 Florins!!"
  },
  AvgCommunicate_66975_Content_16 = {
    Text = "You'd have to be crazy to think five hundred would buy the real thing!!! What happened to all your years of savings??"
  },
  AvgCommunicate_66975_Content_17 = {
    Text = "B-because Karen loves sparkly things so much, whenever Karen gets money it all goes to buying sparkly stuff, so Karen hasn't saved up much..."
  },
  AvgCommunicate_66975_Content_18 = {
    Text = "Whatever... Look, if all you care about is shiny stones, these stones are indeed shiny enough, and the craftsmanship is actually quite fine."
  },
  AvgCommunicate_66975_Content_19 = {
    Text = "Compared to buying the real thing, you actually saved a fortune. What's there to be upset about?"
