  },
  AvgCommunicate_66975_Content_20 = {
    Text = "Oh, you're right!"
  },
  AvgCommunicate_66975_Content_21 = {
    Text = "Karen actually scored a bargain! Thank you, Master!"
  },
  AvgCommunicate_66975_Content_3 = {
    Text = "It's Daffodil, that treacherous woman! She took all of Karen's hard-earned savings!"
  },
  AvgCommunicate_66975_Content_4 = {
    Text = "Daffodil ripped you off? What did you buy from her?"
  },
  AvgCommunicate_66975_Content_5 = {
    Text = "It's all because Karen was sighing over the jewelry prices in a magazine, and that wicked woman happened to see Karen."
  },
  AvgCommunicate_66975_Content_6 = {
    Text = "She told Karen that she had a batch of gemstone jewelry on special sale. Nobody wanted them because the designs were a bit dated, but they'd be perfect for Karen's vintage look..."
