  AvgCommunicate_66980_Content_1 = {
    Text = "Excuse me, what is this intricate mechanical box used for?"
  },
  AvgCommunicate_66980_Content_10 = {
    Text = "Stop researching it! You don't need to know THAT much about it! It's too expensive for you to be messing with it!"
  },
  AvgCommunicate_66980_Content_11 = {
    Text = "Then tell me what this box is supposed to do."
  },
  AvgCommunicate_66980_Content_12 = {
    Text = "It's a communicator the school gave you. It'll let you communicate with other people remotely, or used to call for help if you're in danger."
  },
  AvgCommunicate_66980_Content_13 = {
    Text = "I see, what an interesting invention. Thank you, Keeper."
  },
  AvgCommunicate_66980_Content_14 = {
    Text = "Do you actually remember who I am?"
  },
  AvgCommunicate_66980_Content_15 = {
    Text = "Of course I do. I promised I would never forget you!"
  },
  AvgCommunicate_66980_Content_16 = {
    Text = "You're my friend, %player%!"
  },
  AvgCommunicate_66980_Content_2 = {
    Text = "? Did you forget again?"
  },
  AvgCommunicate_66980_Content_3 = {
    Text = "Forgot? I can't recall where this box came from."
  },
  AvgCommunicate_66980_Content_4 = {
    Text = "But I saw the chat logs. I think I've used it before, but I don't remember how to use it now..."
  },
  AvgCommunicate_66980_Content_5 = {
    Text = "Then how are you using it now?!"
  },
  AvgCommunicate_66980_Content_6 = {Text = "Hehe."},
  AvgCommunicate_66980_Content_7 = {
    Text = "Stop laughing! This is serious!"
  },
  AvgCommunicate_66980_Content_8 = {
