  AvgCommunicate_66981_Content_1 = {
    Text = "Keeper, what are your thoughts on human emotions?"
  },
  AvgCommunicate_66981_Content_10 = {
    Text = "Then what about you? As the Aeon of Sagacity, aren't you supposed to be absolutely rational?"
  },
  AvgCommunicate_66981_Content_11 = {
    Text = "You're perceptive, Keeper, which is one reason I've always tried to minimize my contact with the world."
  },
  AvgCommunicate_66981_Content_12 = {
    Text = "When I remain aloof from the world and avoid maintaining overly close ties with humans, I am able to keep my thoughts clear and independent."
  },
  AvgCommunicate_66981_Content_13 = {
    Text = "It's like if I had never tasted the sweetness of cake, I wouldn't constantly develop a preference for it in my thoughts."
  },
  AvgCommunicate_66981_Content_14 = {
    Text = "I see... So, you want to eat some small cakes now?"
  },
  AvgCommunicate_66981_Content_15 = {
    Text = "It's not a necessity, but if it's convenient for you, I'd be very grateful."
  },
  AvgCommunicate_66981_Content_2 = {
    Text = "Such a profound topic right from the start!"
  },
  AvgCommunicate_66981_Content_3 = {
    Text = "Emotions... everyone has them, after all, we are only human."
  },
  AvgCommunicate_66981_Content_4 = {
    Text = "Exactly. Humans exist relying on their flesh, and emotions arise from instinctual reactions."
  },
  AvgCommunicate_66981_Content_5 = {
    Text = "Most human choices are influenced by emotions rather than rational thinking, which requires constraint and conscious effort."
  },
  AvgCommunicate_66981_Content_6 = {
    Text = "Indeed, maintaining absolute rationality at all times seems possible only for Professor Doll."
  },
  AvgCommunicate_66981_Content_7 = {
    Text = "No, Doll can't do it either. She still holds emotional attachments and will take a desperate gamble when making decisions."
  },
  AvgCommunicate_66981_Content_8 = {
    Text = "Is this how it is? Are all people like this, including those twisted and mad individuals?"
  },
  AvgCommunicate_66981_Content_9 = {
    Text = "Yes. Extreme choices are more profoundly driven by emotions."
  },
  AvgCommunicate_66981_Option_10 = {
    Text = "Then what about you? As the Aeon of Sagacity, aren't you supposed to be absolutely rational?"
  },
  AvgCommunicate_66981_Option_14 = {
    Text = "I see... So, you want to eat some small cakes now?"
  },
  AvgCommunicate_66981_Option_2 = {
    Text = "Such a profound topic right from the start!"
  },
  AvgCommunicate_66981_Option_6 = {
    Text = "Indeed, maintaining absolute rationality at all times seems possible only for Professor Doll."
  },
  AvgCommunicate_66981_Option_8 = {
    Text = "Is this how it is? Are all people like this, including those twisted and mad individuals?"
  },
  AvgCommunicate_66982_Content_1 = {
    Text = "Keeper, I'm giving you a chance to win my favor."
  },
  AvgCommunicate_66982_Content_10 = {
    Text = "Why don't you just sell me while you're at it?"
  },
  AvgCommunicate_66982_Content_11 = {
    Text = "How am I supposed to get my hands on a luxury trinket like that—money alone isn't enough!"
  },
  AvgCommunicate_66982_Content_12 = {
    Text = "I don't care! Figure something out. That bunny must be longing to come to me too."
  },
  AvgCommunicate_66982_Content_13 = {
    Text = "I've already named her—Ivy!"
  },
  AvgCommunicate_66982_Content_14 = {
    Text = "She'll have tea parties with me, along with Jenny and Oliver."
  },
  AvgCommunicate_66982_Content_15 = {
    Text = "Alright, alright, alright... Let me go beg Lady Sorel. I'll make sure Ivy joins your little circle eventually."
  },
  AvgCommunicate_66982_Content_16 = {
    Text = "Hmph, now that's more like it!"
  },
  AvgCommunicate_66982_Content_2 = {
    Text = "You want some limited-edition cupcakes again?"
  },
  AvgCommunicate_66982_Content_3 = {
    Text = "Is food the only thing you think I care about?!"
  },
  AvgCommunicate_66982_Content_4 = {
    Text = "Well, what else..."
  },
  AvgCommunicate_66982_Content_5 = {
    Text = "Hmph, cake is nice too, but this time it's not about food."
  },
  AvgCommunicate_66982_Content_6 = {
    Text = "I saw in that magazine you brought back—Londinium Department Store just launched a new line of artisan plush dolls."
  },
  AvgCommunicate_66982_Content_7 = {
    Text = "And there’s this one special black-and-pink bunny!"
  },
  AvgCommunicate_66982_Content_8 = {
    Text = "It practically has my name written all over it! The magazine says it's a one-of-a-kind masterpiece. Hurry up and buy it for me!"
  },
  AvgCommunicate_66982_Content_9 = {
    Text = "A masterpiece?"
  },
  AvgCommunicate_66982_Option_10 = {
    Text = "Why don't you just sell me while you're at it?"
  },
  AvgCommunicate_66982_Option_15 = {
    Text = "Alright, alright, alright..."
  },
  AvgCommunicate_66982_Option_2 = {
    Text = "You want some limited-edition cupcakes again?"
  },
  AvgCommunicate_66982_Option_4 = {
    Text = "Well, what else..."
  },
  AvgCommunicate_66982_Option_9 = {
    Text = "A masterpiece?"
  },
  AvgCommunicate_66983_Content_1 = {
    Text = "Hey, you don't need to bring me any cakes these days."
  },
  AvgCommunicate_66983_Content_10 = {
    Text = "And with a dazzling array of ingredients, you can add as much as you want—it's absolutely delightful!"
  },
  AvgCommunicate_66983_Content_11 = {
    Text = "Isn't that the key point?! Won't adding too much make it sickeningly sweet?"
  },
  AvgCommunicate_66983_Content_12 = {
    Text = "What do you know? My new creations have earned endless praise from those chefs!"
  },
  AvgCommunicate_66983_Content_13 = {
    Text = "Production started yesterday, and it's already on the cafeteria shelves. There are plenty of people lining up!"
  },
  AvgCommunicate_66983_Content_14 = {
    Text = "So, you were the one who made that new mini cake that was instantly bought up yesterday!"
  },
  AvgCommunicate_66983_Content_15 = {
    Text = "Hahahahaha, am I amazing or not? Call me a genius!"
  },
  AvgCommunicate_66983_Content_16 = {Text = "Genius!"},
  AvgCommunicate_66983_Content_17 = {
    Text = "But I suddenly realized that homemade cakes might taste better. Keeping this up from now on isn't a bad idea."
  },
  AvgCommunicate_66983_Content_18 = {
    Text = "How genuinely delightful. The young lady has finally experienced the joy of labor."
  },
  AvgCommunicate_66983_Content_2 = {
    Text = "What is this I'm seeing? What catastrophe struck you?"
  },
  AvgCommunicate_66983_Content_3 = {
    Text = "What catastrophe? I'm perfectly fine!"
  },
  AvgCommunicate_66983_Content_4 = {
    Text = "Then what's going on?"
  },
  AvgCommunicate_66983_Content_5 = {
    Text = "Sigh, it's just that I've gotten completely tired of the cafeteria's little cakes recently, and those empty-headed chefs have no intention of introducing new ones!"
  },
  AvgCommunicate_66983_Content_6 = {
    Text = "Indeed, no one has such a massive craving for cupcakes as you do..."
  },
  AvgCommunicate_66983_Content_7 = {
    Text = "It's all their fault for being so incompetent, so I stormed into the kitchen and made them teach me how to bake a cake."
  },
  AvgCommunicate_66983_Content_8 = {
    Text = "Huh? You, cooking?"
  },
  AvgCommunicate_66983_Content_9 = {
    Text = "Surprise! Then I discovered that making a cake isn't difficult at all! I'm simply a natural genius!"
  },
  AvgCommunicate_66983_Option_11 = {
