  AvgCommunicate_66984_Content_1 = {
    Text = "{Male=Sir,Female=Miss} %player%, I've encountered a small problem. Would you lend a hand?"
  },
  AvgCommunicate_66984_Content_10 = {
    Text = "But I told him that I already had a dance partner."
  },
  AvgCommunicate_66984_Content_11 = {
    Text = "In truth, I’ve only just come to find my lovely partner."
  },
  AvgCommunicate_66984_Content_12 = {
    Text = "I think, {Male=he,Female=she} wouldn't bear to let me attend the ball all alone, right?"
  },
  AvgCommunicate_66984_Content_13 = {
    Text = "What do you say?"
  },
  AvgCommunicate_66984_Content_14 = {
    Text = "The honor is mine, my lady."
  },
  AvgCommunicate_66984_Content_15 = {
    Text = "It seems I'd better brush up on my steps and etiquette, lest I step on your toes."
  },
  AvgCommunicate_66984_Content_16 = {
    Text = "You are always so dependable and considerate, my knight."
  },
  AvgCommunicate_66984_Content_2 = {
    Text = "What has got Lady Sorel stumped?"
  },
  AvgCommunicate_66984_Content_3 = {
    Text = "I'm all ears."
  },
  AvgCommunicate_66984_Content_4 = {
    Text = "In a few days, I'll be attending a dinner ball. You know the kind—a bunch of pretentious, fussy people idling about together."
  },
  AvgCommunicate_66984_Content_5 = {
    Text = "What's annoying is that some utterly boorish fellow has been pestering me lately. He’ll be there too, and he made a very public show of asking me to be his partner."
  },
  AvgCommunicate_66984_Content_6 = {
    Text = "What a nuisance. Shall I take care of him for you, my lady?"
  },
  AvgCommunicate_66984_Content_7 = {
    Text = "How delightful. Your sense of humor is truly improving."
  },
  AvgCommunicate_66984_Content_8 = {
    Text = "Unfortunately, that's not an option just yet. Such are the tedious complications of high society. However, I've already declined his invitation."
  },
  AvgCommunicate_66984_Content_9 = {
    Text = "Then isn't the matter settled?"
  },
  AvgCommunicate_66984_Option_14 = {
    Text = "The honor is mine, my lady."
  },
  AvgCommunicate_66984_Option_2 = {
    Text = "What has got Lady Sorel stumped?"
  },
  AvgCommunicate_66984_Option_3 = {
    Text = "I'm all ears."
