  AvgCommunicate_66984_Option_6 = {
    Text = "What a nuisance. Shall I take care of him for you, my lady?"
  },
  AvgCommunicate_66984_Option_9 = {
    Text = "Then isn't the matter settled?"
  },
  AvgCommunicate_66985_Content_1 = {
    Text = "My little knight, thanks to your help at the dance last time, I've successfully shaken off that tiresome fellow."
  },
  AvgCommunicate_66985_Content_10 = {
    Text = "A wish? Then I wish for the beautiful Lady Sorel to share a lavish candlelit dinner with me."
  },
  AvgCommunicate_66985_Content_11 = {
    Text = "Only you and me, no need to entertain anyone else."
  },
  AvgCommunicate_66985_Content_12 = {
    Text = "As you wish, you cunning little thing."
  },
  AvgCommunicate_66985_Content_13 = {
    Text = "What would you like to eat? Tell me, and we'll enjoy it together."
  },
  AvgCommunicate_66985_Content_14 = {
    Text = "My usual dining hall fare hardly prepares me for a lady’s table... but I’d gladly try whatever you enjoy most, my lady."
  },
  AvgCommunicate_66985_Content_15 = {
    Text = "Hehe, what a charming child you are."
  },
  AvgCommunicate_66985_Content_16 = {
    Text = "Then, I shall await your arrival at my estate."
  },
  AvgCommunicate_66985_Content_2 = {
    Text = "To thank you for your kindness and generosity, I'd like to do something for you as a token of my gratitude."
  },
  AvgCommunicate_66985_Content_3 = {
    Text = "You're too kind, Lady Sorel. I thought we were past the point of thank-yous."
  },
  AvgCommunicate_66985_Content_4 = {
    Text = "Indeed, I don't like expressing gratitude in words. Most of the time, it's just hollow pleasantries."
  },
  AvgCommunicate_66985_Content_5 = {
    Text = "However, an opportunity to make any request of me—are you truly not interested?"
  },
  AvgCommunicate_66985_Content_6 = {
    Text = "Wow, any request? If those noble gentlemen heard about this, they'd be green with envy."
  },
  AvgCommunicate_66985_Content_7 = {
    Text = "You always deserve special treatment from me."
  },
  AvgCommunicate_66985_Content_8 = {
    Text = "Now you've really stumped me. So hard to decide... If I went all out and asked for a mansion, would the school discover it..."
  },
  AvgCommunicate_66985_Content_9 = {
    Text = "Don't worry, I'll take care of everything. Feel free to make your wish."
  },
  AvgCommunicate_66985_Option_10 = {Text = "A wish?"},
  AvgCommunicate_66985_Option_14 = {
    Text = "Then I’d love to try whatever you favor most, my lady."
  },
  AvgCommunicate_66985_Option_3 = {
    Text = "You're too kind, Lady Sorel."
  },
  AvgCommunicate_66985_Option_6 = {
    Text = "Wow, any request?"
  },
  AvgCommunicate_66985_Option_8 = {
    Text = "Now you've really stumped me..."
  },
  AvgCommunicate_66986_Content_1 = {
    Text = "I just had a bout with Lotan. We tied."
  },
  AvgCommunicate_66986_Content_10 = {
    Text = "Ahaha... I don't think I have that many distracting thoughts, so I'll pass for now..."
  },
  AvgCommunicate_66986_Content_11 = {
    Text = "Then you're strong too."
  },
  AvgCommunicate_66986_Content_12 = {
    Text = "Unfortunately, there's always someone fishing next to that waterfall. It's a bit noisy."
  },
  AvgCommunicate_66986_Content_13 = {
    Text = "Once I walked out from under the waterfall to ask him to keep it down, and he got so scared he threw his fish in my face and ran off."
  },
  AvgCommunicate_66986_Content_14 = {
    Text = "I wonder if he'll come back."
  },
  AvgCommunicate_66986_Content_15 = {
    Text = "Hmm... I don't think he will..."
  },
  AvgCommunicate_66986_Content_2 = {
    Text = "What happened between you two?"
  },
  AvgCommunicate_66986_Content_3 = {
    Text = "You didn't get into a fight, did you?"
  },
  AvgCommunicate_66986_Content_4 = {
    Text = "No, just a sparring match between warriors."
  },
  AvgCommunicate_66986_Content_5 = {
    Text = "She told me before that my fighting wasn't pure enough. I think I understand now."
  },
  AvgCommunicate_66986_Content_6 = {
    Text = "I found a way to become purer. I'm stronger now."
  },
  AvgCommunicate_66986_Content_7 = {
    Text = "That's a good thing, but what method did you use to become purer?"
  },
  AvgCommunicate_66986_Content_8 = {
    Text = "Stand below a waterfall and let the water wash away your distracting thoughts."
  },
  AvgCommunicate_66986_Content_9 = {
    Text = "It works well. Want to go together?"
