  AvgCommunicate_66987_Content_1 = {
    Text = "Keeper, do you know any fish recipes?"
  },
  AvgCommunicate_66987_Content_10 = {
    Text = "What a kind and gentle old lady."
  },
  AvgCommunicate_66987_Content_11 = {
    Text = "Mm. So, I want to learn how to cook fish. Next time, I want to cook for her instead."
  },
  AvgCommunicate_66987_Content_12 = {
    Text = "That's so touching! You absolutely should! I'll go interrogate the cafeteria cook for you right now!"
  },
  AvgCommunicate_66987_Content_13 = {Text = "Thank you."},
  AvgCommunicate_66987_Content_2 = {
    Text = "Recipes?? You're going to cook?"
  },
  AvgCommunicate_66987_Content_3 = {
    Text = "Mm, after I scared off the angler last time, it's been quiet near the waterfall for quite a while."
  },
  AvgCommunicate_66987_Content_4 = {
    Text = "Recently, an old lady has been coming here to fish. She never makes any noise, so I never showed myself."
  },
  AvgCommunicate_66987_Content_5 = {
    Text = "Then one day, she made a fire and was roasting the fish she caught."
  },
  AvgCommunicate_66987_Content_6 = {
    Text = "The smell was so good that my stomach made a little noise, and she discovered me."
  },
  AvgCommunicate_66987_Content_7 = {
    Text = "Huh? Did you scare her too?"
  },
  AvgCommunicate_66987_Content_8 = {
    Text = "No, she invited me to share the roasted fish. It was delicious."
  },
  AvgCommunicate_66987_Content_9 = {
    Text = "After that, she started bringing a small pot with her, then she'd make fish soup and share it with me."
  },
  AvgCommunicate_66987_Option_10 = {
    Text = "What a kind and gentle old lady."
  },
  AvgCommunicate_66987_Option_12 = {
    Text = "That's so touching! You absolutely should! I'll go interrogate the cafeteria cook for you right now!"
  },
  AvgCommunicate_66987_Option_2 = {
    Text = "Recipes?? You're going to cook?"
  },
  AvgCommunicate_66987_Option_7 = {
    Text = "Huh? Did you scare her too?"
  },
  AvgCommunicate_66988_Content_1 = {
    Text = "Recently got another sum of money, but nearly lost my life in the process. Luckily, Lady Luck is always on my side."
  },
  AvgCommunicate_66988_Content_10 = {
    Text = "But in the middle of our scuffle, his own trap went off and hit him instead."
  },
  AvgCommunicate_66988_Content_11 = {Text = "Huh?"},
  AvgCommunicate_66988_Content_12 = {
    Text = "I even gave him emergency first aid, which is the only reason he was still alive when I brought him to the police station."
  },
  AvgCommunicate_66988_Content_13 = {
    Text = "The police gave me a reward, and the convict went right back to prison. I heard his sentence is being changed to life."
  },
  AvgCommunicate_66988_Content_14 = {
    Text = "He only had a few more years before he would've been released. Why did he have to do something so foolish... Sigh..."
  },
  AvgCommunicate_66988_Content_15 = {
    Text = "Hard to say who's worse off, you or him..."
  },
  AvgCommunicate_66988_Content_16 = {
    Text = "But wait, wasn't someone from the den hounding you for debts yesterday? What happened to the reward?"
  },
  AvgCommunicate_66988_Content_17 = {
    Text = "Ahaha... My luck is limited, after all. If I spend it all on surviving traps, I'm bound to slip up a few times at the table..."
  },
  AvgCommunicate_66988_Content_18 = {
    Text = "Hearing that actually makes me feel a lot better."
  },
  AvgCommunicate_66988_Content_2 = {
    Text = "What happened??"
  },
  AvgCommunicate_66988_Content_3 = {
    Text = "You know I take on detective work, right? My solve rate is so high, I’ve become quite the local celebrity."
  },
  AvgCommunicate_66988_Content_4 = {
    Text = "But that also means the criminals I’ve sent up the river absolutely loathe me."
  },
  AvgCommunicate_66988_Content_5 = {
    Text = "Well, they did lose in the most baffling ways."
  },
  AvgCommunicate_66988_Content_6 = {
    Text = "A couple of days ago, an escapee staked out my usual gambling den for days until he finally caught me."
  },
  AvgCommunicate_66988_Content_7 = {
    Text = "Was he there to get revenge on you?!"
  },
  AvgCommunicate_66988_Content_8 = {
    Text = "That's right. He tailed me for a long time and finally cornered me in an alley."
  },
  AvgCommunicate_66988_Content_9 = {
    Text = "He had set up traps in the alley beforehand, intending to finish me off."
  },
  AvgCommunicate_66988_Option_11 = {Text = "Huh?"},
  AvgCommunicate_66988_Option_15 = {
    Text = "Hard to say who's worse off, you or him..."
  },
  AvgCommunicate_66988_Option_18 = {
    Text = "Hearing that actually makes me feel a lot better."
  },
  AvgCommunicate_66988_Option_2 = {
    Text = "What happened??"
  },
  AvgCommunicate_66988_Option_5 = {
    Text = "Well, they did lose in the most baffling ways."
  },
  AvgCommunicate_66988_Option_7 = {
    Text = "Was he there to get revenge on you?!"
