  AvgCommunicate_66989_Content_1 = {
    Text = "Keeper, I've finished compiling the investigator crisis management plans you asked me about."
  },
  AvgCommunicate_66989_Content_10 = {
    Text = "While I may be more attentive to your needs than that Ramona, don't forget—I was once her too."
  },
  AvgCommunicate_66989_Content_11 = {
    Text = "If you want to fool me, you'll need more practice."
  },
  AvgCommunicate_66989_Content_12 = {
    Text = "Sigh... And to think I came to you with such good faith!"
  },
  AvgCommunicate_66989_Content_13 = {
    Text = "So about that homework—I mean, that question—at least give me a few pointers!"
  },
  AvgCommunicate_66989_Content_14 = {Text = "Ramona?"},
  AvgCommunicate_66989_Content_15 = {Text = "Ramona—"},
  AvgCommunicate_66989_Content_2 = {
    Text = "Wonderful! I knew I could always count on you!"
  },
  AvgCommunicate_66989_Content_3 = {
