  },
  AvgCommunicate_66989_Content_4 = {
    Text = "You know how it is. That Ramona has always been so strict. If I go ask her directly, she'll definitely make me think it through on my own."
  },
  AvgCommunicate_66989_Content_5 = {
    Text = "But here's the thing! I believe learning progresses fastest through mutual discussion and exchange of ideas!"
  },
  AvgCommunicate_66989_Content_6 = {
    Text = "Understood."
  },
  AvgCommunicate_66989_Content_7 = {
