  AvgCommunicate_66991_Content_1 = {
    Text = "Kiiper!! Brown is missing, have you seen it?"
  },
  AvgCommunicate_66991_Content_10 = {
    Text = "I guess that's all we can do for now... Thank you, Kiiper."
  },
  AvgCommunicate_66991_Content_11 = {
    Text = "Since when are you so polite with me? Let me just throw something on and head out... Wait a second."
  },
  AvgCommunicate_66991_Content_12 = {
    Text = "Why is there a familiar-looking tail in my pile of clothes..."
  },
  AvgCommunicate_66991_Content_13 = {
    Text = "Brown?! Is Brown at your place?"
  },
  AvgCommunicate_66991_Content_14 = {
    Text = "Yes, you can stop looking. Also, it got tangled up in my shirt, and it has my sock in its mouth and won't let go. Care to explain why?"
  },
  AvgCommunicate_66991_Content_15 = {
    Text = "Th-that's definitely just its own ratty hobby. It has nothing to do with me!"
  },
  AvgCommunicate_66991_Content_16 = {
    Text = "Worst case, I'll just buy you a new pair of socks, okay?"
  },
  AvgCommunicate_66991_Content_2 = {
    Text = "Brown? Isn't it always with you?"
  },
  AvgCommunicate_66991_Content_3 = {
    Text = "Most of the time, yes, but sometimes it goes out to steal... *ahem* hunt for things. It usually comes back within half a day, but I haven't seen it for a whole day!"
  },
  AvgCommunicate_66991_Content_4 = {
    Text = "Don't panic. Let me help you figure this out. Where does it usually hang out?"
