  AvgCommunicate_66991_Content_5 = {
    Text = "It goes to the kitchen the most, but those idiots could never catch Brown."
  },
  AvgCommunicate_66991_Content_6 = {
    Text = "It might also go to the labs to find some shiny little things, but I've already checked each one. No sign of Brown."
  },
  AvgCommunicate_66991_Content_7 = {
    Text = "...Well, well. So that explains the \"supernatural\" disappearances of lab parts."
  },
  AvgCommunicate_66991_Content_8 = {
    Text = "I've walked around the campus several times already. Could it be... could it have been eaten by that damn school cat?!"
  },
  AvgCommunicate_66991_Content_9 = {
    Text = "Hmm, that school cat probably doesn't have that kind of taste... How about this—I'll go make a batch of lost rat notices right now and put them up around campus. If everyone helps look, we'll definitely find it!"
