  AvgCommunicate_66995_Content_3 = {
    Text = "I can't believe you actually came to me on your own."
  },
  AvgCommunicate_66995_Content_4 = {
    Text = "Cut the nonsense. Do something about that Lotan woman."
  },
  AvgCommunicate_66995_Content_5 = {
    Text = "That lunatic has been hounding me for a whole month."
  },
  AvgCommunicate_66995_Content_6 = {
    Text = "And no matter how hard I hit her, she just won't stay down. It's so annoying!"
  },
  AvgCommunicate_66995_Content_7 = {
