  AvgCommunicate_66995_Content_9 = {
    Text = "Hmph, flattery won't get you anywhere."
  },
  AvgCommunicate_66995_Option_2 = {
    Text = "First, my name isn't Hey..."
  },
  AvgCommunicate_66995_Option_3 = {
    Text = "Second, I can't believe you actually sought me out."
