  },
  AvgCommunicate_66996_Content_1 = {
    Text = "Mythag is such a boring place."
  },
  AvgCommunicate_66996_Content_10 = {
    Text = "Then I hope you find what you're looking for. If you ever want to come back, the gates of Mythag will always be open for you."
  },
  AvgCommunicate_66996_Content_2 = {
    Text = "A bunch of self-proclaimed righteous people, keeping a bunch of collared beasts locked up."
  },
  AvgCommunicate_66996_Content_3 = {
    Text = "I really don't know why that other me is willing to take part in your boring little games. But then again, considering how weak she is, it all makes sense."
  },
  AvgCommunicate_66996_Content_4 = {
    Text = "You've never had someone fiercely stand guard for you, so you wouldn't understand what it means to protect someone."
  },
  AvgCommunicate_66996_Content_5 = {
    Text = "Helot is an outstanding warrior. She just chose to accept the warmth and support others offered her."
  },
  AvgCommunicate_66996_Content_6 = {
    Text = "Hah, suit yourselves. If she's willing to wear a collar, then let her stay here."
  },
  AvgCommunicate_66996_Content_7 = {
    Text = "I'm leaving. Staying here will only dull a warrior’s edge."
  },
  AvgCommunicate_66996_Content_8 = {
    Text = "Alright, I suppose asking where you're headed would be pointless."
  },
  AvgCommunicate_66996_Content_9 = {
    Text = "I'll go wherever I can find power."
  },
  AvgCommunicate_66996_Option_10 = {
    Text = "Then I hope you find what you're looking for."
  },
  AvgCommunicate_66996_Option_4 = {
    Text = "You've never had someone fiercely stand guard for you, so you wouldn't understand what it means to protect someone."
  },
  AvgCommunicate_66996_Option_8 = {
    Text = "Alright, I suppose asking where you're headed would be pointless."
  },
  AvgCommunicate_66997_Content_1 = {
    Text = "Hey, I heard Murphy hasn't been attending class recently. What's going on?"
  },
  AvgCommunicate_66997_Content_10 = {
    Text = "Of course, I'll just seize one back."
  },
  AvgCommunicate_66997_Content_11 = {
    Text = "Hello, is this the police? Someone is about to commit a crime again."
  },
  AvgCommunicate_66997_Content_12 = {
    Text = "Fine, I'll buy one, alright? You meddling fool."
  },
  AvgCommunicate_66997_Content_13 = {
    Text = "Remember, I'm watching you. If you try anything funny with Murphy... Hmph."
  },
  AvgCommunicate_66997_Content_2 = {
    Text = "She ate too many little cakes and got a stomachache. But why don't you ask her yourself?"
  },
  AvgCommunicate_66997_Content_3 = {
    Text = "Enough talk. Did you do something? I saw you kept buying her cakes."
  },
  AvgCommunicate_66997_Content_4 = {
    Text = "What does that have to do with me? She was just greedy and ate the leftover cake she hadn't thrown out the previous day."
  },
  AvgCommunicate_66997_Content_5 = {
    Text = "Wait, how is this even any of your business?"
  },
  AvgCommunicate_66997_Content_6 = {
    Text = "I doubt you'd dare."
  },
  AvgCommunicate_66997_Content_7 = {
    Text = "Hmph, what's so special about a few cakes? I'll find a chef to make them for her every single day."
  },
  AvgCommunicate_66997_Content_8 = {
    Text = "You don't actually think you're her father, do you? I never expected you to have such a fatherly side."
  },
  AvgCommunicate_66997_Content_9 = {
    Text = "Wait, how are you planning to \"find\" a chef?"
  },
  AvgCommunicate_66997_Option_11 = {
    Text = "Hello, is this the police? Someone is about to commit a crime again."
  },
  AvgCommunicate_66997_Option_2 = {
    Text = "She ate too many little cakes and got a stomachache."
  },
  AvgCommunicate_66997_Option_4 = {
    Text = "What does that have to do with me?"
  },
  AvgCommunicate_66997_Option_8 = {
    Text = "I never expected you to show such a fatherly side."
  },
  AvgCommunicate_66998_Content_1 = {
    Text = "The path of the strong is a lonely one indeed."
  },
  AvgCommunicate_66998_Content_10 = {
    Text = "Hard to tell if you did something good or bad there..."
  },
  AvgCommunicate_66998_Content_11 = {
    Text = "Hmph, I just did what the strong are supposed to do."
  },
  AvgCommunicate_66998_Content_12 = {
    Text = "The underworld here has gotten a bit boring now. What should I do next..."
  },
  AvgCommunicate_66998_Content_13 = {
    Text = "Whatever you're planning, I'm telling the police to keep an eye on you."
  },
  AvgCommunicate_66998_Content_2 = {
    Text = "Path? What did you do? Don't tell me you're at the police station again?"
  },
  AvgCommunicate_66998_Content_3 = {
    Text = "Ha, as if those fools could ever hold me."
  },
  AvgCommunicate_66998_Content_4 = {
    Text = "After what happened last time, I've successfully conquered half the underworld of Londinium."
  },
  AvgCommunicate_66998_Content_5 = {
    Text = "Too bad the gangs here are far weaker than my Philistine kinsmen back in the day. They'll never amount to anything great."
  },
  AvgCommunicate_66998_Content_6 = {
    Text = "Gangs?? What illegal stuff have you been up to?"
  },
  AvgCommunicate_66998_Content_7 = {
    Text = "What? If taking down gangs is a crime, then there aren’t any good people left in this world."
  },
  AvgCommunicate_66998_Content_8 = {
    Text = "If you ask me, Mythag or that police department or whatever still owes me a medal of honor."
  },
  AvgCommunicate_66998_Content_9 = {
    Text = "Now that I've beaten them all into submission, haven't you noticed the streets are much safer now?"
  },
  AvgCommunicate_66998_Option_10 = {
    Text = "Hard to tell if you did something good or bad there..."
  },
  AvgCommunicate_66998_Option_13 = {
    Text = "Whatever you're planning, I'm telling the police to keep an eye on you."
  },
  AvgCommunicate_66998_Option_2 = {
    Text = "Path? What did you do? Don't tell me you're at the police station again?"
  },
  AvgCommunicate_66998_Option_6 = {
    Text = "Gangs?? What illegal stuff have you been up to?"
  },
  AvgCommunicate_66999_Content_1 = {
    Text = "{Male=Mr.,Female=Miss} %player%, I was recently invited by Mythag University to help record the class transition music."
  },
  AvgCommunicate_66999_Content_10 = {
    Text = "If I must specify what's special about it, it must be because it's brimming with my need to protect you."
  },
  AvgCommunicate_66999_Content_11 = {
    Text = "Actually, I've always had a bit of trouble getting up. If I had some rousing music, it would probable be easier to get out of bed!"
  },
  AvgCommunicate_66999_Content_12 = {
    Text = "Rousing music? Understood."
  },
  AvgCommunicate_66999_Content_13 = {
    Text = "Even though I think it's more important to get quality sleep, you shoulder such numerous burdens that business is unavoidable."
  },
  AvgCommunicate_66999_Content_14 = {
    Text = "May this march lend you strength!"
  },
  AvgCommunicate_66999_Content_2 = {
    Text = "During the recording session, Professor Doll also mentioned that the school had developed a new type of tape recorder. It's small and portable for missions, has clear audio, and features both recording and playback functions."
  },
  AvgCommunicate_66999_Content_3 = {
    Text = "When I saw it, I thought of you. If you'd like, I can make a recording of the music you like to listen to."
  },
  AvgCommunicate_66999_Content_4 = {
    Text = "That way, even when I'm not by your side, you need not worry about lacking music to soothe your soul."
  },
  AvgCommunicate_66999_Content_5 = {
    Text = "Hameln... I'm so moved!"
  },
  AvgCommunicate_66999_Content_6 = {
    Text = "It's simply fulfilling my duty. Well then, is there anything you wish to listen to?"
  },
  AvgCommunicate_66999_Content_7 = {
