  },
  AvgCommunicate_67000_Content_1 = {
    Text = "{Male=Mr.,Female=Miss} %player%. I've recently composed a new piece and would like to invite you to give it a listen and critique in your free time."
  },
  AvgCommunicate_67000_Content_10 = {
    Text = "Ah, such requests are rather austere. My apologies for being inconsiderate."
  },
  AvgCommunicate_67000_Content_11 = {
    Text = "How about next time I play by your bedside and you allow me to observe and record your sleep."
  },
  AvgCommunicate_67000_Content_12 = {
    Text = "I hope you fall asleep every time under my protection."
  },
  AvgCommunicate_67000_Content_2 = {
    Text = "You're too kind Hameln, but how can a half-baked amateur like me be qualified to critique your work?"
  },
  AvgCommunicate_67000_Content_3 = {
    Text = "No, don't downplay your significance; your suggestions are my greatest source of creative motivation."
  },
  AvgCommunicate_67000_Content_4 = {
    Text = "Really? I'm ashamed to admit this, but I tend to fall asleep when I listen to your new compositions..."
  },
  AvgCommunicate_67000_Content_5 = {
    Text = "Your music is hauntingly beautiful and flawlessly performed, yet it casts some sedative magic on me and I fall asleep instantly. Perhaps I truly lack a musical ear."
  },
  AvgCommunicate_67000_Content_6 = {
    Text = "No, that is exactly what I want."
  },
  AvgCommunicate_67000_Content_7 = {
    Text = "Being able to bring you restful sleep is my mission and duty."
  },
  AvgCommunicate_67000_Content_8 = {
    Text = "Rather, please describe to me in detail the feelings that different pieces bring you, as well as your post-listening sleep quality, how long it takes to fall asleep, the duration of your sleep..."
  },
  AvgCommunicate_67000_Content_9 = {Text = "Huh?"},
  AvgCommunicate_67000_Option_2 = {
    Text = "You're too kind."
  },
  AvgCommunicate_67000_Option_4 = {Text = "Really?"},
  AvgCommunicate_67000_Option_9 = {Text = "Huh?"},
  AvgCommunicate_67001_Content_1 = {
    Text = "Keeper, were you the one who left these new dance shoes at my door?"
  },
  AvgCommunicate_67001_Content_10 = {
    Text = "No, not at all. The dance shoes you gave me inspire my heart and soul."
  },
  AvgCommunicate_67001_Content_11 = {
    Text = "Knowing that someone looks forward to my dancing so much, I'll take it as motivation to keep dancing with all my heart."
  },
  AvgCommunicate_67001_Content_2 = {
    Text = "Ahaha, was it that obvious? I thought I didn't leave any trace?"
  },
  AvgCommunicate_67001_Content_3 = {
    Text = "In Mythag, there really aren't many people who pay such close attention to me and are so considerate of others."
  },
  AvgCommunicate_67001_Content_4 = {
    Text = "I've always been grateful for everything you've done for me. Thank you, Keeper."
  },
  AvgCommunicate_67001_Content_5 = {
    Text = "Now you're making me blush. Actually, I noticed the dance shoes you wore during your last performance were a bit worn, so I thought I'd get you a new pair."
  },
  AvgCommunicate_67001_Content_6 = {
    Text = "Ah, indeed, those dance shoes have been with me for a long time. But for a dancer, newer shoes aren't necessarily better."
  },
  AvgCommunicate_67001_Content_7 = {
    Text = "Huh? Why is that?"
  },
  AvgCommunicate_67001_Content_8 = {
    Text = "A pair of dance shoes must go through countless hours of breaking in to gradually conform to one's feet. The wear on them often reflects the shape of the dancer's own habits."
  },
  AvgCommunicate_67001_Content_9 = {
    Text = "I see. It seems my good intentions backfired."
  },
  AvgCommunicate_67001_Option_2 = {
