  AvgCommunicate_67003_Content_4 = {
    Text = "Happy to help!"
  },
  AvgCommunicate_67003_Content_5 = {
    Text = "Good. Several of my experiments have recently reached critical stages. I've been living in the laboratory for quite some time now and simply can't step away."
  },
  AvgCommunicate_67003_Content_6 = {
    Text = "But this body of mine has worn down a bit and needs to be replaced."
  },
  AvgCommunicate_67003_Content_7 = {
