  AvgCommunicate_67007_Content_1 = {
    Text = "Master, today Aigis told Jenkin and me about the toys at the Workhouse."
  },
  AvgCommunicate_67007_Content_10 = {
    Text = "No, Keeper, don't listen to Jenkin. My doll is perfectly fine. There's no need to buy a new one!"
  },
  AvgCommunicate_67007_Content_11 = {
    Text = "Alright, alright! I'll buy it all! Everything!"
  },
  AvgCommunicate_67007_Content_12 = {
    Text = "Master, the communicator just got grabbed out of my hand and hit the floor. I think a few pieces broke off..."
  },
  AvgCommunicate_67007_Content_13 = {
    Text = "Can we get a new one of these too?"
  },
  AvgCommunicate_67007_Content_14 = {Text = "What???"},
  AvgCommunicate_67007_Content_2 = {
    Text = "She said there's a toy called a tangram, made of seven flat pieces like blocks that can be arranged into lots of patterns and also fit back into a perfect square."
  },
  AvgCommunicate_67007_Content_3 = {
    Text = "Jenkin said we could make one out of paper, but we couldn't picture what it looked like no matter how hard we tried."
  },
  AvgCommunicate_67007_Content_4 = {
    Text = "Master, have you ever seen what a tangram looks like?"
  },
  AvgCommunicate_67007_Content_5 = {
    Text = "I have seen one before, but now that you mention it, I can't quite remember the shape either..."
  },
  AvgCommunicate_67007_Content_6 = {
    Text = "No worries. As an adult, I have a special superpower—a full wallet. I'll take you all shopping right away."
  },
  AvgCommunicate_67007_Content_7 = {
    Text = "Thank you, Master! I'll go tell Jenkin and Aigis!"
  },
  AvgCommunicate_67007_Content_8 = {
    Text = "Hey, Kiiper, Aigis said there's also a toy called a Rubik's Cube! It's got little colored squares you can twist and turn! We want that too!"
  },
  AvgCommunicate_67007_Content_9 = {
    Text = "And Aigis's doll is getting all worn out, so you need to buy her a new one!"
  },
  AvgCommunicate_67007_Option_11 = {
    Text = "Alright, alright! I'll buy it all! Everything!"
  },
  AvgCommunicate_67007_Option_14 = {Text = "What???"},
  AvgCommunicate_67007_Option_5 = {
    Text = "I have seen one before, but now that you mention it, I can't quite remember the shape either..."
  },
  AvgCommunicate_67008_Content_1 = {Text = "Ugh..."},
  AvgCommunicate_67008_Content_10 = {
    Text = "It seems the only thing left for a useless failure like me would be to crawl into a grave and die..."
  },
  AvgCommunicate_67008_Content_11 = {
    Text = "That's a bit of an extreme conclusion!"
  },
  AvgCommunicate_67008_Content_12 = {
    Text = "Listen, it's not your fault. You were deceived and preyed upon by those that sold you that remedy; they took advantage of your desperation."
  },
  AvgCommunicate_67008_Content_13 = {
    Text = "It's not a matter of you being unable to Awaken; you've been poisoned by quack medicine!"
  },
  AvgCommunicate_67008_Content_14 = {
    Text = "Is that so? What you're saying does make sense."
  },
  AvgCommunicate_67008_Content_15 = {
    Text = "So now you believe me?!"
  },
  AvgCommunicate_67008_Content_16 = {
    Text = "So I'm just sick? Then there is still hope for me to Awaken!"
  },
  AvgCommunicate_67008_Content_17 = {
    Text = "Yes, yes, that's right. So just relax and focus on getting better."
  },
  AvgCommunicate_67008_Content_18 = {
    Text = "I understand. Thank you, Keeper."
  },
  AvgCommunicate_67008_Content_19 = {
    Text = "So. Can you lend me fifty so I can see a doctor?"
