  AvgCommunicate_67015_Content_1 = {
    Text = "Keeper, the lectures I held on campus and the promotional pamphlets I printed have been very well received."
  },
  AvgCommunicate_67015_Content_10 = {
    Text = "Miss Sanga? I rarely see her. I've heard she's a brilliant sculptor."
