  AvgCommunicate_67023_Content_1 = {
    Text = "Keeper, lately I keep seeing strange spots before my eyes, plus dizziness, heart palpitations, chest tightness, ringing in my ears... Am I dying?!"
  },
  AvgCommunicate_67023_Content_10 = {
    Text = "No, you don't understand. That darkness is everywhere—no matter where I am, it will find me! I can't sleep, I can't close my eyes..."
  },
  AvgCommunicate_67023_Content_11 = {
    Text = "Uh... then why not hire someone to just knock you out? That way you lose consciousness and won't feel afraid."
  },
  AvgCommunicate_67023_Content_12 = {
    Text = "Huh? That actually makes some sense."
  },
  AvgCommunicate_67023_Content_13 = {
    Text = "Since destruction is coming no matter what, I might as well let myself die peacefully in blissful ignorance..."
  },
  AvgCommunicate_67023_Content_14 = {
    Text = "It's just getting knocked out—you're nowhere near dying!"
  },
  AvgCommunicate_67023_Content_15 = {
    Text = "Thank you, Keeper. Then I'll leave it in your hands. You're the only one I trust."
