  AvgCommunicate_67027_Content_1 = {
    Text = "Keeper, why doesn't anyone from Mythag ask me to fulfill their wishes anymore?"
  },
  AvgCommunicate_67027_Content_10 = {
    Text = "Instead of asking for it to be directly fulfilled, people want something to dream about; to look forward to."
  },
  AvgCommunicate_67027_Content_11 = {
    Text = "Even if their wishes don't immediately come true, the very act of wishing for something can bring comfort to them."
  },
  AvgCommunicate_67027_Content_12 = {
    Text = "Are wishes that can't be fulfilled right away... really that precious?"
  },
  AvgCommunicate_67027_Content_13 = {
    Text = "I think I understand now. Starting tomorrow, I will give everyone my blessings at the school's fountain."
  },
  AvgCommunicate_67027_Content_14 = {
    Text = "Wait, why the school fountain?"
  },
  AvgCommunicate_67027_Content_15 = {
    Text = "I heard that many places have a tradition of setting up wishing wells, so if I turn the school fountain into a wishing well, everyone can come and make a wish."
  },
  AvgCommunicate_67027_Content_16 = {
    Text = "I get the logic, but it's a little strange!"
  },
  AvgCommunicate_67027_Content_2 = {
    Text = "Mm... I suppose it's because people at Mythag are pragmatic."
  },
  AvgCommunicate_67027_Content_3 = {
    Text = "Having faced countless dangers every day, their spirits have become resillient enough to not rely on wishing to save them."
  },
  AvgCommunicate_67027_Content_4 = {
    Text = "...It seems I'm still too useless."
  },
  AvgCommunicate_67027_Content_5 = {
    Text = "No, no! It's not like everyone has completely stopped wishing for things."
  },
  AvgCommunicate_67027_Content_6 = {
    Text = "It's moreso that their wishes have become more abstract; longterm."
  },
  AvgCommunicate_67027_Content_7 = {
    Text = "Is that so?"
  },
  AvgCommunicate_67027_Content_8 = {
    Text = "I don't understand. What do you mean by abstract?"
  },
  AvgCommunicate_67027_Content_9 = {
    Text = "Things like passing exams, improving one's wealth, experiencing a sweet romance..."
  },
  AvgCommunicate_67027_Option_14 = {
    Text = "Wait, why the school fountain?"
