  AvgCommunicate_67032_Content_1 = {
    Text = "Oh puppy, it's so cold in the Black Pool. I can feel my life slowly draining away."
  },
  AvgCommunicate_67032_Content_10 = {
    Text = "Hmm... What if I say I've managed to loosen the device trapping me a little?"
  },
  AvgCommunicate_67032_Content_11 = {
    Text = "?! I'm coming now."
  },
  AvgCommunicate_67032_Content_2 = {
    Text = "If you don't visit me soon, I might melt away into D-Slime..."
  },
  AvgCommunicate_67032_Content_3 = {
    Text = "...I won't fall for your tricks anymore."
  },
  AvgCommunicate_67032_Content_4 = {
    Text = "How could you treat your mentor this way? I would never lie to my precious student."
  },
  AvgCommunicate_67032_Content_5 = {
    Text = "I still miss how you used to slack off in class and worry that I might catch you."
  },
  AvgCommunicate_67032_Content_6 = {
    Text = "Your righteous yet naive expression was so~ cute."
  },
  AvgCommunicate_67032_Content_7 = {
    Text = "Stop that or I'm turning my communicator off."
  },
  AvgCommunicate_67032_Content_8 = {
    Text = "How cold of you. Is there nothing I can say to have you visit me?"
  },
  AvgCommunicate_67032_Content_9 = {
    Text = "What do you think?"
  },
  AvgCommunicate_67032_Option_11 = {
