  AvgCommunicate_67033_Content_1 = {
    Text = "Ah, Watson, life is so dull."
  },
  AvgCommunicate_67033_Content_10 = {
    Text = "Don't tell me you actually lost to him?"
  },
  AvgCommunicate_67033_Content_11 = {
    Text = "No, neither of us was willing to back down. The stakes kept getting higher and higher, and we were both completely caught up in it."
  },
  AvgCommunicate_67033_Content_12 = {
    Text = "Then the old man got too excited and slipped up, and I discovered that he had actually been cheating the whole time."
  },
  AvgCommunicate_67033_Content_13 = {
    Text = "So you were dead even with a cheater this whole time?"
  },
  AvgCommunicate_67033_Content_14 = {
    Text = "Yeah, it was so disappointing. What's even more infuriating is that the old man flew into a rage and lunged at me, and we got into a scuffle."
  },
  AvgCommunicate_67033_Content_15 = {
    Text = "He actually suspected I was a fellow card sharp just like him! What an insult."
  },
  AvgCommunicate_67033_Content_16 = {
    Text = "In the end, we both got tossed out. My butt still hurts from the fall. What rotten luck."
  },
  AvgCommunicate_67033_Content_17 = {
    Text = "I don't know why, but I just can't seem to feel any sympathy..."
  },
  AvgCommunicate_67033_Content_2 = {
    Text = "Hmm? You must have gone gambling again. Did you win the pants off everyone again?"
  },
  AvgCommunicate_67033_Content_3 = {
    Text = "Not this time, really! I just went to the gambling den for some fun like usual... Ahem."
