  AvgCommunicate_67034_Content_13 = {Text = "Ramona."},
  AvgCommunicate_67034_Content_14 = {
    Text = "Understood. Switching personality simulation to: Ramona."
  },
  AvgCommunicate_67034_Content_15 = {
    Text = "Partner, a teacher just told me that you apparently didn't submit one of your assignments?"
  },
  AvgCommunicate_67034_Content_16 = {
    Text = "Huh? Really? I could've sworn I finished all my assignments..."
  },
  AvgCommunicate_67034_Content_17 = {
    Text = "When are you going to fix this habit of slacking off?"
  },
  AvgCommunicate_67034_Content_18 = {
    Text = "Forget it. Just come to my dorm every day from now on. I'll supervise you until you finish all your daily assignments before you leave. Oh, and no looking up answers or references."
  },
  AvgCommunicate_67034_Content_19 = {
    Text = "What?! No way! How am I supposed to do assignments without any references?!"
  },
  AvgCommunicate_67034_Content_2 = {
    Text = "You are invited to try the latest simulated personality system. This system will, when needed for missions, handle communications for absent members and mimic their thought patterns."
