  AvgCommunicate_67034_Content_22 = {
    Text = "Until the next system test, Keeper."
  },
  AvgCommunicate_67034_Content_3 = {
    Text = "Please share your feedback and suggestions once you have finished the trial."
  },
  AvgCommunicate_67034_Content_4 = {
    Text = "What kind of weird thing is this now?"
  },
  AvgCommunicate_67034_Content_5 = {
