  AvgCommunicate_67035_Content_11 = {
    Text = "Well... Alva's training sessions have recently been focused on training puppies to chase down enemies."
  },
  AvgCommunicate_67035_Content_12 = {
    Text = "If you don't mind being bitten by dogs, you can go play the villain there."
