  },
  AvgCommunicate_67035_Content_3 = {
    Text = "Oh come on, I really wasn't outside your room this time!"
  },
  AvgCommunicate_67035_Content_4 = {
    Text = "Thanks to your help last time, I spent a long time happily getting hit inside the sandbag in the training room. It felt like being at home—I've never been this happy before."
  },
  AvgCommunicate_67035_Content_5 = {
    Text = "Mm... you're welcome. As long as you're happy."
