  },
  AvgCommunicate_67036_Content_5 = {
    Text = "I can now schedule messages to be sent with a delay, and I can control exactly how long the delay is."
  },
  AvgCommunicate_67036_Content_6 = {
    Text = "Like, that first message I just sent? I actually wrote it five minutes ago as a test."
