  AvgCommunicate_67037_Content_10 = {Text = "Cold."},
  AvgCommunicate_67037_Content_11 = {Text = "Death."},
  AvgCommunicate_67037_Content_12 = {Text = "Song."},
  AvgCommunicate_67037_Content_13 = {Text = "Love."},
  AvgCommunicate_67037_Content_14 = {
    Text = "Melancholy."
  },
  AvgCommunicate_67037_Content_15 = {Text = "Fragrance."},
  AvgCommunicate_67037_Content_16 = {
    Text = "Hmm, I think that's enough. Let me try to weave them into a verse."
  },
  AvgCommunicate_67037_Content_17 = {
    Text = "The nightingale's love for the moon blooms night after night in its melodious song, yet the moon remains ever so cold."
  },
  AvgCommunicate_67037_Content_18 = {
    Text = "It sang and sang, until the rose pierced its heart."
  },
  AvgCommunicate_67037_Content_19 = {
    Text = "That song faded away with the crimson flow of death, leaving only the rose, only the rose exhaling a melancholy fragrance."
  },
  AvgCommunicate_67037_Content_2 = {
    Text = "What kind of game?"
  },
  AvgCommunicate_67037_Content_20 = {
    Text = "Stunning! I knew you could do it!"
  },
  AvgCommunicate_67037_Content_21 = {
    Text = "It's... it's just something I made up on the spot, it's nothing special..."
  },
  AvgCommunicate_67037_Content_22 = {
    Text = "If there is any beauty in these lines, half of it belongs to you."
  },
  AvgCommunicate_67037_Content_3 = {
    Text = "Everyone takes turns offering an image, and after several rounds, all the images are woven together into a verse."
  },
  AvgCommunicate_67037_Content_4 = {
    Text = "Full of the beauty of chance encounters, don't you think? Would you like to try it with me?"
