  AvgCommunicate_67038_Content_1 = {
    Text = "{Male=Mr.,Female=Miss} Keeper, the Tulu statue you asked me to make for Miryam has been delivered to your room."
  },
  AvgCommunicate_67038_Content_10 = {
    Text = "Her understanding of Tulu is even less than my understanding of you; how truly incompetent."
  },
  AvgCommunicate_67038_Content_11 = {
    Text = "Stop! Don't say that. Don't let her see it."
  },
  AvgCommunicate_67038_Content_12 = {
    Text = "Anyway, thank you for your hard work. Let me think about how to tell Miryam..."
  },
  AvgCommunicate_67038_Content_2 = {
    Text = "I saw it, but this image... isn't it a bit too cute?"
  },
  AvgCommunicate_67038_Content_3 = {
    Text = "Is this what Tulu actually looks like? Will Miryam strangle me..."
  },
  AvgCommunicate_67038_Content_4 = {
    Text = "What? Are you also a devout follower of the young King?"
  },
  AvgCommunicate_67038_Content_5 = {
    Text = "In my eyes, he was just a child, merely saddled with a crown and chains by others."
  },
  AvgCommunicate_67038_Content_6 = {
    Text = "Don't you think his drowsy, lazy look every day is adorable? He reminds me of the long-haired cat I had as a child."
  },
  AvgCommunicate_67038_Content_7 = {
    Text = "While you may have a point, and those who requested the statue will likely be satisfied..."
  },
  AvgCommunicate_67038_Content_8 = {
    Text = "The only bad news might be the creation of a world where only Miryam suffers..."
  },
  AvgCommunicate_67038_Content_9 = {
    Text = "That just shows she is a blind priestess who doesn't understand the God she worships."
  },
  AvgCommunicate_67038_Option_11 = {
    Text = "Stop! Don't say that. Don't let her see it."
  },
  AvgCommunicate_67038_Option_2 = {
    Text = "I saw it, but this image... isn't it a bit too cute?"
  },
  AvgCommunicate_67038_Option_7 = {
    Text = "While you may have a point, and those who requested the statue will likely be satisfied..."
  },
  AvgCommunicate_67039_Content_1 = {
    Text = "Dear Keeper, did you receive my latest work?"
  },
  AvgCommunicate_67039_Content_10 = {
    Text = "Such sudden praise... you're making me blush..."
  },
  AvgCommunicate_67039_Content_11 = {
    Text = "No need to be shy. You've always been my muse. When you have time, would you come visit my studio?"
  },
  AvgCommunicate_67039_Content_12 = {
    Text = "I have so many works I wish to complete. I need to carefully trace the contours of your soul."
  },
  AvgCommunicate_67039_Content_13 = {
    Text = "I will be here, waiting for you to grant me more inspiration."
  },
  AvgCommunicate_67039_Content_2 = {
    Text = "This is... me, asleep?"
  },
  AvgCommunicate_67039_Content_3 = {
    Text = "In my vision, this is you, sinking into a beautiful dream."
  },
  AvgCommunicate_67039_Content_4 = {
    Text = "To gain blind, false happiness, or lucid, painful descent?"
  },
  AvgCommunicate_67039_Content_5 = {
    Text = "Such a dilemma is an eternal theme in art and philosophy."
  },
  AvgCommunicate_67039_Content_6 = {
    Text = "Can't I have happiness that's both lucid and real?"
  },
  AvgCommunicate_67039_Content_7 = {
    Text = "Hmm, how greedy of you."
  },
  AvgCommunicate_67039_Content_8 = {
    Text = "Nothing is perfect. Perhaps not even sculpture can capture perfection."
  },
  AvgCommunicate_67039_Content_9 = {
    Text = "But you can always walk the path of pursuing such happiness. That is where your charm lies."
  },
  AvgCommunicate_67039_Option_10 = {
    Text = "Such sudden praise... you're making me blush..."
  },
  AvgCommunicate_67039_Option_2 = {
    Text = "This is... me, asleep?"
  },
  AvgCommunicate_67039_Option_6 = {
    Text = "Can't I have happiness that's both lucid and real?"
  },
  AvgCommunicate_67040_Content_1 = {
    Text = "Oh, sweetheart, how did you enjoy our little moment last time? I bet you've been replaying it in your head every day since?"
  },
  AvgCommunicate_67040_Content_10 = {
    Text = "Just say it, what are you up to this time..."
  },
  AvgCommunicate_67040_Content_11 = {
    Text = "Don't be so tense, we're already on such good terms~"
  },
  AvgCommunicate_67040_Content_12 = {
    Text = "Trust me, follow me, and I'll show you pleasures you've never even imagined."
  },
  AvgCommunicate_67040_Content_13 = {
    Text = "This time, would you like to personally experience how candles and little whips are used?"
  },
  AvgCommunicate_67040_Content_14 = {
    Text = "I'll teach you everything, step by step, bit by bit, darling."
  },
  AvgCommunicate_67040_Content_2 = {
    Text = "What little moment?"
  },
  AvgCommunicate_67040_Content_3 = {
    Text = "I don't remember."
  },
  AvgCommunicate_67040_Content_4 = {
    Text = "How cold~ I was so gentle with you last time~"
  },
  AvgCommunicate_67040_Content_5 = {
    Text = "I'd advise you to watch your words..."
  },
  AvgCommunicate_67040_Content_6 = {
    Text = "Hmph, playing dumb won't help! After all, I've already used wax to record every contour, every curve, every shape of yours!"
  },
  AvgCommunicate_67040_Content_7 = {
    Text = "I really want to show it off to everyone~"
  },
  AvgCommunicate_67040_Content_8 = {
    Text = "Don't you dare."
  },
  AvgCommunicate_67040_Content_9 = {
    Text = "Oh my, that all depends on how you treat me, sweetheart~ I'm very fragile, you know~"
  },
  AvgCommunicate_67040_Option_10 = {
    Text = "Just say it, what are you up to this time..."
  },
  AvgCommunicate_67040_Option_2 = {
    Text = "What little moment?"
  },
  AvgCommunicate_67040_Option_3 = {
    Text = "I don't remember."
  },
  AvgCommunicate_67040_Option_5 = {
    Text = "I'd advise you to watch your words..."
  },
  AvgCommunicate_67040_Option_8 = {
    Text = "Don't you dare."
  },
  AvgCommunicate_67041_Content_1 = {
    Text = "Master, you were just beckoning me over. Did you want to speak with me?"
  },
  AvgCommunicate_67041_Content_10 = {
    Text = "Sigh, I need to teach you how to spot troublemakers around campus... and give you some survival tips."
  },
  AvgCommunicate_67041_Content_11 = {
    Text = "Listen to me, leave her door right now. The farther you go, the better. Just tell her later that I called you away!"
  },
  AvgCommunicate_67041_Content_12 = {
    Text = "B-but I already promised Lady Pandia. I can't go back on my word."
  },
  AvgCommunicate_67041_Content_13 = {
    Text = "It's alright, my lord. I have the power to protect myself!"
  },
  AvgCommunicate_67041_Content_14 = {
    Text = "You... Ugh, forget it. If you insist on standing there, remember—never go into her room."
  },
  AvgCommunicate_67041_Content_15 = {
    Text = "Of course, I would never enter a lady's room!"
  },
  AvgCommunicate_67041_Content_16 = {
    Text = "No matter what she says, don't go in. Call me if anything happens. Oh, and whatever you do, don't smell her candles!"
  },
  AvgCommunicate_67041_Content_17 = {
    Text = "I'll remember that, my lord. But why can't I smell the candles?"
  },
  AvgCommunicate_67041_Content_18 = {
    Text = "Don't ask... Let's just say I learned that the hard way, and I'm trying to spare you the same fate."
  },
  AvgCommunicate_67041_Content_2 = {
    Text = "That's right. Why have you been standing outside Pandia's door??"
  },
  AvgCommunicate_67041_Content_3 = {
    Text = "Ah, Lady Pandia asked me to do this. She said she had some very important things to take care of and hoped I could keep watch outside her door."
  },
  AvgCommunicate_67041_Content_4 = {
    Text = "Something important? Don't fall for it. Her so-called matters... Forget it, she's definitely tricked you!"
  },
  AvgCommunicate_67041_Content_5 = {
    Text = "Huh? But she looked so serious just now, and she held my hand so earnestly..."
  },
  AvgCommunicate_67041_Content_6 = {
    Text = "Did she also hold your hand and call you the most reliable and gentle knight?"
  },
  AvgCommunicate_67041_Content_7 = {
    Text = "How did you know, my lord?!"
  },
  AvgCommunicate_67041_Content_8 = {
    Text = "Ogier, never trust a word that woman says! She'll have you wrapped around her finger before you know it!"
  },
