  AvgCommunicate_67043_Content_1 = {
    Text = "After all this time in Mythag, I suddenly find myself missing the moon over the desert."
  },
  AvgCommunicate_67043_Content_10 = {
    Text = "Come, let’s make new memories together—through blooming fields, across open plains, by the sea and valleys, in cities and quiet towns."
  },
  AvgCommunicate_67043_Content_11 = {
    Text = "I want to leave our mark in every beautiful place. You’ll stay by my side, won’t you?"
  },
  AvgCommunicate_67043_Content_2 = {
    Text = "So you get homesick too?"
  },
  AvgCommunicate_67043_Content_3 = {
    Text = "It’s less about homesickness, and more about nostalgia—cherishing the people I’ve met and the warmth of those shared moments."
  },
  AvgCommunicate_67043_Content_4 = {
    Text = "I didn't expect you to be so sentimental."
  },
  AvgCommunicate_67043_Content_5 = {
    Text = "What? You think I’m just a free-spirited wanderer with no attachments? I remember everyone I’ve met, and every sweet moment we’ve shared."
