  AvgCommunicate_70504_Content_13 = {
    Text = "My secret? What does that refer to?"
  },
  AvgCommunicate_70504_Content_14 = {
    Text = "Now is not the time. But rest assured, the trade involving the new secret will begin soon."
  },
  AvgCommunicate_70504_Content_15 = {
    Text = "The wind and snow on the road are more ferocious than you imagine."
  },
  AvgCommunicate_70504_Content_16 = {
    Text = "While there's time, enjoy the warmth of the fireplace, little one."
  },
  AvgCommunicate_70504_Content_2 = {
    Text = "Such a warm little shop is rare on a snowy day. Thank you for your hospitality, Lady Daffodil."
  },
  AvgCommunicate_70504_Content_3 = {
    Text = "However, your shop seems to conceal many secrets."
  },
  AvgCommunicate_70504_Content_4 = {
    Text = "Those collectibles are probably not as simple as they appear."
  },
  AvgCommunicate_70504_Content_5 = {
    Text = "Keen observation. However, prying into others' secrets is hardly polite."
  },
  AvgCommunicate_70504_Content_6 = {
    Text = "I'm sorry, Lady Daffodil."
  },
  AvgCommunicate_70504_Content_7 = {
