  AvgCommunicate_70504_Content_9 = {
    Text = "Of course. If one could carelessly fall asleep in a stranger's house, then Mythag's education for Keepers is evidently inadequate."
  },
  AvgCommunicate_70504_Option_13 = {Text = "My secret?"},
  AvgCommunicate_70504_Option_2 = {
    Text = "There seem to be many secrets here."
  },
  AvgCommunicate_70504_Option_6 = {
