    Text = "You misunderstand, my lord! What I wanted to ask you about is... the dream..."
  },
  AvgCommunicate_70511_Content_4 = {
    Text = "The \"dream\" I had?"
  },
  AvgCommunicate_70511_Content_5 = {
    Text = "Yes, my lord!"
  },
  AvgCommunicate_70511_Content_6 = {
    Text = "I want to know—what exactly did you see in that dream?"
  },
  AvgCommunicate_70511_Content_7 = {
    Text = "I saw a calamity, a kind princess, and a brave, resolute little knight."
  },
  AvgCommunicate_70511_Content_8 = {
    Text = "I also have a question I'd like to ask you."
  },
  AvgCommunicate_70511_Content_9 = {
    Text = "My lord, please go ahead."
  },
  AvgCommunicate_70511_Option_10 = {
    Text = "Between me and the Princess, who would you save first?"
  },
  AvgCommunicate_70511_Option_13 = {
    Text = "I know, you are a dutiful knight"
  },
  AvgCommunicate_70511_Option_18 = {Text = "No!"},
  AvgCommunicate_70511_Option_2 = {
    Text = "About riding horses on the field?"
  },
  AvgCommunicate_70511_Option_4 = {
    Text = "The \"dream\"?"
  },
  AvgCommunicate_70512_Content_1 = {
    Text = "It has been a long time since we last parted at Remouahe, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgCommunicate_70512_Content_10 = {
    Text = "The crumbling decay of this world is something you pampered people will never understand."
  },
  AvgCommunicate_70512_Content_11 = {
    Text = "The Supreme Will, the Original Creator, will bring ultimate purification to the world."
  },
  AvgCommunicate_70512_Content_12 = {
    Text = "I have no intention of targeting Mythag, but Mythag is blocking the path to the New World's Arrival."
  },
  AvgCommunicate_70512_Content_13 = {
    Text = "Rest assured, {Male=Mr.,Female=Miss} Keeper, my Lord won't abandon you for this."
  },
  AvgCommunicate_70512_Content_14 = {
    Text = "You will also become a member of the new world."
  },
  AvgCommunicate_70512_Content_15 = {
    Text = "He will show you all that brand-new future."
  },
  AvgCommunicate_70512_Content_16 = {
    Text = "At that time, He will hear your sincere confessions."
  },
  AvgCommunicate_70512_Content_17 = {
    Text = "You can also rest assured, Juliette."
  },
  AvgCommunicate_70512_Content_18 = {
    Text = "Your master won't have a chance to arrive."
  },
  AvgCommunicate_70512_Content_19 = {
    Text = "I will stop you. Definitely!"
  },
  AvgCommunicate_70512_Content_2 = {
    Text = "Juliette... what exactly do you want to do by breaking into Mythag?!"
  },
  AvgCommunicate_70512_Content_3 = {
    Text = "In Remouahe, I once spoke to you."
  },
  AvgCommunicate_70512_Content_4 = {
    Text = "Our God will create a better future for the world."
  },
  AvgCommunicate_70512_Content_5 = {
    Text = "Do you remember, Keeper?"
  },
  AvgCommunicate_70512_Content_6 = {
    Text = "Of course, I won't forget this important information."
  },
  AvgCommunicate_70512_Content_7 = {
    Text = "What does this have to do with Mythag?"
  },
  AvgCommunicate_70512_Content_8 = {
    Text = "I don't waste time on remembering your manipulative words."
  },
  AvgCommunicate_70512_Content_9 = {
    Text = "I have seen many hopelessly stubborn people, and I am not surprised."
  },
  AvgCommunicate_70512_Option_17 = {
    Text = "I will stop you."
  },
  AvgCommunicate_70512_Option_2 = {
