  },
  AvgCommunicate_70522_Content_1 = {
    Text = "Several land consolidations within Londinium are proceeding smoothly, and those troublesome contracts have been resolved."
  },
  AvgCommunicate_70522_Content_10 = {
    Text = "What? The {Male=Mr.,Female=Miss} Keeper of Mythag, could you possibly be a person who breaks their word?"
  },
  AvgCommunicate_70522_Content_11 = {
    Text = "Certainly not! It's just..."
  },
  AvgCommunicate_70522_Content_12 = {
    Text = "Heh... How childish of you. Though I can't see it, I bet your face must be flushed down to your neck right now while thinking about how to lie, correct?"
  },
  AvgCommunicate_70522_Content_13 = {
    Text = "Here's the deal. The item I promised to give to Mythag needs to be handed over by you. Is that reason sufficient?"
  },
  AvgCommunicate_70522_Content_14 = {Text = "But..."},
  AvgCommunicate_70522_Content_15 = {
    Text = "Alright, no more \"buts\"; it's decided."
  },
  AvgCommunicate_70522_Content_16 = {
    Text = "Alright, I promise you... It's my honor, Lady Sorel."
  },
  AvgCommunicate_70522_Content_17 = {
    Text = "That's better."
  },
  AvgCommunicate_70522_Content_18 = {
    Text = "Between us, there's no need for those formalities and mutual probing anymore."
  },
  AvgCommunicate_70522_Content_19 = {
    Text = "At 8 PM tonight, in the wine cellar of my manor. No one will stop you."
  },
  AvgCommunicate_70522_Content_2 = {
    Text = "All of this is thanks to your help, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgCommunicate_70522_Content_20 = {
    Text = "I'm waiting for you, my little knight."
  },
  AvgCommunicate_70522_Content_3 = {
    Text = "Those tedious business salons are finally coming to an end."
  },
  AvgCommunicate_70522_Content_4 = {
    Text = "While you have some free time, come over and have a drink with me?"
  },
  AvgCommunicate_70522_Content_5 = {
    Text = "Mythag students are prohibited from drinking..."
  },
  AvgCommunicate_70522_Content_6 = {
    Text = "Is that so? Professor Dexter didn't say that to me."
  },
  AvgCommunicate_70522_Content_7 = {
    Text = "Who made this rule? It needs to be changed."
  },
  AvgCommunicate_70522_Content_8 = {
    Text = "Ah, this..."
  },
  AvgCommunicate_70522_Content_9 = {
    Text = "You still owe me a drink. Remember?"
  },
  AvgCommunicate_70522_Option_11 = {
    Text = "Certainly not! It's just..."
  },
  AvgCommunicate_70522_Option_16 = {
    Text = "It is my honor, Lady Sorel."
  },
  AvgCommunicate_70522_Option_5 = {
    Text = "Mythag students are prohibited from drinking..."
  },
  AvgCommunicate_70523_Content_1 = {
    Text = "In the rush, I didn't have the chance to introduce the local customs and culture to all of you."
  },
  AvgCommunicate_70523_Content_10 = {
    Text = "As I mentioned before, I am but a messenger proclaiming the teachings of my Lord."
  },
  AvgCommunicate_70523_Content_11 = {
    Text = "Our God will create a better future for the world."
  },
  AvgCommunicate_70523_Content_12 = {
    Text = "Primitive groups like the Aram are also part of this future and remain our most loyal friends."
  },
  AvgCommunicate_70523_Content_13 = {
    Text = "Of course, I also understand {Male=Mr.,Female=Miss} Keeper's doubts."
  },
  AvgCommunicate_70523_Content_14 = {
    Text = "I believe that as long as we spend a little more time together, these doubts will naturally disappear."
  },
  AvgCommunicate_70523_Content_15 = {
    Text = "You have traveled a long way; please rest well."
  },
  AvgCommunicate_70523_Content_16 = {
    Text = "On behalf of Remouahe, I sincerely welcome your arrival, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgCommunicate_70523_Content_2 = {
    Text = "I wonder if {Male=Mr.,Female=Miss} Keeper has any questions for me?"
  },
  AvgCommunicate_70523_Content_3 = {
    Text = "I'm a bit curious about the customs here."
  },
  AvgCommunicate_70523_Content_4 = {
    Text = "Although the Aramite people have lived by herding for generations, away from industrial society, please do not regard them as uncivilized barbaric tribes."
  },
  AvgCommunicate_70523_Content_5 = {
    Text = "There are no rules here; feel free to interact with them."
  },
  AvgCommunicate_70523_Content_6 = {
    Text = "I believe everyone will soon feel the enthusiasm of the Aram people."
  },
  AvgCommunicate_70523_Content_7 = {
    Text = "It is quite strange for someone like you to exist in such a tribe, isn't it?"
  },
  AvgCommunicate_70523_Content_8 = {
    Text = "Answering the call of a dream to guide Aramites—this reason feels somewhat far-fetched."
  },
  AvgCommunicate_70523_Content_9 = {
    Text = "{Male=Mr.,Female=Miss} Keeper, please don't overthink it."
  },
  AvgCommunicate_70523_Option_3 = {
    Text = "I'm a bit curious about the customs here."
  },
  AvgCommunicate_70523_Option_7 = {
    Text = "I am very curious about you."
  },
  AvgCommunicate_70524_Content_1 = {
    Text = "Speaking of which, it has been a long time since we last collaborated after the wax museum."
  },
  AvgCommunicate_70524_Content_10 = {
    Text = "I hope this collaboration goes smoothly."
  },
  AvgCommunicate_70524_Content_11 = {
    Text = "With your help, it will definitely go smoothly!"
  },
  AvgCommunicate_70524_Content_2 = {
    Text = "You helped a lot with the Seafarer incident last time, Senior William!"
  },
  AvgCommunicate_70524_Content_3 = {
    Text = "...It was just driving, nothing particularly helpful about it."
  },
  AvgCommunicate_70524_Content_4 = {
    Text = "After all, assigning two aces to the same mission feels a bit wasteful."
  },
  AvgCommunicate_70524_Content_5 = {Text = "..."},
  AvgCommunicate_70524_Content_6 = {
    Text = "You really don't mind the awkwardness of saying that."
  },
  AvgCommunicate_70524_Content_7 = {
    Text = "You once saved me at the wax museum. I will repay that debt of gratitude."
  },
  AvgCommunicate_70524_Content_8 = {
    Text = "For this task, you and Ramona are operating in the open, which makes certain actions difficult."
  },
  AvgCommunicate_70524_Content_9 = {
    Text = "I will handle the investigation in the shadows."
  },
  AvgCommunicate_70524_Option_11 = {Text = "Certainly!"},
  AvgCommunicate_70524_Option_2 = {
    Text = "You helped a lot with the Seafarer incident last time, Senior William."
  },
  AvgCommunicate_70524_Option_4 = {
    Text = "After all, assigning two aces to the same mission is a bit wasteful."
  },
  AvgCommunicate_70525_Content_1 = {
    Text = "Ding ding ding!"
  },
  AvgCommunicate_70525_Content_10 = {
    Text = "I see. That works too."
  },
  AvgCommunicate_70525_Content_11 = {
    Text = "I hope next time you'll show some respect for the performance and refrain from bringing up something like \"the girl lived happily with her mother from then on\"!"
  },
  AvgCommunicate_70525_Content_2 = {
    Text = "So, {Male=Mr.,Female=Miss} Keeper? Aren't you amazed by Andy Johnson's stage setup!"
  },
  AvgCommunicate_70525_Content_3 = {
    Text = "While you did go a bit overboard..."
  },
  AvgCommunicate_70525_Content_4 = {
    Text = "But, I must say that the stage you arranged is truly impressive."
  },
  AvgCommunicate_70525_Content_5 = {
    Text = "The timing of the performance is also well executed."
  },
  AvgCommunicate_70525_Content_6 = {
    Text = "We are preparing for the next project."
  },
  AvgCommunicate_70525_Content_7 = {
    Text = "In that case, the setting and director for the next installment are up to you!"
  },
  AvgCommunicate_70525_Content_8 = {
    Text = "What? Does that not include the screenwriter?"
  },
  AvgCommunicate_70525_Content_9 = {
    Text = "Uh, Jenkin has some small ideas for the story of the Night Ranger..."
  },
  AvgCommunicate_70525_Option_3 = {
    Text = "It was great!"
  },
  AvgCommunicate_70525_Option_6 = {
    Text = "The next project will depend on you!"
  },
  AvgCommunicate_70525_Option_9 = {
    Text = "Jenkin has some small ideas for the story of the Night Ranger..."
  },
  AvgCommunicate_70526_Content_1 = {
    Text = "My collaboration with Herbert has come to an end."
  },
  AvgCommunicate_70526_Content_10 = {
    Text = "In short, I want to see a wider world."
  },
  AvgCommunicate_70526_Content_11 = {
    Text = "Lotan defeated me three times. I wonder, what else, beyond hatred, can grant someone such immense power."
  },
  AvgCommunicate_70526_Content_12 = {
    Text = "After I find the answer, I will return."
  },
  AvgCommunicate_70526_Content_13 = {
    Text = "By then, I hope you and Lotan are willing to be my opponents once more."
  },
  AvgCommunicate_70526_Content_14 = {
    Text = "As long as you are no longer an enemy, be it as an opponent or a teammate, you are welcome."
  },
  AvgCommunicate_70526_Content_15 = {
    Text = "I will convey this to Lotan. I think she would be very eager to see the new you."
  },
  AvgCommunicate_70526_Content_16 = {
    Text = "The ship has set sail."
  },
  AvgCommunicate_70526_Content_17 = {
    Text = "We will meet again. See you, Helot."
  },
  AvgCommunicate_70526_Content_2 = {
    Text = "I will no longer oppose you. This is my promise."
  },
  AvgCommunicate_70526_Content_3 = {
    Text = "After that battle, you just disappeared without a trace..."
  },
  AvgCommunicate_70526_Content_4 = {
    Text = "Herbert is our common enemy, and we are more than willing to turn foes into friends with you."
  },
  AvgCommunicate_70526_Content_5 = {
    Text = "If you wish to come, Mythag welcomes you at any time."
  },
  AvgCommunicate_70526_Content_6 = {
    Text = "I appreciate the thought. But I'm preparing to leave."
  },
  AvgCommunicate_70526_Content_7 = {
    Text = "Leaving? Where are you going?"
