  AvgCommunicate_70526_Content_8 = {
    Text = "Unclear. Perhaps it's a certain sea."
  },
  AvgCommunicate_70526_Content_9 = {
    Text = "Perhaps it's a certain mountain. I always hear it calling."
  },
  AvgCommunicate_70526_Option_14 = {
    Text = "I will pass this on to her."
  },
  AvgCommunicate_70526_Option_17 = {
    Text = "See you, Helot."
  },
  AvgCommunicate_70526_Option_3 = {
    Text = "You might consider coming to Mythag."
  },
  AvgCommunicate_70526_Option_7 = {
    Text = "Where are you going?"
  },
  AvgCommunicate_70527_Content_1 = {
    Text = "Aurita showed me the jellyfish she had raised."
  },
  AvgCommunicate_70527_Content_10 = {
    Text = "Because she fulfilled her greatest wish—to let you live a happy life."
  },
  AvgCommunicate_70527_Content_11 = {
    Text = "I want to see Mother smile like that."
  },
  AvgCommunicate_70527_Content_12 = {
    Text = "To make Mother happy, I will stay happy!"
