  AvgCommunicate_70529_Content_1 = {
    Text = "Hello, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgCommunicate_70529_Content_10 = {
    Text = "Of course. Right at this moment, a patient's condition suddenly worsened, and I need to deal with it immediately."
  },
  AvgCommunicate_70529_Content_11 = {
    Text = "Thank you for bringing Lily home. The lounge and refreshments have been prepared for everyone."
  },
  AvgCommunicate_70529_Content_12 = {
    Text = "Welcome to Rye Sanatorium, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgCommunicate_70529_Content_2 = {
