  },
  AvgCommunicate_70529_Content_5 = {
    Text = "Did Lily cause any trouble for everyone on this journey?"
  },
  AvgCommunicate_70529_Content_6 = {
    Text = "Please don't worry; Lily has been very obedient all along."
  },
  AvgCommunicate_70529_Content_7 = {
    Text = "Ms. Francis, regarding the sanatorium, I would like to..."
