  },
  AvgCommunicate_70530_Content_11 = {
    Text = "This most precious Seed will, sooner or later, belong to you."
  },
  AvgCommunicate_70530_Content_12 = {
    Text = "Don't worry, {Male=Mr.,Female=Miss} Keeper. That day won't keep you waiting for long."
