  },
  AvgCommunicate_70531_Content_2 = {
    Text = "How is Jenkin's awakening going?"
  },
  AvgCommunicate_70531_Content_3 = {
    Text = "The school's material library has prepared everything needed for her body, and the process of her Awakening is currently happening."
  },
  AvgCommunicate_70531_Content_4 = {
