  AvgCommunicate_70531_Content_6 = {
    Text = "Thank you, Keeper. Thank you..."
  },
  AvgCommunicate_70531_Content_7 = {
    Text = "You two saved us."
  },
  AvgCommunicate_70531_Content_8 = {
    Text = "She died for the sake of saving Mythag. Any investigator would do the same."
  },
  AvgCommunicate_70531_Content_9 = {
