  AvgCommunicate_70532_Content_1 = {Text = "Kiiper!"},
  AvgCommunicate_70532_Content_2 = {
    Text = "When will we go film again!"
  },
  AvgCommunicate_70532_Content_3 = {
    Text = "What, have you become addicted to the applause?"
  },
  AvgCommunicate_70532_Content_4 = {
    Text = "It's not that I'm addicted; it's that this city needs us!"
  },
  AvgCommunicate_70532_Content_5 = {
    Text = "This city is full of evil, in need of the Night Ranger and their asitsant!"
  },
  AvgCommunicate_70532_Content_6 = {
    Text = "I'll ask Doll if I can borrow the camera again."
  },
  AvgCommunicate_70532_Content_7 = {
    Text = "By the way, have you been attending literacy classes properly? How many typos have you made!"
  },
  AvgCommunicate_70532_Content_8 = {
    Text = "Mind your own business, West Welp!"
  },
  AvgCommunicate_70532_Content_9 = {
    Text = "This city needs us; the Night Ranger and their assistant are extremely busy!"
  },
  AvgCommunicate_70532_Option_3 = {
    Text = "Addicted to filming?"
  },
  AvgCommunicate_70532_Option_6 = {
    Text = "Let me go ask Doll..."
  },
  AvgCommunicate_70533_Content_1 = {
    Text = "Keeper, Keeper!"
  },
  AvgCommunicate_70533_Content_10 = {
    Text = "But why can't I remember them?"
  },
  AvgCommunicate_70533_Content_11 = {
    Text = "Puppy, Pony, Little Jellyfish... They were all once friends of Aurita."
  },
  AvgCommunicate_70533_Content_12 = {
    Text = "But one day, they had to go to a very distant place."
  },
  AvgCommunicate_70533_Content_13 = {
    Text = "They were afraid Aurita would be sad, so they took away Aurita's memories of them."
  },
  AvgCommunicate_70533_Content_14 = {
    Text = "Yet they still wished to stay by Aurita's side, so they left their bodies behind."
  },
  AvgCommunicate_70533_Content_15 = {
    Text = "These bodies turned into small clay dolls and were left in Aurita's Water Palace."
  },
  AvgCommunicate_70533_Content_16 = {
    Text = "...They have always cared for and accompanied you. That has never changed."
  },
  AvgCommunicate_70533_Content_17 = {
    Text = "I think I understand... but then again, maybe I don't..."
  },
  AvgCommunicate_70533_Content_18 = {
    Text = "But, Aurita knows! The things in the Water Palace are all good friends of Aurita."
  },
  AvgCommunicate_70533_Content_19 = {
    Text = "So Aurita will take good care of them and play with them every day!"
  },
  AvgCommunicate_70533_Content_2 = {
    Text = "Do you know what is inside Aurita's Water Palace?"
  },
  AvgCommunicate_70533_Content_3 = {
    Text = "Aurita, what do you think those are?"
  },
  AvgCommunicate_70533_Content_4 = {
    Text = "Umm... Aurita can't seem to remember..."
  },
  AvgCommunicate_70533_Content_5 = {
    Text = "It feels familiar, like... like..."
  },
  AvgCommunicate_70533_Content_6 = {Text = "Friends..."},
  AvgCommunicate_70533_Content_7 = {
    Text = "Aurita loves friends the most! But why can't Aurita remember them?"
  },
  AvgCommunicate_70533_Content_8 = {
    Text = "Those are all Aurita's friends."
  },
  AvgCommunicate_70533_Content_9 = {
    Text = "Friends? I love friends!"
  },
  AvgCommunicate_70533_Option_11 = {
    Text = "Tell Aurita her story."
  },
  AvgCommunicate_70533_Option_3 = {
    Text = "Well, what do you think?"
  },
  AvgCommunicate_70533_Option_8 = {
    Text = "Those are all Aurita's friends."
  },
  AvgCommunicate_72037_Content_1 = {
    Text = "Yesterday, This One dreamt of childhood—of many faces from Lemuria's past."
  },
  AvgCommunicate_72037_Content_10 = {
    Text = "Nothing escapes your notice."
  },
  AvgCommunicate_72037_Content_11 = {
    Text = "What lingered in the dream was an exceptionally warm and familiar feeling. I initially thought it was brought by Noah."
  },
  AvgCommunicate_72037_Content_12 = {
    Text = "Later, I realized that over the long years, the most familiar thing to me was no longer any person, but a cold, lifeless object."
  },
  AvgCommunicate_72037_Content_13 = {Text = "Tulu..."},
  AvgCommunicate_72037_Content_14 = {
    Text = "Put away your sympathy. From the moment I donned the crown, all was already decided."
  },
  AvgCommunicate_72037_Content_15 = {
    Text = "The King of Lemuria does not need anyone to shed tears for him."
  },
  AvgCommunicate_72037_Content_16 = {
    Text = "So... Great King of Lemuria, are you interested in tasting that rice candy again? I think Mythag's chef should be able to recreate it to some extent."
  },
  AvgCommunicate_72037_Content_17 = {Text = "..."},
  AvgCommunicate_72037_Content_18 = {
    Text = "Hmph. That's considerate of you."
  },
  AvgCommunicate_72037_Content_19 = {
    Text = "Very well, then. I shall accept it as your offering."
  },
  AvgCommunicate_72037_Content_2 = {
    Text = "Those are the memories I never liked to speak of, but... in yesterday's dream, you were there, weren't you?"
  },
  AvgCommunicate_72037_Content_3 = {
    Text = "?! How did you know that?"
  },
  AvgCommunicate_72037_Content_4 = {
    Text = "The time I've spent in the dream far exceeds that in the ordinary world. Are you questioning the perception of someone who lives in a dream?"
  },
  AvgCommunicate_72037_Content_5 = {
    Text = "Besides prophecies, I sometimes have dreams like ordinary people, but none of those dreams are as vivid and continuous as yesterday's..."
  },
  AvgCommunicate_72037_Content_6 = {
    Text = "It was as though someone was sitting beside me, reliving the past from the very beginning."
  },
  AvgCommunicate_72037_Content_7 = {
    Text = "This feeling of not being alone... it's quite pleasant."
  },
  AvgCommunicate_72037_Content_8 = {
    Text = "I have indeed always been by your side."
  },
  AvgCommunicate_72037_Content_9 = {
    Text = "Let me guess: you must have been possessing the crown, correct?"
  },
  AvgCommunicate_72037_Option_10 = {Text = "Yes."},
  AvgCommunicate_72037_Option_13 = {Text = "Tulu..."},
  AvgCommunicate_72037_Option_16 = {Text = "So..."},
  AvgCommunicate_72037_Option_3 = {Text = "?!"},
  AvgCommunicate_72037_Option_8 = {
    Text = "I have indeed always been by your side."
  },
  AvgCommunicate_80100_Content_1 = {
    Text = "%player%, if you have a moment, would you mind taking a psychological test?"
  },
  AvgCommunicate_80100_Content_10 = {
    Text = "Ramona, Lotan, Ogier... when I'm alone, their figures always float in my mind."
  },
  AvgCommunicate_80100_Content_11 = {
    Text = "That's it, don't bottle all of those feelings inside. If you're feeling troubled or confused, you can always tell me."
  },
  AvgCommunicate_80100_Content_12 = {
    Text = "I even prepared hot tea and snacks for you, so we can chat as long as you want."
  },
  AvgCommunicate_80100_Content_13 = {
    Text = "...alright, I'm coming over."
  },
  AvgCommunicate_80100_Content_2 = {
    Text = "...A psychological test?"
  },
  AvgCommunicate_80100_Content_3 = {
    Text = "It's very simple. All you need to do is draw a house, a tree, and a person on a blank sheet of paper."
  },
  AvgCommunicate_80100_Content_4 = {
    Text = "Trust me, it won't take up too much of your time."
  },
  AvgCommunicate_80100_Content_5 = {
    Text = "...But I think my mental health is perfectly fine."
  },
  AvgCommunicate_80100_Content_6 = {
    Text = "The ultimate purpose of the test is not to judge health, but to observe potential psychological issues."
  },
  AvgCommunicate_80100_Content_7 = {
    Text = "%player%, after coming here, do you feel lonely? Do you miss your friends from that world?"
  },
  AvgCommunicate_80100_Content_8 = {
    Text = "This loneliness and solitude will be buried deep within your heart, festering over time with unpredictable consequences."
  },
  AvgCommunicate_80100_Content_9 = {
    Text = "I suppose I do miss them..."
  },
  AvgCommunicate_80100_Option_13 = {
    Text = "...alright, I'm coming over."
  },
  AvgCommunicate_80100_Option_2 = {
    Text = "...A psychological test?"
  },
  AvgCommunicate_80100_Option_5 = {
    Text = "...But I think my mental health is perfectly fine."
  },
  AvgCommunicate_80100_Option_9 = {Text = "..."},
  AvgCommunicate_80101_Content_1 = {
    Text = "I heard you've been feeling down lately. If you don't mind, you can come to me for a consultation."
  },
  AvgCommunicate_80101_Content_10 = {
    Text = "Ah~, just describing it makes my silver heart tremble non-stop..."
  },
  AvgCommunicate_80101_Content_11 = {
    Text = "%player%, I can't wait to delve into your heart and taste your memories."
  },
  AvgCommunicate_80101_Content_12 = {
    Text = "Then you'll be dissappointed, since I've already left."
  },
  AvgCommunicate_80101_Content_13 = {
    Text = "I know. One of my patients already let me know."
  },
  AvgCommunicate_80101_Content_14 = {
    Text = "She was even thoughtful enough to send me your location, so..."
  },
  AvgCommunicate_80101_Content_15 = {
    Text = "I will be there shortly."
  },
  AvgCommunicate_80101_Content_2 = {
    Text = "You don't need to act tough, Keeper. A professional can help relieve your stress more quickly."
  },
  AvgCommunicate_80101_Content_3 = {
    Text = "How did you know...?"
  },
  AvgCommunicate_80101_Content_4 = {Text = "Secret~"},
  AvgCommunicate_80101_Content_5 = {
    Text = "So, what's your answer?"
  },
  AvgCommunicate_80101_Content_6 = {
    Text = "I promise I won't do anything else this time."
  },
  AvgCommunicate_80101_Content_7 = {
    Text = "You said the same last time... and the time before that..."
  },
  AvgCommunicate_80101_Content_8 = {
    Text = "It's not my fault; rather, your conciousness that's filled with such pleasant memories..."
  },
  AvgCommunicate_80101_Content_9 = {
    Text = "Those memories that far exceed the pain that an ordinary person can endure, bearing the aura of that great existence, the most supreme sweetness..."
  },
  AvgCommunicate_80101_Option_12 = {
    Text = "...Then you'll be disappointed."
  },
  AvgCommunicate_80101_Option_3 = {
    Text = "How did you know...?"
  },
  AvgCommunicate_80101_Option_7 = {
    Text = "You said the same last time... and the time before that..."
  },
  AvgCommunicate_80102_Content_1 = {
    Text = "%player%, if you don't mind, could I take care of your psychological needs?"
  },
  AvgCommunicate_80102_Content_10 = {
    Text = "But I won't do anything extreme. Trust me."
  },
  AvgCommunicate_80102_Content_11 = {Text = "...Really?"},
  AvgCommunicate_80102_Content_12 = {
    Text = "Of course. After all, I'm only a psychologist."
  },
  AvgCommunicate_80102_Content_2 = {
    Text = "I think you need a personal psychiatrist."
  },
  AvgCommunicate_80102_Content_3 = {
    Text = "...I feel like this is unnecessary."
  },
  AvgCommunicate_80102_Content_4 = {
    Text = "No, as the only Keeper, your existence itself is worth valuing."
  },
  AvgCommunicate_80102_Content_5 = {
    Text = "I just want to use my professional skills to help you."
  },
  AvgCommunicate_80102_Content_6 = {
    Text = "Is that right? Why do I feel like you have ulterior motives..."
  },
  AvgCommunicate_80102_Content_7 = {
    Text = "For example, using the guise of a personal psychologist to peer into my memories?"
  },
  AvgCommunicate_80102_Content_8 = {
    Text = "Oh dear, was it that obvious? Oh well, nothing I can do about that."
  },
  AvgCommunicate_80102_Content_9 = {
    Text = "I am indeed very, very interested in your memories, especially after you spoke about that world."
  },
  AvgCommunicate_80102_Option_11 = {Text = "...Really?"},
  AvgCommunicate_80102_Option_3 = {
    Text = "...I feel like this is unnecessary."
  },
  AvgCommunicate_80102_Option_6 = {
    Text = "...Is that right?"
  },
  AvgCommunicate_80104_Content_1 = {
    Text = "Thank you for sending me that report."
  },
  AvgCommunicate_80104_Content_10 = {
    Text = "As for whether it's possible to return to that world, relying solely on the power of Doll: Inferno and I is clearly not enough."
  },
  AvgCommunicate_80104_Content_11 = {
    Text = "So you need my power...? I understand."
  },
  AvgCommunicate_80104_Content_12 = {
    Text = "I'll accept this gift. In return, I'll give you a free psychological consultation."
  },
  AvgCommunicate_80104_Content_13 = {
    Text = "%player%, when do you have free time?"
  },
  AvgCommunicate_80104_Content_14 = {
    Text = "Whether as a doctor or as a friend, I feel responsible for deeply understanding your inner self."
  },
  AvgCommunicate_80104_Content_15 = {
    Text = "I'm on field duty... signal poor... will continue later..."
  },
  AvgCommunicate_80104_Content_16 = {Text = "%player%?"},
  AvgCommunicate_80104_Content_17 = {Text = "%player%?"},
  AvgCommunicate_80104_Content_18 = {
    Text = "Heh, I know you're still there. But it's okay, we still have plenty of time."
  },
  AvgCommunicate_80104_Content_2 = {
    Text = "That's a brief version of my report on insect species. There's nothing on it that's classified, so feel free to keep it."
  },
  AvgCommunicate_80104_Content_3 = {
    Text = "Is this the \"reward\" paid in advance?"
  },
  AvgCommunicate_80104_Content_4 = {
    Text = "But sorry, I don't have any insider information from the Committee to share recently."
  },
  AvgCommunicate_80104_Content_5 = {
    Text = "It's a gift, not a reward."
  },
  AvgCommunicate_80104_Content_6 = {
    Text = "Congratulations on your rebirth, and thank you for choosing me."
  },
  AvgCommunicate_80104_Content_7 = {
    Text = "Because I'm not opposing you like \"her\" from the other world?"
  },
  AvgCommunicate_80104_Content_8 = {
    Text = "You can think of it that way."
  },
  AvgCommunicate_80104_Content_9 = {
    Text = "As the Keeper, I'd like to believe that the Awakeners and I are allies, not enemies."
  },
  AvgCommunicate_80104_Option_15 = {
    Text = "...signals cutting out..."
  },
  AvgCommunicate_80104_Option_2 = {
    Text = "I guess you got the mail then."
  },
  AvgCommunicate_80104_Option_5 = {
    Text = "No, this is a Gift."
  },
  AvgCommunicate_80104_Option_8 = {
    Text = "You can think of it that way."
